window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[11]={"numero": 11, "titulo": "El yoga de la visión de la forma universal", "versos": [{"n": 1, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "मदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम् ।", "यत्त्वयोक्तं वचस्तेन मोहोऽयं विगतो मम ॥१॥"], "iast": ["arjuna uvāca", "mad-anugrahāya paramaṃ guhyam adhyātma-saṃjñitam", "yat tvayoktaṃ vacas tena moho 'yaṃ vigato mama"], "rojas": [], "t": "<span class=\"vt-parte\">Por favorecerme, me has dicho la palabra suprema y secreta que trata de <a class=\"t\" href=\"glosario.html#adhyatma\" data-t=\"adhyatma\">lo relativo al sí-mismo</a>; con ella se ha disipado este <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a> mío.</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "mad-anugrahāya", "sa": "मदनुग्रहाय", "gram": "dat. sg. m. comp.", "es": "por favorecerme", "analisis": "mad (yo) + anugraha (favor, gracia), de anu-√grah (acoger, favorecer)"}, {"iast": "paramam", "sa": "परमम्", "gram": "nom. sg. n.", "es": "supremo"}, {"iast": "guhyam", "sa": "गुह्यम्", "gram": "nom. sg. n.", "es": "secreto", "analisis": "de √guh (ocultar)"}, {"iast": "adhyātma-saṃjñitam", "sa": "अध्यात्मसंज्ञितम्", "gram": "nom. sg. n. comp.", "es": "que se llama «lo relativo al sí-mismo»", "ref": "adhyatma", "analisis": "adhyātma (lo relativo al sí-mismo) + saṃjñita (llamado, designado)"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. pron. rel.", "es": "que"}, {"iast": "tvayā", "sa": "त्वया", "gram": "instr. sg. pron.", "es": "por ti"}, {"iast": "uktam", "sa": "उक्तम्", "gram": "nom. sg. n. ppp.", "es": "dicho", "analisis": "√vac (hablar)"}, {"iast": "vacaḥ", "sa": "वचः", "gram": "nom. sg. n.", "es": "palabra, discurso", "analisis": "vacas, de √vac"}, {"iast": "tena", "sa": "तेन", "gram": "instr. sg. n. pron.", "es": "con ello"}, {"iast": "mohaḥ", "sa": "मोहः", "gram": "nom. sg. m.", "es": "extravío", "ref": "moha"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "este"}, {"iast": "vigataḥ", "sa": "विगतः", "gram": "nom. sg. m. ppp.", "es": "se ha ido, se ha disipado", "analisis": "vi-√gam (alejarse)"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mío"}], "nota": "<p><em>Mad-anugrahāya</em>, «para favorecerme»: Arjuna reconoce que la enseñanza ha sido una gracia, no una deuda; es la misma idea de <a class=\"vref\" href=\"capitulo-10.html#v1\" data-v=\"10.1\">10.1</a> y <a class=\"vref\" href=\"capitulo-10.html#v11\" data-v=\"10.11\">10.11</a>, donde Kṛṣṇa habla por el bien de Arjuna y por compasión. <em>Adhyātma-saṃjñitam</em>, «lo que se llama <em>adhyātma</em>», es el término que el capítulo 8 definió como la naturaleza propia, el sí-mismo (<a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a>). A qué parte de la enseñanza se refiere Arjuna no lo precisa el verso: <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> sólo dice que es la que discierne el sí-mismo de lo que no lo es; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la limitan a los capítulos 2 a 6, y refieren el verso siguiente a lo dicho después; Vallabha, en cambio, la entiende de lo dicho en el capítulo 10 (<a class=\"vref\" href=\"capitulo-10.html#v8\" data-v=\"10.8\">10.8</a>), y Viśvanātha Cakravartī, de lo que Kṛṣṇa ha dicho de sus manifestaciones. El primer pie tiene nueve sílabas en lugar de ocho (<em>mad-anugrahāya paramam</em>): es una irregularidad del metro que trae así el texto transmitido.</p>", "interp": [{"titulo": "Un extravío que se dice disipado", "html": "<p>Arjuna afirma que su extravío se ha ido, pero el capítulo mostrará que la visión todavía puede espantarlo (<a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>). Sólo al final del poema volverá a decirlo, ya sin vuelta atrás y con las mismas palabras de fondo: «se ha destruido mi extravío, he recobrado la memoria» (<a class=\"vref\" href=\"capitulo-18.html#v73\" data-v=\"18.73\">18.73</a>). Entre las dos declaraciones queda todo lo que falta por enseñar.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh con un pie hipermétrico (nueve sílabas)"}, {"n": 2, "hablante": "arjuna", "sa": ["भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया ।", "त्वत्तः कमलपत्राक्ष माहात्म्यमपि चाव्ययम् ॥२॥"], "iast": ["bhavāpyayau hi bhūtānāṃ śrutau vistaraśo mayā", "tvattaḥ kamala-patrākṣa māhātmyam api cāvyayam"], "rojas": [], "t": "<span class=\"vt-parte\">Porque de ti he oído con detalle el origen y la disolución de los seres, oh tú, de ojos como pétalos de loto, y también tu grandeza imperecedera.</span>", "palabras": [{"iast": "bhava-apyayau", "sa": "भवाप्ययौ", "gram": "nom. du. m. comp.", "es": "el origen y la disolución", "analisis": "bhava (llegar a ser, origen) + apyaya (disolución, retorno), de api-√i (entrar en)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque, en efecto"}, {"iast": "bhūtānām", "sa": "भूतानाम्", "gram": "gen. pl. n.", "es": "de los seres"}, {"iast": "śrutau", "sa": "श्रुतौ", "gram": "nom. du. m. ppp.", "es": "han sido oídos", "analisis": "√śru (oír)"}, {"iast": "vistaraśaḥ", "sa": "विस्तरशः", "gram": "adv.", "es": "con detalle, por extenso"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "tvattaḥ", "sa": "त्वत्तः", "gram": "abl. sg. pron.", "es": "de ti"}, {"iast": "kamala-patra-akṣa", "sa": "कमलपत्राक्ष", "gram": "voc. sg. m. comp.", "es": "de ojos como pétalos de loto", "analisis": "kamala (loto) + patra (pétalo, hoja) + akṣa (ojo)"}, {"iast": "māhātmyam", "sa": "माहात्म्यम्", "gram": "nom. sg. n.", "es": "grandeza", "analisis": "de mahātman (grande de alma)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "nom. sg. n.", "es": "imperecedero"}], "nota": "<p>Arjuna resume, según <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, lo que ha escuchado en los capítulos 7 a 10: que Kṛṣṇa es el origen y la disolución del mundo (<a class=\"vref\" href=\"capitulo-07.html#v6\" data-v=\"7.6\">7.6</a>, <a class=\"vref\" href=\"capitulo-09.html#v7\" data-v=\"9.7\">9.7</a>–<a class=\"vref\" href=\"capitulo-09.html#v8\" data-v=\"9.8\">9.8</a>, <a class=\"vref\" href=\"capitulo-10.html#v8\" data-v=\"10.8\">10.8</a>) y su grandeza, desplegada en la lista de sus manifestaciones. <em>Kamala-patrākṣa</em>, «el de ojos como pétalos de loto», es un epíteto de belleza que la tradición aplica a Kṛṣṇa y a Viṣṇu; se traduce en el texto, como otros vocativos descriptivos (<a class=\"vref\" href=\"capitulo-08.html#v4\" data-v=\"8.4\">8.4</a>).</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 3, "hablante": "arjuna", "sa": ["एवमेतद्यथात्थ त्वमात्मानं परमेश्वर ।", "द्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम ॥३॥"], "iast": ["evam etad yathāttha tvam ātmānaṃ parameśvara", "draṣṭum icchāmi te rūpam aiśvaraṃ puruṣottama"], "rojas": [], "t": "<span class=\"vt-parte\">Así es, tal como tú dices de ti mismo, oh Señor supremo. Quiero ver tu <a class=\"t\" href=\"glosario.html#visvarupa\" data-t=\"visvarupa\">forma soberana</a>, oh <a class=\"t\" href=\"glosario.html#purusottama\" data-t=\"purusottama\">Puruṣottama</a>.</span>", "palabras": [{"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "etat", "sa": "एतत्", "gram": "nom. sg. n. pron.", "es": "esto"}, {"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "como"}, {"iast": "āttha", "sa": "आत्थ", "gram": "2 sg. pf. act.", "es": "dices", "analisis": "√ah (decir), perfecto con valor de presente"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "acc. sg. m.", "es": "a ti mismo", "analisis": "ātman como reflexivo"}, {"iast": "parama-īśvara", "sa": "परमेश्वर", "gram": "voc. sg. m. comp.", "es": "oh Señor supremo", "analisis": "parama (supremo) + īśvara (señor)"}, {"iast": "draṣṭum", "sa": "द्रष्टुम्", "gram": "inf.", "es": "ver", "analisis": "√dṛś (ver)"}, {"iast": "icchāmi", "sa": "इच्छामि", "gram": "1 sg. pres. act.", "es": "quiero", "analisis": "√iṣ (desear)"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "acc. sg. n.", "es": "forma", "ref": "visvarupa"}, {"iast": "aiśvaram", "sa": "ऐश्वरम्", "gram": "acc. sg. n.", "es": "soberana, propia del Señor", "analisis": "de īśvara (señor)"}, {"iast": "puruṣa-uttama", "sa": "पुरुषोत्तम", "gram": "voc. sg. m. comp.", "es": "oh Persona suprema", "ref": "purusottama", "analisis": "puruṣa (persona) + uttama (el más alto)"}], "nota": "<p><em>Evam etad</em>, «así es»: Arjuna no pide ver para comprobar lo que ha oído; lo da por cierto y desea verlo. <em>Aiśvaram rūpam</em>, «la forma soberana», la que corresponde al Señor (<em>īśvara</em>): el mismo adjetivo que en «mi yoga soberano» (<a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>, <a class=\"vref\" href=\"capitulo-11.html#v8\" data-v=\"11.8\">11.8</a>). Con este verso Arjuna lleva más lejos la petición de <a class=\"vref\" href=\"capitulo-10.html#v18\" data-v=\"10.18\">10.18</a>: allí pedía que Kṛṣṇa le hablara de sus manifestaciones; ahora, ver.</p>", "interp": [{"titulo": "De oír a ver", "html": "<p>Hasta aquí todo ha sido palabra: Arjuna ha oído (<em>śrutau</em>, <a class=\"vref\" href=\"capitulo-11.html#v2\" data-v=\"11.2\">11.2</a>). Ahora pide ver (<em>draṣṭum</em>), y el verbo «ver» domina el capítulo entero: Kṛṣṇa responde con un «mira» repetido (<a class=\"vref\" href=\"capitulo-11.html#v5\" data-v=\"11.5\">11.5</a>–<a class=\"vref\" href=\"capitulo-11.html#v8\" data-v=\"11.8\">11.8</a>), Sañjaya describe lo que Arjuna vio (<a class=\"vref\" href=\"capitulo-11.html#v9\" data-v=\"11.9\">11.9</a>–<a class=\"vref\" href=\"capitulo-11.html#v13\" data-v=\"11.13\">11.13</a>) y Arjuna mismo lo cuenta en primera persona. El paso de la escucha a la visión es el eje del capítulo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 4, "hablante": "arjuna", "sa": ["मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो ।", "योगेश्वर ततो मे त्वं दर्शयात्मानमव्ययम् ॥४॥"], "iast": ["manyase yadi tac chakyaṃ mayā draṣṭum iti prabho", "yogeśvara tato me tvaṃ darśayātmānam avyayam"], "rojas": [], "t": "<span class=\"vt-parte\">Si crees, oh Señor, que puedo verla, entonces, oh Señor del yoga, muéstrame tu ser imperecedero.</span>", "palabras": [{"iast": "manyase", "sa": "मन्यसे", "gram": "2 sg. pres. med.", "es": "crees", "analisis": "√man (pensar)"}, {"iast": "yadi", "sa": "यदि", "gram": "ind.", "es": "si"}, {"iast": "tat", "sa": "तत्", "gram": "nom. sg. n. pron.", "es": "eso"}, {"iast": "śakyam", "sa": "शक्यम्", "gram": "nom. sg. n.", "es": "posible", "analisis": "de √śak (poder)"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "draṣṭum", "sa": "द्रष्टुम्", "gram": "inf.", "es": "ver", "analisis": "√dṛś (ver)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (marca de lo pensado)"}, {"iast": "prabho", "sa": "प्रभो", "gram": "voc. sg. m.", "es": "oh Señor", "analisis": "prabhu (señor, el que puede)"}, {"iast": "yoga-īśvara", "sa": "योगेश्वर", "gram": "voc. sg. m. comp.", "es": "oh Señor del yoga", "analisis": "yoga + īśvara (señor)"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "entonces"}, {"iast": "me", "sa": "मे", "gram": "dat. sg. pron.", "es": "a mí"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "darśaya", "sa": "दर्शय", "gram": "2 sg. impv. caus.", "es": "muestra", "analisis": "causativo de √dṛś (ver): hacer ver"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "acc. sg. m.", "es": "a ti mismo, tu ser"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "acc. sg. m.", "es": "imperecedero"}], "nota": "<p>Arjuna condiciona su ruego al juicio de Kṛṣṇa: sólo si él cree que es posible. <em>Yogeśvara</em>, «Señor del yoga», el dueño de ese poder que el capítulo 9 llamó «mi yoga soberano» (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo glosan, en cambio, «señor de los yoguis»): Arjuna lo usa aquí por primera vez, y Sañjaya lo repetirá al narrar la visión (<a class=\"vref\" href=\"capitulo-11.html#v9\" data-v=\"11.9\">11.9</a>) y al cerrar el poema (<a class=\"vref\" href=\"capitulo-18.html#v75\" data-v=\"18.75\">18.75</a>, <a class=\"vref\" href=\"capitulo-18.html#v78\" data-v=\"18.78\">18.78</a>). <em>Ātmānam avyayam</em>, literalmente «a ti mismo, el imperecedero»: Arjuna no pide un espectáculo, sino ver a Kṛṣṇa tal como es.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 5, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "पश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः ।", "नानाविधानि दिव्यानि नानावर्णाकृतीनि च ॥५॥"], "iast": ["śrī-bhagavān uvāca", "paśya me pārtha rūpāṇi śataśo 'tha sahasraśaḥ", "nānā-vidhāni divyāni nānā-varṇākṛtīni ca"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Mira, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, mis formas, por cientos y por miles: divinas, de muchas clases, de muchos colores y figuras.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "paśya", "sa": "पश्य", "gram": "2 sg. impv. act.", "es": "mira", "analisis": "√paś (ver)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mis"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "rūpāṇi", "sa": "रूपाणि", "gram": "acc. pl. n.", "es": "formas"}, {"iast": "śataśaḥ", "sa": "शतशः", "gram": "adv.", "es": "por cientos"}, {"iast": "atha", "sa": "अथ", "gram": "ind.", "es": "y también"}, {"iast": "sahasraśaḥ", "sa": "सहस्रशः", "gram": "adv.", "es": "por miles"}, {"iast": "nānā-vidhāni", "sa": "नानाविधानि", "gram": "acc. pl. n. comp.", "es": "de muchas clases", "analisis": "nānā (diverso) + vidhā (clase, modo)"}, {"iast": "divyāni", "sa": "दिव्यानि", "gram": "acc. pl. n.", "es": "divinas"}, {"iast": "nānā-varṇa-ākṛtīni", "sa": "नानावर्णाकृतीनि", "gram": "acc. pl. n. comp.", "es": "de muchos colores y figuras", "analisis": "nānā (diverso) + varṇa (color) + ākṛti (figura)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}], "nota": "<p>Kṛṣṇa no responde con palabras, sino con una orden: «mira» (<em>paśya</em>), que se repite cinco veces en cuatro versos (<a class=\"vref\" href=\"capitulo-11.html#v5\" data-v=\"11.5\">11.5</a>–<a class=\"vref\" href=\"capitulo-11.html#v8\" data-v=\"11.8\">11.8</a>). <em>Varṇa</em> es aquí «color», su sentido primero, y no la clase social que la palabra designa en otros lugares (<a class=\"vref\" href=\"capitulo-04.html#v13\" data-v=\"4.13\">4.13</a>).</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-ojo-divino"}, {"n": 6, "hablante": "krsna", "sa": ["पश्यादित्यान्वसून्रुद्रानश्विनौ मरुतस्तथा ।", "बहून्यदृष्टपूर्वाणि पश्याश्चर्याणि भारत ॥६॥"], "iast": ["paśyādityān vasūn rudrān aśvinau marutas tathā", "bahūny adṛṣṭa-pūrvāṇi paśyāścaryāṇi bhārata"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Mira a los <a class=\"t\" href=\"glosario.html#aditya\" data-t=\"aditya\">Ādityas</a>, a los <a class=\"t\" href=\"glosario.html#vasu\" data-t=\"vasu\">Vasus</a>, a los <a class=\"t\" href=\"glosario.html#rudra\" data-t=\"rudra\">Rudras</a>, a los dos <a class=\"t\" href=\"glosario.html#asvins\" data-t=\"asvins\">Aśvins</a> y también a los <a class=\"t\" href=\"glosario.html#marut\" data-t=\"marut\">Maruts</a>; mira, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>, muchas maravillas nunca vistas antes.</span>", "palabras": [{"iast": "paśya", "sa": "पश्य", "gram": "2 sg. impv. act.", "es": "mira", "analisis": "√paś (ver)"}, {"iast": "ādityān", "sa": "आदित्यान्", "gram": "acc. pl. m.", "es": "a los Ādityas", "ref": "aditya"}, {"iast": "vasūn", "sa": "वसून्", "gram": "acc. pl. m.", "es": "a los Vasus", "ref": "vasu"}, {"iast": "rudrān", "sa": "रुद्रान्", "gram": "acc. pl. m.", "es": "a los Rudras", "ref": "rudra"}, {"iast": "aśvinau", "sa": "अश्विनौ", "gram": "acc. du. m.", "es": "a los dos Aśvins", "ref": "asvins"}, {"iast": "marutaḥ", "sa": "मरुतः", "gram": "acc. pl. m.", "es": "a los Maruts", "ref": "marut"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "también"}, {"iast": "bahūni", "sa": "बहूनि", "gram": "acc. pl. n.", "es": "muchas"}, {"iast": "adṛṣṭa-pūrvāṇi", "sa": "अदृष्टपूर्वाणि", "gram": "acc. pl. n. comp.", "es": "nunca vistas antes", "analisis": "a-dṛṣṭa (no visto) + pūrva (antes)"}, {"iast": "āścaryāṇi", "sa": "आश्चर्याणि", "gram": "acc. pl. n.", "es": "maravillas"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata"}], "nota": "<p>Las clases de dioses que Kṛṣṇa nombraba en el capítulo anterior al enumerar sus manifestaciones (todas menos los Aśvins) (<a class=\"vref\" href=\"capitulo-10.html#v21\" data-v=\"10.21\">10.21</a>–<a class=\"vref\" href=\"capitulo-10.html#v23\" data-v=\"10.23\">10.23</a>) aparecen ahora a la vista, dentro de su forma. <em>Adṛṣṭa-pūrva</em>, «no visto antes»: Arjuna lo repetirá al final, cuando confiese que la visión lo ha llenado de alegría y de miedo a la vez (<a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>).</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-ojo-divino"}, {"n": 7, "hablante": "krsna", "sa": ["इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम् ।", "मम देहे गुडाकेश यच्चान्यद्द्रष्टुमिच्छसि ॥७॥"], "iast": ["ihaika-sthaṃ jagat kṛtsnaṃ paśyādya sa-carācaram", "mama dehe guḍākeśa yac cānyad draṣṭum icchasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Mira ahora aquí, en mi cuerpo, reunido en un solo lugar, el mundo entero, con lo móvil y lo inmóvil, oh <a class=\"t\" href=\"glosario.html#gudakesa\" data-t=\"gudakesa\">Guḍākeśa</a>, y todo lo demás que quieras ver.</span>", "palabras": [{"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí"}, {"iast": "eka-stham", "sa": "एकस्थम्", "gram": "acc. sg. n. comp.", "es": "reunido en uno, en un solo lugar", "analisis": "eka (uno) + stha (que está, de √sthā)"}, {"iast": "jagat", "sa": "जगत्", "gram": "acc. sg. n.", "es": "el mundo", "analisis": "de √gam (ir): lo que se mueve"}, {"iast": "kṛtsnam", "sa": "कृत्स्नम्", "gram": "acc. sg. n.", "es": "entero"}, {"iast": "paśya", "sa": "पश्य", "gram": "2 sg. impv. act.", "es": "mira", "analisis": "√paś (ver)"}, {"iast": "adya", "sa": "अद्य", "gram": "ind.", "es": "hoy, ahora"}, {"iast": "sa-cara-acaram", "sa": "सचराचरम्", "gram": "acc. sg. n. comp.", "es": "con lo móvil y lo inmóvil", "analisis": "sa (con) + cara (móvil) + acara (inmóvil)"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "dehe", "sa": "देहे", "gram": "loc. sg. m.", "es": "en el cuerpo"}, {"iast": "guḍākeśa", "sa": "गुडाकेश", "gram": "voc. sg. m.", "es": "oh Guḍākeśa", "ref": "gudakesa"}, {"iast": "yat", "sa": "यत्", "gram": "acc. sg. n. pron. rel.", "es": "lo que"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "anyat", "sa": "अन्यत्", "gram": "acc. sg. n.", "es": "otra cosa"}, {"iast": "draṣṭum", "sa": "द्रष्टुम्", "gram": "inf.", "es": "ver", "analisis": "√dṛś (ver)"}, {"iast": "icchasi", "sa": "इच्छसि", "gram": "2 sg. pres. act.", "es": "deseas", "analisis": "√iṣ (desear)"}], "nota": "<p><em>Eka-stha</em>, «que está en uno»: todo el universo, que en el capítulo anterior se recorría clase por clase, aparece ahora junto, en un solo cuerpo. Sañjaya repetirá casi las mismas palabras al describir lo que Arjuna vio: «el mundo entero, dividido de muchas maneras, reunido en uno en el cuerpo del dios de los dioses» (<a class=\"vref\" href=\"capitulo-11.html#v13\" data-v=\"11.13\">11.13</a>). <em>Yac cānyad draṣṭum icchasi</em>, «y lo que quieras ver además», deja abierta la visión a lo que Arjuna busque en ella.</p>", "interp": [{"titulo": "Lo que Arjuna quería saber", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> concreta «lo demás que quieras ver», como luego Vedānta Deśika y Viśvanātha Cakravartī —y con él <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>—: la victoria o la derrota, la duda que Arjuna expresaba antes de empezar la enseñanza, cuando no sabía si era mejor vencer o ser vencido (<a class=\"vref\" href=\"capitulo-02.html#v6\" data-v=\"2.6\">2.6</a>). La visión responderá también a esa pregunta, como señalan los tres: Arjuna verá a los guerreros de los dos ejércitos entrar en las bocas de Kṛṣṇa (<a class=\"vref\" href=\"capitulo-11.html#v26\" data-v=\"11.26\">11.26</a>–<a class=\"vref\" href=\"capitulo-11.html#v30\" data-v=\"11.30\">11.30</a>).</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-ojo-divino"}, {"n": 8, "hablante": "krsna", "sa": ["न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा ।", "दिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम् ॥८॥"], "iast": ["na tu māṃ śakyase draṣṭum anenaiva sva-cakṣuṣā", "divyaṃ dadāmi te cakṣuḥ paśya me yogam aiśvaram"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero no podrás verme con estos tus propios ojos. Te doy un <a class=\"t\" href=\"glosario.html#divya-caksus\" data-t=\"divya-caksus\">ojo divino</a>: mira mi <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga soberano</a>.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "śakyase", "sa": "शक्यसे", "gram": "2 sg. pres. pas.", "es": "puedes, eres capaz", "analisis": "√śak (poder), forma pasiva con valor activo"}, {"iast": "draṣṭum", "sa": "द्रष्टुम्", "gram": "inf.", "es": "ver", "analisis": "√dṛś (ver)"}, {"iast": "anena", "sa": "अनेन", "gram": "instr. sg. n. pron.", "es": "con este"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo, sólo"}, {"iast": "sva-cakṣuṣā", "sa": "स्वचक्षुषा", "gram": "instr. sg. n. comp.", "es": "con tu propio ojo", "analisis": "sva (propio) + cakṣus (ojo, vista)"}, {"iast": "divyam", "sa": "दिव्यम्", "gram": "acc. sg. n.", "es": "divino", "analisis": "de div (cielo)"}, {"iast": "dadāmi", "sa": "ददामि", "gram": "1 sg. pres. act.", "es": "doy", "analisis": "√dā (dar)"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "cakṣuḥ", "sa": "चक्षुः", "gram": "acc. sg. n.", "es": "ojo, vista", "ref": "divya-caksus"}, {"iast": "paśya", "sa": "पश्य", "gram": "2 sg. impv. act.", "es": "mira", "analisis": "√paś (ver)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "yogam", "sa": "योगम्", "gram": "acc. sg. m.", "es": "yoga, poder", "ref": "yoga-maya"}, {"iast": "aiśvaram", "sa": "ऐश्वरम्", "gram": "acc. sg. m.", "es": "soberano", "analisis": "de īśvara (señor)"}], "nota": "<p><em>Cakṣus</em> es a la vez el ojo y la facultad de ver: lo que Kṛṣṇa concede no es un órgano nuevo, sino una vista capaz de lo que los ojos de la carne no alcanzan; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo llama «un ojo hecho de conocimiento». El verso plantea una condición que el capítulo retomará al final: esta forma no se ve por los Vedas, los sacrificios ni las austeridades (<a class=\"vref\" href=\"capitulo-11.html#v48\" data-v=\"11.48\">11.48</a>, <a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a>), sino por una devoción exclusiva (<a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a>).</p>", "interp": [{"titulo": "Dos visiones concedidas", "html": "<p>El ojo divino de Arjuna tiene un paralelo en el marco del poema: también Sañjaya narra lo que no tiene delante gracias a una visión que le concedió <a class=\"t\" href=\"glosario.html#vyasa\" data-t=\"vyasa\">Vyāsa</a> (véase la ficha <a class=\"t\" href=\"glosario.html#sanjaya\" data-t=\"sanjaya\">Sañjaya</a>), y al final lo reconoce: «por la gracia de Vyāsa he escuchado este secreto supremo» (<a class=\"vref\" href=\"capitulo-18.html#v75\" data-v=\"18.75\">18.75</a>). La Gītā llega así al lector a través de dos miradas que no son naturales: la de Arjuna, que ve la forma de Kṛṣṇa, y la de Sañjaya, que ve a Arjuna verla.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Pero no podrás verme con estos tus propios ojos. Te doy un ojo divino: mira mi poder soberano.", "nota": "<p><em>Yoga</em> no es aquí la disciplina, sino el poder o el prodigio del Señor: <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo glosa «el exceso del poder del yoga» (<em>yoga-śakty-atiśaya</em>), y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, «la capacidad de hacer posible lo imposible», el mismo sentido que estos dos dan a «mi yoga soberano» en <a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a> (véase la ficha <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga-māyā</a>). La traducción principal conserva la palabra, como en aquel verso; la alternativa hace explícito ese sentido. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo entiende como la posesión (<em>yoga</em>) de sus cualidades infinitas, como el conocimiento, y de su poderío sin límite (<em>vibhūti</em>).</p>"}], "ens": "el-ojo-divino"}, {"n": 9, "hablante": "sanjaya", "sa": ["सञ्जय उवाच ।", "एवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः ।", "दर्शयामास पार्थाय परमं रूपमैश्वरम् ॥९॥"], "iast": ["sañjaya uvāca", "evam uktvā tato rājan mahā-yogeśvaro hariḥ", "darśayām āsa pārthāya paramaṃ rūpam aiśvaram"], "rojas": [], "t": "<span class=\"vt-parte\">Dicho esto, oh <a class=\"t\" href=\"glosario.html#dhrtarastra\" data-t=\"dhrtarastra\">rey</a>, <a class=\"t\" href=\"glosario.html#hari\" data-t=\"hari\">Hari</a>, el gran Señor del <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, mostró a <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a> su <a class=\"t\" href=\"glosario.html#visvarupa\" data-t=\"visvarupa\">forma</a> suprema, soberana:</span>", "palabras": [{"iast": "sañjayaḥ", "sa": "सञ्जयः", "gram": "nom. sg. m.", "es": "Sañjaya", "ref": "sanjaya"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "uktvā", "sa": "उक्त्वा", "gram": "abs.", "es": "habiendo dicho", "analisis": "√vac (hablar)"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "entonces"}, {"iast": "rājan", "sa": "राजन्", "gram": "voc. sg. m.", "es": "oh rey", "ref": "dhrtarastra", "analisis": "Sañjaya se dirige a Dhṛtarāṣṭra"}, {"iast": "mahā-yogeśvaraḥ", "sa": "महायोगेश्वरः", "gram": "nom. sg. m. comp.", "es": "el gran Señor del yoga", "ref": "yoga", "analisis": "mahā (grande) + yoga + īśvara (señor)"}, {"iast": "hariḥ", "sa": "हरिः", "gram": "nom. sg. m.", "es": "Hari", "ref": "hari", "analisis": "√hṛ (llevarse, arrebatar)"}, {"iast": "darśayām āsa", "sa": "दर्शयामास", "gram": "3 sg. pf. perifr. caus.", "es": "mostró", "analisis": "causativo de √dṛś (ver): «hizo ver»"}, {"iast": "pārthāya", "sa": "पार्थाय", "gram": "dat. sg. m.", "es": "a Pārtha", "ref": "partha"}, {"iast": "paramam", "sa": "परमम्", "gram": "acc. sg. n.", "es": "supremo"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "acc. sg. n.", "es": "forma", "ref": "visvarupa"}, {"iast": "aiśvaram", "sa": "ऐश्वरम्", "gram": "acc. sg. n.", "es": "soberana, propia del Señor", "analisis": "de īśvara (señor)"}], "nota": "<p>Vuelve a hablar el narrador. Desde <a class=\"vref\" href=\"capitulo-02.html#v11\" data-v=\"2.11\">2.11</a> la Gītā había sido un diálogo entre Kṛṣṇa y Arjuna; ahora <a class=\"t\" href=\"glosario.html#sanjaya\" data-t=\"sanjaya\">Sañjaya</a> retoma la palabra para contar a <a class=\"t\" href=\"glosario.html#dhrtarastra\" data-t=\"dhrtarastra\">Dhṛtarāṣṭra</a>, el rey ciego, lo que ve por la visión que le concedió <a class=\"t\" href=\"glosario.html#vyasa\" data-t=\"vyasa\">Vyāsa</a>: el «oh rey» lo recuerda. Hasta <a class=\"vref\" href=\"capitulo-11.html#v14\" data-v=\"11.14\">11.14</a> es él quien describe la forma universal; después Arjuna la describirá con su propia voz (<a class=\"vref\" href=\"capitulo-11.html#v15\" data-v=\"11.15\">11.15</a>–<a class=\"vref\" href=\"capitulo-11.html#v31\" data-v=\"11.31\">11.31</a>). <em>Rūpam aiśvaram</em>, «la forma soberana», son las mismas palabras con que Arjuna la había pedido en <a class=\"vref\" href=\"capitulo-11.html#v3\" data-v=\"11.3\">11.3</a>: el verso cuenta que la petición se cumple al pie de la letra. <em>Mahā-yogeśvara</em>, «gran Señor del yoga», amplía el <em>yogeśvara</em> de <a class=\"vref\" href=\"capitulo-11.html#v4\" data-v=\"11.4\">11.4</a>; <em>yoga</em> puede entenderse aquí como el poder prodigioso de Kṛṣṇa, el «yoga soberano» de <a class=\"vref\" href=\"capitulo-11.html#v8\" data-v=\"11.8\">11.8</a> y <a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a> (así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: «señor de los prodigios más asombrosos»), aunque <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> explican <em>yogeśvara</em> como «señor de los yoguis» (<a class=\"vref\" href=\"capitulo-11.html#v4\" data-v=\"11.4\">11.4</a>). <em>Hari</em> es uno de los nombres de Viṣṇu; en la Gītā sólo aparece aquí y en <a class=\"vref\" href=\"capitulo-18.html#v77\" data-v=\"18.77\">18.77</a>, también en boca de Sañjaya.</p>", "interp": [{"titulo": "Un ciego oye lo que vio Arjuna", "html": "<p>El marco del poema vuelve a hacerse visible en el momento de mayor visión. Quien cuenta la forma universal es Sañjaya, que la ve gracias a un don de Vyāsa, y quien la escucha es Dhṛtarāṣṭra, que no puede ver nada. La escena tiene así tres niveles: Arjuna ve con el ojo divino que Kṛṣṇa le acaba de dar (<a class=\"vref\" href=\"capitulo-11.html#v8\" data-v=\"11.8\">11.8</a>); Sañjaya ve con el que le dio Vyāsa; y el rey, y con él el lector, sólo puede oír. Al final del poema Sañjaya dirá que recordar esta forma lo sigue llenando de asombro (<a class=\"vref\" href=\"capitulo-18.html#v77\" data-v=\"18.77\">18.77</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 10, "hablante": "sanjaya", "sa": ["अनेकवक्त्रनयनमनेकाद्भुतदर्शनम् ।", "अनेकदिव्याभरणं दिव्यानेकोद्यतायुधम् ॥१०॥"], "iast": ["aneka-vaktra-nayanam anekādbhuta-darśanam", "aneka-divyābharaṇaṃ divyānekodyatāyudham"], "rojas": [], "t": "<span class=\"vt-parte\">de muchas bocas y ojos, de muchas visiones prodigiosas, de muchos adornos divinos, con muchas armas divinas alzadas,</span>", "palabras": [{"iast": "aneka-vaktra-nayanam", "sa": "अनेकवक्त्रनयनम्", "gram": "acc. sg. n. comp.", "es": "de muchas bocas y ojos", "analisis": "aneka (muchos) + vaktra (boca, rostro) + nayana (ojo)"}, {"iast": "anekādbhuta-darśanam", "sa": "अनेकाद्भुतदर्शनम्", "gram": "acc. sg. n. comp.", "es": "de muchas visiones prodigiosas", "analisis": "aneka (muchos) + adbhuta (prodigioso) + darśana (visión, aspecto)"}, {"iast": "aneka-divyābharaṇam", "sa": "अनेकदिव्याभरणम्", "gram": "acc. sg. n. comp.", "es": "de muchos adornos divinos", "analisis": "aneka (muchos) + divya (divino) + ābharaṇa (adorno, joya)"}, {"iast": "divyānekodyatāyudham", "sa": "दिव्यानेकोद्यतायुधम्", "gram": "acc. sg. n. comp.", "es": "con muchas armas divinas alzadas", "analisis": "divya (divino) + aneka (muchos) + udyata (alzado) + āyudha (arma)"}], "nota": "<p>El verso no tiene verbo: es una cadena de compuestos que describen la forma de <a class=\"vref\" href=\"capitulo-11.html#v9\" data-v=\"11.9\">11.9</a> y continúa en el verso siguiente. El original repite <em>aneka</em>, «muchos», cuatro veces en dos líneas, y <em>divya</em>, «divino», dos; la traducción conserva la repetición, que da el efecto de una visión que no se deja abarcar. <em>Vaktra</em> es «boca» y también «rostro»; las muchas bocas volverán, terribles, en <a class=\"vref\" href=\"capitulo-11.html#v23\" data-v=\"11.23\">11.23</a>–<a class=\"vref\" href=\"capitulo-11.html#v30\" data-v=\"11.30\">11.30</a>.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 11, "hablante": "sanjaya", "sa": ["दिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम् ।", "सर्वाश्चर्यमयं देवमनन्तं विश्वतोमुखम् ॥११॥"], "iast": ["divya-mālyāmbara-dharaṃ divya-gandhānulepanam", "sarvāścarya-mayaṃ devam anantaṃ viśvato-mukham"], "rojas": [], "t": "<span class=\"vt-parte\">con guirnaldas y vestidos divinos, ungido de perfumes divinos: el <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dios</a>, todo maravilla, infinito, con el rostro vuelto a todas partes.</span>", "palabras": [{"iast": "divya-mālyāmbara-dharam", "sa": "दिव्यमाल्याम्बरधरम्", "gram": "acc. sg. m. comp.", "es": "que lleva guirnaldas y vestidos divinos", "analisis": "divya (divino) + mālya (guirnalda) + ambara (vestido) + dhara (que lleva)"}, {"iast": "divya-gandhānulepanam", "sa": "दिव्यगन्धानुलेपनम्", "gram": "acc. sg. m. comp.", "es": "ungido de perfumes divinos", "analisis": "divya (divino) + gandha (perfume) + anulepana (unción)"}, {"iast": "sarvāścarya-mayam", "sa": "सर्वाश्चर्यमयम्", "gram": "acc. sg. m. comp.", "es": "hecho todo de maravillas", "analisis": "sarva (todo) + āścarya (maravilla) + -maya (hecho de)"}, {"iast": "devam", "sa": "देवम्", "gram": "acc. sg. m.", "es": "el dios", "ref": "deva"}, {"iast": "anantam", "sa": "अनन्तम्", "gram": "acc. sg. m.", "es": "infinito", "analisis": "an- (sin) + anta (fin)"}, {"iast": "viśvato-mukham", "sa": "विश्वतोमुखम्", "gram": "acc. sg. m. comp.", "es": "con el rostro vuelto a todas partes", "analisis": "viśvatas (por todas partes) + mukha (rostro)"}], "nota": "<p>A mitad de la descripción el género cambia: en <a class=\"vref\" href=\"capitulo-11.html#v10\" data-v=\"11.10\">11.10</a> los compuestos concuerdan con <em>rūpam</em>, «la forma», que es neutro; aquí aparece <em>devam</em>, «el dios», masculino, y la descripción pasa a él. Lo que Sañjaya empezó a describir como una forma resulta ser alguien. <em>Viśvato-mukha</em>, «con el rostro vuelto a todas partes», es la misma expresión de <a class=\"vref\" href=\"capitulo-09.html#v15\" data-v=\"9.15\">9.15</a> y <a class=\"vref\" href=\"capitulo-10.html#v33\" data-v=\"10.33\">10.33</a>: lo que allí se afirmaba de Kṛṣṇa, aquí se ve.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 12, "hablante": "sanjaya", "sa": ["दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता ।", "यदि भाः सदृशी सा स्याद्भासस्तस्य महात्मनः ॥१२॥"], "iast": ["divi sūrya-sahasrasya bhaved yugapad utthitā", "yadi bhāḥ sadṛśī sā syād bhāsas tasya mahātmanaḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Si en el cielo se alzara de golpe el resplandor de mil soles, ese resplandor quizá se asemejaría al de aquel <a class=\"t\" href=\"glosario.html#mahatman\" data-t=\"mahatman\">gran ser</a>.</span>", "palabras": [{"iast": "divi", "sa": "दिवि", "gram": "loc. sg. f.", "es": "en el cielo", "analisis": "div (cielo)"}, {"iast": "sūrya-sahasrasya", "sa": "सूर्यसहस्रस्य", "gram": "gen. sg. n. comp.", "es": "de mil soles", "ref": "surya", "analisis": "sūrya (sol) + sahasra (mil)"}, {"iast": "bhavet", "sa": "भवेत्", "gram": "3 sg. opt.", "es": "hubiera, se diera", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "yugapat", "sa": "युगपत्", "gram": "ind.", "es": "a la vez, de golpe"}, {"iast": "utthitā", "sa": "उत्थिता", "gram": "nom. sg. f. ppp.", "es": "alzado, surgido", "analisis": "ud-√sthā (levantarse)"}, {"iast": "yadi", "sa": "यदि", "gram": "ind.", "es": "si"}, {"iast": "bhāḥ", "sa": "भाः", "gram": "nom. sg. f.", "es": "el resplandor", "analisis": "bhās (luz, brillo)"}, {"iast": "sadṛśī", "sa": "सदृशी", "gram": "nom. sg. f.", "es": "semejante"}, {"iast": "sā", "sa": "सा", "gram": "nom. sg. f. pron.", "es": "ese"}, {"iast": "syāt", "sa": "स्यात्", "gram": "3 sg. opt.", "es": "sería", "analisis": "√as (ser)"}, {"iast": "bhāsaḥ", "sa": "भासः", "gram": "gen. sg. f.", "es": "al resplandor", "analisis": "bhās (luz, brillo)"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m. pron.", "es": "de aquel"}, {"iast": "mahātmanaḥ", "sa": "महात्मनः", "gram": "gen. sg. m.", "es": "gran ser", "ref": "mahatman", "analisis": "mahā (grande) + ātman"}], "nota": "<p>El verso encadena dos condiciones: si se diera el resplandor de mil soles, y si acaso ese resplandor pudiera compararse con el de la forma universal. La segunda, <em>yadi… syāt</em>, deja en duda que la comparación alcance; de ahí el «quizá». Según <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, mil soles a la vez quizá se le parecerían, o quizá no, y en ese caso el resplandor de la forma universal los excedería; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> («apenas semejante») y Madhusūdana concluyen que no hay otra comparación posible. <em>Mahātman</em>, «gran ser», lo aplica Sañjaya a Kṛṣṇa aquí y en <a class=\"vref\" href=\"capitulo-11.html#v50\" data-v=\"11.50\">11.50</a>.</p>", "interp": [{"titulo": "Más brillante que mil soles", "html": "<p>El verso se hizo célebre en el siglo XX por su asociación con la bomba atómica. Según el periodista Robert Jungk, cuyo libro sobre los científicos del proyecto Manhattan tomó de aquí su título (<em>Heller als tausend Sonnen</em>, 1956; en inglés, <em>Brighter than a Thousand Suns</em>, 1958), J. Robert Oppenheimer recordó este verso al ver el resplandor de la prueba Trinity, en julio de 1945, y, al alzarse la nube, otro del mismo capítulo, el del tiempo que destruye los mundos (<a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a>); éste es el que el propio Oppenheimer citó años después ante las cámaras.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 13, "hablante": "sanjaya", "sa": ["तत्रैकस्थं जगत्कृत्स्नं प्रविभक्तमनेकधा ।", "अपश्यद्देवदेवस्य शरीरे पाण्डवस्तदा ॥१३॥"], "iast": ["tatraika-sthaṃ jagat kṛtsnaṃ pravibhaktam anekadhā", "apaśyad deva-devasya śarīre pāṇḍavas tadā"], "rojas": [], "t": "<span class=\"vt-parte\">Allí, en el cuerpo del dios de los dioses, vio entonces el <a class=\"t\" href=\"glosario.html#pandava\" data-t=\"pandava\">hijo de Pāṇḍu</a> el universo entero, dividido de muchas maneras, reunido en uno solo.</span>", "palabras": [{"iast": "tatra", "sa": "तत्र", "gram": "ind.", "es": "allí"}, {"iast": "eka-stham", "sa": "एकस्थम्", "gram": "acc. sg. n. comp.", "es": "reunido en uno, en un solo lugar", "analisis": "eka (uno) + stha (que está, de √sthā)"}, {"iast": "jagat", "sa": "जगत्", "gram": "acc. sg. n.", "es": "el universo, el mundo", "analisis": "de √gam (ir): «lo que se mueve»"}, {"iast": "kṛtsnam", "sa": "कृत्स्नम्", "gram": "acc. sg. n.", "es": "entero"}, {"iast": "pravibhaktam", "sa": "प्रविभक्तम्", "gram": "acc. sg. n. ppp.", "es": "dividido, distribuido", "analisis": "pra-vi-√bhaj (repartir, dividir)"}, {"iast": "anekadhā", "sa": "अनेकधा", "gram": "ind.", "es": "de muchas maneras"}, {"iast": "apaśyat", "sa": "अपश्यत्", "gram": "3 sg. impf. act.", "es": "vio", "analisis": "√dṛś / paś (ver)"}, {"iast": "deva-devasya", "sa": "देवदेवस्य", "gram": "gen. sg. m. comp.", "es": "del dios de los dioses", "ref": "deva", "analisis": "deva (dios) + deva"}, {"iast": "śarīre", "sa": "शरीरे", "gram": "loc. sg. n.", "es": "en el cuerpo"}, {"iast": "pāṇḍavaḥ", "sa": "पाण्डवः", "gram": "nom. sg. m.", "es": "el hijo de Pāṇḍu (Arjuna)", "ref": "pandava"}, {"iast": "tadā", "sa": "तदा", "gram": "ind.", "es": "entonces"}], "nota": "<p>El verso junta dos palabras opuestas: el universo está «dividido de muchas maneras» (<em>pravibhaktam anekadhā</em>) y a la vez «reunido en uno» (<em>eka-stha</em>). <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> precisan las divisiones —dioses, antepasados, hombres y demás— y entienden el «uno» como la sola forma universal; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como «una sola parte» de ese cuerpo. No se trata de que la multiplicidad desaparezca, sino de verla toda a la vez, sin perder sus divisiones, en un solo cuerpo. Es la visión que Arjuna había pedido después de oír, en <a class=\"vref\" href=\"capitulo-10.html#v42\" data-v=\"10.42\">10.42</a>, que Kṛṣṇa sostiene el universo con una sola parte de sí, y la que Kṛṣṇa le había anunciado en <a class=\"vref\" href=\"capitulo-11.html#v7\" data-v=\"11.7\">11.7</a>: «mira aquí, reunido en mi cuerpo, el universo entero». <em>Deva-deva</em>, «dios de los dioses», es el mismo título que Arjuna le dio en <a class=\"vref\" href=\"capitulo-10.html#v15\" data-v=\"10.15\">10.15</a>.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 14, "hablante": "sanjaya", "sa": ["ततः स विस्मयाविष्टो हृष्टरोमा धनञ्जयः ।", "प्रणम्य शिरसा देवं कृताञ्जलिरभाषत ॥१४॥"], "iast": ["tataḥ sa vismayāviṣṭo hṛṣṭa-romā dhanañjayaḥ", "praṇamya śirasā devaṃ kṛtāñjalir abhāṣata"], "rojas": [], "t": "<span class=\"vt-parte\">Entonces <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>, invadido por el asombro, con el vello erizado, inclinó la cabeza ante el <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dios</a> y, con las manos juntas, le dijo:</span>", "palabras": [{"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "entonces"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "vismayāviṣṭaḥ", "sa": "विस्मयाविष्टः", "gram": "nom. sg. m. comp.", "es": "invadido por el asombro", "analisis": "vismaya (asombro) + āviṣṭa (entrado, poseído, de ā-√viś)"}, {"iast": "hṛṣṭa-romā", "sa": "हृष्टरोमा", "gram": "nom. sg. m. comp.", "es": "con el vello erizado", "analisis": "hṛṣṭa (erizado, de √hṛṣ) + roman (vello)"}, {"iast": "dhanañjayaḥ", "sa": "धनञ्जयः", "gram": "nom. sg. m.", "es": "Dhanañjaya", "ref": "dhananjaya"}, {"iast": "praṇamya", "sa": "प्रणम्य", "gram": "abs.", "es": "inclinándose", "analisis": "pra-√nam (inclinarse, postrarse)"}, {"iast": "śirasā", "sa": "शिरसा", "gram": "instr. sg. n.", "es": "con la cabeza", "analisis": "śiras (cabeza)"}, {"iast": "devam", "sa": "देवम्", "gram": "acc. sg. m.", "es": "ante el dios", "ref": "deva"}, {"iast": "kṛtāñjaliḥ", "sa": "कृताञ्जलिः", "gram": "nom. sg. m. comp.", "es": "con las manos juntas", "analisis": "kṛta (hecho) + añjali (las palmas unidas, gesto de reverencia)"}, {"iast": "abhāṣata", "sa": "अभाषत", "gram": "3 sg. impf. med.", "es": "dijo, habló", "analisis": "√bhāṣ (hablar)"}], "nota": "<p><em>Añjali</em> es el gesto de las palmas unidas a la altura del pecho o de la frente, el saludo de reverencia que todavía se usa en la India. <em>Vismayāviṣṭa</em>, «invadido por el asombro», se construye como el <em>kṛpayāviṣṭa</em> con que se describía a Arjuna al principio, «invadido por la compasión» (<a class=\"vref\" href=\"capitulo-01.html#v28\" data-v=\"1.28\">1.28</a>, <a class=\"vref\" href=\"capitulo-02.html#v1\" data-v=\"2.1\">2.1</a>), y el vello erizado ya se le había erizado en <a class=\"vref\" href=\"capitulo-01.html#v29\" data-v=\"1.29\">1.29</a>. Con este verso termina la narración de Sañjaya; lo que sigue es la voz de Arjuna.</p>", "interp": [{"titulo": "Del abatimiento al asombro", "html": "<p>El poema parece repetir a propósito los gestos del principio. En el capítulo 1 Arjuna estaba «invadido» por la compasión y por el abatimiento, y el vello se le erizaba de angustia ante la idea de matar a los suyos (<a class=\"vref\" href=\"capitulo-01.html#v28\" data-v=\"1.28\">1.28</a>–<a class=\"vref\" href=\"capitulo-01.html#v29\" data-v=\"1.29\">1.29</a>). Aquí está «invadido» por el asombro, y el vello se le eriza ante lo que ve. El mismo cuerpo reacciona igual, pero a otra cosa: el miedo de perder a los suyos ha dejado paso al estremecimiento ante lo divino. Sañjaya, al final del poema, llamará al diálogo «que eriza el vello» (<a class=\"vref\" href=\"capitulo-18.html#v74\" data-v=\"18.74\">18.74</a>) y dirá que recordar esta forma lo llena de asombro y de gozo una y otra vez (<a class=\"vref\" href=\"capitulo-18.html#v77\" data-v=\"18.77\">18.77</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 15, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "पश्यामि देवांस्तव देव देहे सर्वांस्तथा भूतविशेषसङ्घान् ।", "ब्रह्माणमीशं कमलासनस्थमृषींश्च सर्वानुरगांश्च दिव्यान् ॥१५॥"], "iast": ["arjuna uvāca", "paśyāmi devāṃs tava deva dehe sarvāṃs tathā bhūta-viśeṣa-saṅghān", "brahmāṇam īśaṃ kamalāsana-stham ṛṣīṃś ca sarvān uragāṃś ca divyān"], "rojas": [], "t": "<span class=\"vt-parte\">Veo en tu cuerpo, oh dios, a todos los <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a>, y también a las multitudes de los distintos seres; a <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a>, el señor, sentado sobre el loto, a todos los <a class=\"t\" href=\"glosario.html#rsi\" data-t=\"rsi\">videntes</a> y a las serpientes divinas.</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "paśyāmi", "sa": "पश्यामि", "gram": "1 sg. pres. act.", "es": "veo", "analisis": "√dṛś / paś (ver)"}, {"iast": "devān", "sa": "देवान्", "gram": "ac. pl. m.", "es": "a los dioses", "ref": "deva"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tu, de ti"}, {"iast": "deva", "sa": "देव", "gram": "voc. sg. m.", "es": "oh dios", "ref": "deva"}, {"iast": "dehe", "sa": "देहे", "gram": "loc. sg. m.", "es": "en el cuerpo"}, {"iast": "sarvān", "sa": "सर्वान्", "gram": "ac. pl. m.", "es": "a todos"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así, y también"}, {"iast": "bhūta-viśeṣa-saṅghān", "sa": "भूतविशेषसङ्घान्", "gram": "ac. pl. m. comp.", "es": "las multitudes de los distintos seres", "analisis": "bhūta (ser) + viśeṣa (clase particular) + saṅgha (multitud)"}, {"iast": "brahmāṇam", "sa": "ब्रह्माणम्", "gram": "ac. sg. m.", "es": "a Brahmā", "ref": "brahma-deva", "analisis": "brahman, masculino: el dios creador"}, {"iast": "īśam", "sa": "ईशम्", "gram": "ac. sg. m.", "es": "al señor", "analisis": "√īś (ser dueño, gobernar)"}, {"iast": "kamalāsana-stham", "sa": "कमलासनस्थम्", "gram": "ac. sg. m. comp.", "es": "sentado sobre el loto", "analisis": "kamala (loto) + āsana (asiento) + stha (que está)"}, {"iast": "ṛṣīn", "sa": "ऋषीन्", "gram": "ac. pl. m.", "es": "a los videntes", "ref": "rsi"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "sarvān", "sa": "सर्वान्", "gram": "ac. pl. m.", "es": "a todos"}, {"iast": "uragān", "sa": "उरगान्", "gram": "ac. pl. m.", "es": "a las serpientes", "analisis": "ura (pecho) + ga (que va): «la que va sobre el pecho»"}, {"iast": "divyān", "sa": "दिव्यान्", "gram": "ac. pl. m.", "es": "divinas", "analisis": "de div (cielo)"}], "nota": "<p>Empieza aquí el himno de Arjuna, que llega hasta <a class=\"vref\" href=\"capitulo-11.html#v31\" data-v=\"11.31\">11.31</a>: diecisiete versos en <em>triṣṭubh</em>, el metro de los himnos védicos, de once sílabas por pie, más amplio que el <em>śloka</em> del diálogo. Arjuna dice lo que ve, y lo primero que ve es que todo está en el cuerpo de Kṛṣṇa, como éste había anunciado: «mira aquí, reunido en mi cuerpo, el mundo entero» (<a class=\"vref\" href=\"capitulo-11.html#v7\" data-v=\"11.7\">11.7</a>). <em>Kamalāsana-stha</em>, «sentado sobre el loto», es la imagen tradicional de <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a>. <em>Uraga</em>, literalmente «el que va sobre el pecho», es la serpiente; las divinas son los <em>nāga</em> (véase <a class=\"t\" href=\"glosario.html#vasuki\" data-t=\"vasuki\">Vāsuki</a>).</p>", "interp": [{"titulo": "Lo que Arjuna ve primero", "html": "<p>El capítulo 10 había enumerado las manifestaciones una por una; ahora Arjuna las ve todas a la vez, en un solo cuerpo. El orden de lo que nombra no es casual: los dioses, los seres de toda clase, el creador en su loto, los videntes y las serpientes divinas, es decir, lo alto, lo de en medio y lo de abajo. La visión no añade nada a lo que Kṛṣṇa ya había dicho de sí (<a class=\"vref\" href=\"capitulo-09.html#v4\" data-v=\"9.4\">9.4</a>, <a class=\"vref\" href=\"capitulo-10.html#v42\" data-v=\"10.42\">10.42</a>); lo que cambia es que ahora se ve.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Veo en tu cuerpo, oh dios, a todos los dioses, y también a las multitudes de los distintos seres; a Brahmā sentado sobre el loto, a Īśa, a todos los videntes y a las serpientes divinas.", "nota": "<p><em>Īśam</em>, «al señor», está entre <em>brahmāṇam</em> y <em>kamalāsana-stham</em>, los tres en acusativo. Puede leerse como un título del propio <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a>, «el señor de las criaturas» según <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> (también <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>), sentado sobre el loto —el monte Meru en el centro del loto de la tierra, para Śaṅkara; o el loto que brota del ombligo de Viṣṇu, que Śrīdhara y Madhusūdana dan como otra posibilidad—, que es como lo toma la traducción principal; o como el nombre de otra figura, Īśa, «el Señor», un nombre de Śiva (véase <a class=\"t\" href=\"glosario.html#rudra\" data-t=\"rudra\">Rudra</a>), que es como lo leen <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien Īśa está «en Brahmā, el del asiento de loto», sometido a él, y Prabhupāda («as well as Lord Śiva»), y lo que hace explícito la alternativa. En el resto de la Gītā la palabra sólo vuelve en <a class=\"vref\" href=\"capitulo-11.html#v44\" data-v=\"11.44\">11.44</a>, dicha del propio Kṛṣṇa.</p>"}]}, {"n": 16, "hablante": "arjuna", "sa": ["अनेकबाहूदरवक्त्रनेत्रं पश्यामि त्वां सर्वतोऽनन्तरूपम् ।", "नान्तं न मध्यं न पुनस्तवादिं पश्यामि विश्वेश्वर विश्वरूप ॥१६॥"], "iast": ["aneka-bāhūdara-vaktra-netraṃ paśyāmi tvāṃ sarvato 'nanta-rūpam", "nāntaṃ na madhyaṃ na punas tavādiṃ paśyāmi viśveśvara viśva-rūpa"], "rojas": [], "t": "<span class=\"vt-parte\">Te veo de innumerables brazos, vientres, bocas y ojos, de forma infinita por todas partes; no veo tu fin, ni tu medio, ni tampoco tu principio, oh señor del universo, oh <a class=\"t\" href=\"glosario.html#visvarupa\" data-t=\"visvarupa\">forma universal</a>.</span>", "palabras": [{"iast": "aneka-bāhu-udara-vaktra-netram", "sa": "अनेकबाहूदरवक्त्रनेत्रम्", "gram": "ac. sg. m. comp.", "es": "de innumerables brazos, vientres, bocas y ojos", "analisis": "aneka (no uno: muchos) + bāhu (brazo) + udara (vientre) + vaktra (boca, rostro) + netra (ojo)"}, {"iast": "paśyāmi", "sa": "पश्यामि", "gram": "1 sg. pres. act.", "es": "veo"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti"}, {"iast": "sarvataḥ", "sa": "सर्वतः", "gram": "ind.", "es": "por todas partes"}, {"iast": "ananta-rūpam", "sa": "अनन्तरूपम्", "gram": "ac. sg. m. comp.", "es": "de forma infinita", "analisis": "an-anta (sin fin) + rūpa (forma)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "antam", "sa": "अन्तम्", "gram": "ac. sg. m.", "es": "el fin"}, {"iast": "madhyam", "sa": "मध्यम्", "gram": "ac. sg. n.", "es": "el medio"}, {"iast": "punaḥ", "sa": "पुनः", "gram": "ind.", "es": "tampoco (con na), de nuevo"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "ādim", "sa": "आदिम्", "gram": "ac. sg. m.", "es": "el principio"}, {"iast": "viśveśvara", "sa": "विश्वेश्वर", "gram": "voc. sg. m. comp.", "es": "oh señor del universo", "analisis": "viśva (todo, el universo) + īśvara (señor)"}, {"iast": "viśva-rūpa", "sa": "विश्वरूप", "gram": "voc. sg. m. comp.", "es": "oh forma universal", "ref": "visvarupa", "analisis": "viśva (todo) + rūpa (forma)"}], "nota": "<p><em>Vaktra</em> es la boca y también el rostro. <em>Viśva-rūpa</em>, «el de forma universal» o «el que tiene por forma el universo», es el nombre que da título al capítulo; aquí es un vocativo: Arjuna llama a Kṛṣṇa por lo que está viendo. La frase «no veo tu fin, ni tu medio, ni tu principio» invierte la de <a class=\"vref\" href=\"capitulo-10.html#v20\" data-v=\"10.20\">10.20</a>, donde Kṛṣṇa se decía «el principio, el medio y el fin de los seres»: lo que es principio, medio y fin de todo no tiene él mismo ninguno de los tres.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 17, "hablante": "arjuna", "sa": ["किरीटिनं गदिनं चक्रिणं च तेजोराशिं सर्वतो दीप्तिमन्तम् ।", "पश्यामि त्वां दुर्निरीक्ष्यं समन्ताद्दीप्तानलार्कद्युतिमप्रमेयम् ॥१७॥"], "iast": ["kirīṭinaṃ gadinaṃ cakriṇaṃ ca tejo-rāśiṃ sarvato dīptimantam", "paśyāmi tvāṃ durnirīkṣyaṃ samantād dīptānalārka-dyutim aprameyam"], "rojas": [], "t": "<span class=\"vt-parte\">Te veo con diadema, con maza y con disco, masa de <a class=\"t\" href=\"glosario.html#tejas\" data-t=\"tejas\">esplendor</a> que resplandece por todas partes; difícil de mirar, con el fulgor del fuego ardiente y del sol en todas direcciones, inconmensurable.</span>", "palabras": [{"iast": "kirīṭinam", "sa": "किरीटिनम्", "gram": "ac. sg. m.", "es": "con diadema", "analisis": "kirīṭa (diadema, corona) + -in (que tiene)"}, {"iast": "gadinam", "sa": "गदिनम्", "gram": "ac. sg. m.", "es": "con maza", "analisis": "gadā (maza) + -in"}, {"iast": "cakriṇam", "sa": "चक्रिणम्", "gram": "ac. sg. m.", "es": "con disco", "analisis": "cakra (disco, rueda) + -in"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "tejo-rāśim", "sa": "तेजोराशिम्", "gram": "ac. sg. m. comp.", "es": "masa de esplendor", "ref": "tejas", "analisis": "tejas (esplendor) + rāśi (montón, masa)"}, {"iast": "sarvataḥ", "sa": "सर्वतः", "gram": "ind.", "es": "por todas partes"}, {"iast": "dīptimantam", "sa": "दीप्तिमन्तम्", "gram": "ac. sg. m.", "es": "resplandeciente", "analisis": "dīpti (resplandor) + -mat (que tiene)"}, {"iast": "paśyāmi", "sa": "पश्यामि", "gram": "1 sg. pres. act.", "es": "veo"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti"}, {"iast": "durnirīkṣyam", "sa": "दुर्निरीक्ष्यम्", "gram": "ac. sg. m. gerundivo", "es": "difícil de mirar", "analisis": "dus- (mal, difícil) + nir-√īkṣ (mirar)"}, {"iast": "samantāt", "sa": "समन्तात्", "gram": "ind.", "es": "por todos lados"}, {"iast": "dīpta-anala-arka-dyutim", "sa": "दीप्तानलार्कद्युतिम्", "gram": "ac. sg. m. comp.", "es": "con el fulgor del fuego ardiente y del sol", "analisis": "dīpta (ardiente) + anala (fuego) + arka (sol) + dyuti (fulgor)"}, {"iast": "aprameyam", "sa": "अप्रमेयम्", "gram": "ac. sg. m. gerundivo", "es": "inconmensurable", "analisis": "a- (no) + pra-√mā (medir)"}], "nota": "<p>La diadema, la maza y el disco son los atributos de <a class=\"t\" href=\"glosario.html#visnu\" data-t=\"visnu\">Viṣṇu</a> en la iconografía: en medio de una visión sin forma fija, Arjuna reconoce los rasgos del dios que conoce. Volverán en <a class=\"vref\" href=\"capitulo-11.html#v46\" data-v=\"11.46\">11.46</a>, cuando pida ver de nuevo la forma de cuatro brazos. <em>Kirīṭin</em>, «el de la diadema», se dice aquí de Kṛṣṇa; es también un nombre de Arjuna (<a class=\"vref\" href=\"capitulo-11.html#v35\" data-v=\"11.35\">11.35</a>). <em>Durnirīkṣya</em>, «difícil de mirar», recuerda el «resplandor de mil soles» de <a class=\"vref\" href=\"capitulo-11.html#v12\" data-v=\"11.12\">11.12</a>; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> precisa que lo es sin el ojo divino (<a class=\"vref\" href=\"capitulo-11.html#v8\" data-v=\"11.8\">11.8</a>), y por eso Arjuna puede decir que lo ve.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 18, "hablante": "arjuna", "sa": ["त्वमक्षरं परमं वेदितव्यं त्वमस्य विश्वस्य परं निधानम् ।", "त्वमव्ययः शाश्वतधर्मगोप्ता सनातनस्त्वं पुरुषो मतो मे ॥१८॥"], "iast": ["tvam akṣaraṃ paramaṃ veditavyaṃ tvam asya viśvasya paraṃ nidhānam", "tvam avyayaḥ śāśvata-dharma-goptā sanātanas tvaṃ puruṣo mato me"], "rojas": [], "t": "<span class=\"vt-parte\">Tú eres lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a>, lo supremo que ha de conocerse; tú, el último lugar de reposo de este universo; tú, el inmutable, el guardián del <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> eterno; tú eres, para mí, la <a class=\"t\" href=\"glosario.html#purusa\" data-t=\"purusa\">Persona</a> eterna.</span>", "palabras": [{"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "akṣaram", "sa": "अक्षरम्", "gram": "nom. sg. n.", "es": "lo imperecedero", "ref": "aksara", "analisis": "a- (no) + √kṣar (fluir, perecer)"}, {"iast": "paramam", "sa": "परमम्", "gram": "nom. sg. n.", "es": "supremo"}, {"iast": "veditavyam", "sa": "वेदितव्यम्", "gram": "nom. sg. n. gerundivo", "es": "lo que ha de conocerse", "analisis": "√vid (saber)"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. n. pron.", "es": "de este"}, {"iast": "viśvasya", "sa": "विश्वस्य", "gram": "gen. sg. n.", "es": "del universo"}, {"iast": "param", "sa": "परम्", "gram": "nom. sg. n.", "es": "supremo, último"}, {"iast": "nidhānam", "sa": "निधानम्", "gram": "nom. sg. n.", "es": "lugar de reposo, depósito", "analisis": "ni-√dhā (depositar, poner)"}, {"iast": "avyayaḥ", "sa": "अव्ययः", "gram": "nom. sg. m.", "es": "el inmutable, imperecedero", "analisis": "a- (no) + vi-√i (irse, gastarse)"}, {"iast": "śāśvata-dharma-goptā", "sa": "शाश्वतधर्मगोप्ता", "gram": "nom. sg. m. comp.", "es": "el guardián del dharma eterno", "ref": "dharma", "analisis": "śāśvata (eterno) + dharma + goptṛ (guardián, de √gup, proteger)"}, {"iast": "sanātanaḥ", "sa": "सनातनः", "gram": "nom. sg. m.", "es": "eterno, de siempre"}, {"iast": "puruṣaḥ", "sa": "पुरुषः", "gram": "nom. sg. m.", "es": "la Persona", "ref": "purusa"}, {"iast": "mataḥ", "sa": "मतः", "gram": "nom. sg. m. ppp", "es": "tenido por", "analisis": "√man (pensar)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "por mí, para mí"}], "nota": "<p>Por primera vez desde que empieza la visión, Arjuna no describe, sino que confiesa: aplica a lo que ve los nombres que Kṛṣṇa se había dado a sí mismo. Lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a> supremo es lo que <a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a> llamó brahman; <em>veditavya</em>, «lo que ha de conocerse», recuerda el <em>vedya</em> de <a class=\"vref\" href=\"capitulo-09.html#v17\" data-v=\"9.17\">9.17</a>. <em>Nidhāna</em>, «depósito, lugar donde algo se guarda o reposa», es la palabra que en <a class=\"vref\" href=\"capitulo-09.html#v18\" data-v=\"9.18\">9.18</a> se tradujo «el tesoro»; aquí, junto a «de este universo», <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo glosan «aquello en que algo se deposita», el soporte (<em>āśraya</em>) supremo del universo; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, su sostén (<em>ādhāra</em>) supremo; Viśvanātha Cakravartī lo entiende, en cambio, como el lugar donde todo se destruye. Volverá en <a class=\"vref\" href=\"capitulo-11.html#v38\" data-v=\"11.38\">11.38</a>. <em>Mato me</em>, «es mi parecer», da a la frase el tono de una convicción personal.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Tú eres lo imperecedero, lo supremo que ha de conocerse; tú, el último lugar de reposo de este universo; tú, el inmutable, el guardián del dharma, oh eterno; tú eres, para mí, la Persona eterna.", "nota": "<p>En el compuesto <em>śāśvata-dharma-goptā</em>, «eterno» puede ir con <em>dharma</em> («el guardián del dharma eterno») o con el compuesto entero («el guardián eterno del dharma»): las dos divisiones son gramaticalmente posibles, pero <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> toman la primera; Madhusūdana propone además leer <em>śāśvata</em> como vocativo, «oh eterno», que es lo que hace la alternativa. La traducción principal toma la primera, que remite, como señalan <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y Ānandagiri, al dharma que el descenso de Kṛṣṇa viene a restablecer (<a class=\"vref\" href=\"capitulo-04.html#v7\" data-v=\"4.7\">4.7</a>–<a class=\"vref\" href=\"capitulo-04.html#v8\" data-v=\"4.8\">4.8</a>) y al «dharma eterno» del que Kṛṣṇa se dirá fundamento (<a class=\"vref\" href=\"capitulo-14.html#v27\" data-v=\"14.27\">14.27</a>); así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: «el guardián del dharma eterno, el de los Vedas, por medio de descensos como éste».</p>"}]}, {"n": 19, "hablante": "arjuna", "sa": ["अनादिमध्यान्तमनन्तवीर्यमनन्तबाहुं शशिसूर्यनेत्रम् ।", "पश्यामि त्वां दीप्तहुताशवक्त्रं स्वतेजसा विश्वमिदं तपन्तम् ॥१९॥"], "iast": ["anādi-madhyāntam ananta-vīryam ananta-bāhuṃ śaśi-sūrya-netram", "paśyāmi tvāṃ dīpta-hutāśa-vaktraṃ sva-tejasā viśvam idaṃ tapantam"], "rojas": [], "t": "<span class=\"vt-parte\">Te veo sin principio, medio ni fin, de fuerza infinita, de brazos sin número, con la luna y el sol por ojos, con la boca de fuego ardiente, abrasando con tu propio resplandor todo este universo.</span>", "palabras": [{"iast": "an-ādi-madhya-antam", "sa": "अनादिमध्यान्तम्", "gram": "ac. sg. m. comp.", "es": "sin principio, medio ni fin", "analisis": "an- (sin) + ādi (principio) + madhya (medio) + anta (fin)"}, {"iast": "ananta-vīryam", "sa": "अनन्तवीर्यम्", "gram": "ac. sg. m. comp.", "es": "de fuerza infinita", "analisis": "ananta (infinito) + vīrya (fuerza, valor)"}, {"iast": "ananta-bāhum", "sa": "अनन्तबाहुम्", "gram": "ac. sg. m. comp.", "es": "de brazos sin número", "analisis": "ananta + bāhu (brazo)"}, {"iast": "śaśi-sūrya-netram", "sa": "शशिसूर्यनेत्रम्", "gram": "ac. sg. m. comp.", "es": "con la luna y el sol por ojos", "analisis": "śaśin (la luna, «la que tiene la liebre») + sūrya (sol) + netra (ojo)"}, {"iast": "paśyāmi", "sa": "पश्यामि", "gram": "1 sg. pres. act.", "es": "veo"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti"}, {"iast": "dīpta-hutāśa-vaktram", "sa": "दीप्तहुताशवक्त्रम्", "gram": "ac. sg. m. comp.", "es": "con la boca de fuego ardiente", "analisis": "dīpta (ardiente) + hutāśa (fuego, «el que come la oblación») + vaktra (boca)"}, {"iast": "sva-tejasā", "sa": "स्वतेजसा", "gram": "instr. sg. n. comp.", "es": "con su propio resplandor", "ref": "tejas", "analisis": "sva (propio) + tejas (esplendor)"}, {"iast": "viśvam", "sa": "विश्वम्", "gram": "ac. sg. n.", "es": "el universo"}, {"iast": "idam", "sa": "इदम्", "gram": "ac. sg. n. pron.", "es": "este"}, {"iast": "tapantam", "sa": "तपन्तम्", "gram": "ac. sg. m. part. pres.", "es": "abrasando", "analisis": "√tap (calentar, quemar)"}], "nota": "<p><em>Hutāśa</em>, «el que come la oblación», es un nombre del fuego del sacrificio: la boca de Kṛṣṇa es el fuego en el que todo se ofrece, y la imagen prepara la de las bocas que devoran a los guerreros (<a class=\"vref\" href=\"capitulo-11.html#v26\" data-v=\"11.26\">11.26</a>–<a class=\"vref\" href=\"capitulo-11.html#v30\" data-v=\"11.30\">11.30</a>). <em>Śaśin</em>, «el que tiene la liebre», es la luna, por la figura que se ve en sus manchas.</p>", "interp": [{"titulo": "El sol y la luna por ojos", "html": "<p>La imagen tiene una raíz védica: en el himno del Puruṣa, el ser primordial de cuyo sacrificio nace el mundo, «la luna nació de su mente; de su ojo nació el sol» (<em>Ṛg-veda</em> 10.90.13). La forma universal de la Gītā retoma ese cuerpo cósmico, con miles de cabezas, ojos y pies (10.90.1), pero lo convierte en algo que se puede ver, y que además es Kṛṣṇa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 20, "hablante": "arjuna", "sa": ["द्यावापृथिव्योरिदमन्तरं हि व्याप्तं त्वयैकेन दिशश्च सर्वाः ।", "दृष्ट्वाद्भुतं रूपमुग्रं तवेदं लोकत्रयं प्रव्यथितं महात्मन् ॥२०॥"], "iast": ["dyāvā-pṛthivyor idam antaraṃ hi vyāptaṃ tvayaikena diśaś ca sarvāḥ", "dṛṣṭvādbhutaṃ rūpam ugraṃ tavedaṃ loka-trayaṃ pravyathitaṃ mahātman"], "rojas": [], "t": "<span class=\"vt-parte\">Porque este espacio entre el cielo y la tierra, y todas las direcciones, los llenas tú solo; y al ver esta forma tuya, prodigiosa y terrible, los tres mundos tiemblan, oh <a class=\"t\" href=\"glosario.html#mahatman\" data-t=\"mahatman\">Mahātman</a>.</span>", "palabras": [{"iast": "dyāvā-pṛthivyoḥ", "sa": "द्यावापृथिव्योः", "gram": "gen. du. f. comp.", "es": "del cielo y la tierra", "analisis": "dyāvā (cielo) + pṛthivī (tierra), compuesto dual"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "este"}, {"iast": "antaram", "sa": "अन्तरम्", "gram": "nom. sg. n.", "es": "espacio intermedio"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque, en verdad"}, {"iast": "vyāptam", "sa": "व्याप्तम्", "gram": "nom. sg. n. ppp", "es": "lleno, penetrado", "analisis": "vi-√āp (alcanzar, llenar)"}, {"iast": "tvayā", "sa": "त्वया", "gram": "instr. sg. pron.", "es": "por ti"}, {"iast": "ekena", "sa": "एकेन", "gram": "instr. sg. m.", "es": "solo, uno"}, {"iast": "diśaḥ", "sa": "दिशः", "gram": "nom. pl. f.", "es": "las direcciones, los puntos cardinales"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "sarvāḥ", "sa": "सर्वाः", "gram": "nom. pl. f.", "es": "todas"}, {"iast": "dṛṣṭvā", "sa": "दृष्ट्वा", "gram": "abs.", "es": "al ver", "analisis": "√dṛś (ver)"}, {"iast": "adbhutam", "sa": "अद्भुतम्", "gram": "ac. sg. n.", "es": "prodigiosa, asombrosa"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "ac. sg. n.", "es": "forma"}, {"iast": "ugram", "sa": "उग्रम्", "gram": "ac. sg. n.", "es": "terrible"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "idam", "sa": "इदम्", "gram": "ac. sg. n. pron.", "es": "esta"}, {"iast": "loka-trayam", "sa": "लोकत्रयम्", "gram": "nom. sg. n. comp.", "es": "los tres mundos", "analisis": "loka (mundo) + traya (tríada)"}, {"iast": "pravyathitam", "sa": "प्रव्यथितम्", "gram": "nom. sg. n. ppp", "es": "tiembla, está turbado", "analisis": "pra-√vyath (temblar, angustiarse)"}, {"iast": "mahātman", "sa": "महात्मन्", "gram": "voc. sg. m.", "es": "oh Mahātman, oh gran ser", "ref": "mahatman", "analisis": "mahā (grande) + ātman (ser, sí-mismo)"}], "nota": "<p><em>Dyāvā-pṛthivī</em>, «el cielo y la tierra», es un compuesto dual de origen védico, en el que las dos mitades del mundo forman pareja. Los tres mundos (<em>loka-traya</em>) son el cielo, el espacio intermedio y la tierra. <em>Pravyathita</em>, «turbado, tembloroso», es el verbo que define el capítulo: vuelve para los mundos en <a class=\"vref\" href=\"capitulo-11.html#v23\" data-v=\"11.23\">11.23</a>, para el propio Arjuna en <a class=\"vref\" href=\"capitulo-11.html#v24\" data-v=\"11.24\">11.24</a> y para su mente, turbada todavía por el miedo, en <a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>. <em>Mahātman</em>, «gran ser», es el título que <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a> daba al sabio que sabe que Vāsudeva es todo; aquí Arjuna se lo da a Kṛṣṇa.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 21, "hablante": "arjuna", "sa": ["अमी हि त्वां सुरसङ्घा विशन्ति केचिद्भीताः प्राञ्जलयो गृणन्ति ।", "स्वस्तीत्युक्त्वा महर्षिसिद्धसङ्घाः स्तुवन्ति त्वां स्तुतिभिः पुष्कलाभिः ॥२१॥"], "iast": ["amī hi tvāṃ sura-saṅghā viśanti kecid bhītāḥ prāñjalayo gṛṇanti", "svastīty uktvā maharṣi-siddha-saṅghāḥ stuvanti tvāṃ stutibhiḥ puṣkalābhiḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Esas multitudes de <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a> entran en ti; algunos, atemorizados, te invocan con las manos juntas; y, diciendo «¡salud!», las multitudes de grandes <a class=\"t\" href=\"glosario.html#rsi\" data-t=\"rsi\">videntes</a> y de <a class=\"t\" href=\"glosario.html#siddha\" data-t=\"siddha\">perfectos</a> te alaban con himnos abundantes.</span>", "palabras": [{"iast": "amī", "sa": "अमी", "gram": "nom. pl. m. pron.", "es": "aquellos, esos"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "en verdad"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "en ti"}, {"iast": "sura-saṅghāḥ", "sa": "सुरसङ्घाः", "gram": "nom. pl. m. comp.", "es": "las multitudes de dioses", "ref": "deva", "analisis": "sura (dios) + saṅgha (multitud)"}, {"iast": "viśanti", "sa": "विशन्ति", "gram": "3 pl. pres. act.", "es": "entran", "analisis": "√viś (entrar)"}, {"iast": "kecit", "sa": "केचित्", "gram": "nom. pl. m. pron.", "es": "algunos"}, {"iast": "bhītāḥ", "sa": "भीताः", "gram": "nom. pl. m. ppp", "es": "atemorizados", "analisis": "√bhī (temer)"}, {"iast": "prāñjalayaḥ", "sa": "प्राञ्जलयः", "gram": "nom. pl. m.", "es": "con las manos juntas", "analisis": "pra + añjali (las palmas unidas en saludo)"}, {"iast": "gṛṇanti", "sa": "गृणन्ति", "gram": "3 pl. pres. act.", "es": "invocan, cantan", "analisis": "√gṝ (invocar, alabar)"}, {"iast": "svasti", "sa": "स्वस्ति", "gram": "ind.", "es": "¡salud!, ¡bienestar!", "analisis": "su (bien) + asti (es)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra la cita)"}, {"iast": "uktvā", "sa": "उक्त्वा", "gram": "abs.", "es": "diciendo", "analisis": "√vac (decir)"}, {"iast": "maharṣi-siddha-saṅghāḥ", "sa": "महर्षिसिद्धसङ्घाः", "gram": "nom. pl. m. comp.", "es": "las multitudes de grandes videntes y de perfectos", "ref": "siddha", "analisis": "mahā (grande) + ṛṣi (vidente) + siddha (perfecto) + saṅgha (multitud)"}, {"iast": "stuvanti", "sa": "स्तुवन्ति", "gram": "3 pl. pres. act.", "es": "alaban", "analisis": "√stu (alabar)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti"}, {"iast": "stutibhiḥ", "sa": "स्तुतिभिः", "gram": "instr. pl. f.", "es": "con himnos de alabanza", "analisis": "√stu"}, {"iast": "puṣkalābhiḥ", "sa": "पुष्कलाभिः", "gram": "instr. pl. f.", "es": "abundantes, espléndidos"}], "nota": "<p><em>Svasti</em>, «¡que haya bien!», es la fórmula de bendición con que se abren y cierran los ritos. El verso muestra dos maneras de estar ante la forma universal: los dioses que entran en ella, algunos con miedo, y los sabios que, desde fuera, la alaban; la misma escena se repite, ya con los guerreros, en <a class=\"vref\" href=\"capitulo-11.html#v26\" data-v=\"11.26\">11.26</a>–<a class=\"vref\" href=\"capitulo-11.html#v29\" data-v=\"11.29\">11.29</a> (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la adelantan aquí: los dioses que entran son los guerreros, dioses encarnados como hombres para aliviar a la tierra de su carga, y los sabios dicen «¡salud!» al ver los presagios de la batalla), y en <a class=\"vref\" href=\"capitulo-11.html#v36\" data-v=\"11.36\">11.36</a> Arjuna volverá a ver a los perfectos inclinándose.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 22, "hablante": "arjuna", "sa": ["रुद्रादित्या वसवो ये च साध्या विश्वेऽश्विनौ मरुतश्चोष्मपाश्च ।", "गन्धर्वयक्षासुरसिद्धसङ्घा वीक्षन्ते त्वां विस्मिताश्चैव सर्वे ॥२२॥"], "iast": ["rudrādityā vasavo ye ca sādhyā viśve 'śvinau marutaś coṣmapāś ca", "gandharva-yakṣāsura-siddha-saṅghā vīkṣante tvāṃ vismitāś caiva sarve"], "rojas": [], "t": "<span class=\"vt-parte\">Los <a class=\"t\" href=\"glosario.html#rudra\" data-t=\"rudra\">Rudras</a> y los <a class=\"t\" href=\"glosario.html#aditya\" data-t=\"aditya\">Ādityas</a>, los <a class=\"t\" href=\"glosario.html#vasu\" data-t=\"vasu\">Vasus</a> y los <a class=\"t\" href=\"glosario.html#sadhya\" data-t=\"sadhya\">Sādhyas</a>, los <a class=\"t\" href=\"glosario.html#visvedeva\" data-t=\"visvedeva\">Viśvedevas</a>, los dos <a class=\"t\" href=\"glosario.html#asvins\" data-t=\"asvins\">Aśvins</a>, los <a class=\"t\" href=\"glosario.html#marut\" data-t=\"marut\">Maruts</a> y los <a class=\"t\" href=\"glosario.html#usmapa\" data-t=\"usmapa\">Ūṣmapās</a>, las multitudes de <a class=\"t\" href=\"glosario.html#gandharva\" data-t=\"gandharva\">gandharvas</a>, <a class=\"t\" href=\"glosario.html#kubera\" data-t=\"kubera\">yakṣas</a>, <a class=\"t\" href=\"glosario.html#asura\" data-t=\"asura\">asuras</a> y <a class=\"t\" href=\"glosario.html#siddha\" data-t=\"siddha\">perfectos</a>, todos te contemplan asombrados.</span>", "palabras": [{"iast": "rudra-ādityāḥ", "sa": "रुद्रादित्याः", "gram": "nom. pl. m. comp.", "es": "los Rudras y los Ādityas", "ref": "rudra", "analisis": "rudra + āditya"}, {"iast": "vasavaḥ", "sa": "वसवः", "gram": "nom. pl. m.", "es": "los Vasus", "ref": "vasu"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. rel.", "es": "los que"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "sādhyāḥ", "sa": "साध्याः", "gram": "nom. pl. m.", "es": "los Sādhyas", "ref": "sadhya"}, {"iast": "viśve", "sa": "विश्वे", "gram": "nom. pl. m.", "es": "los Viśvedevas", "ref": "visvedeva", "analisis": "viśve devāḥ, «todos los dioses»"}, {"iast": "aśvinau", "sa": "अश्विनौ", "gram": "nom. du. m.", "es": "los dos Aśvins", "ref": "asvins"}, {"iast": "marutaḥ", "sa": "मरुतः", "gram": "nom. pl. m.", "es": "los Maruts", "ref": "marut"}, {"iast": "ūṣmapāḥ", "sa": "ऊष्मपाः", "gram": "nom. pl. m.", "es": "los Ūṣmapās, «los que beben el vapor»", "ref": "usmapa", "analisis": "ūṣman (calor, vapor) + pa (que bebe)"}, {"iast": "gandharva-yakṣa-asura-siddha-saṅghāḥ", "sa": "गन्धर्वयक्षासुरसिद्धसङ्घाः", "gram": "nom. pl. m. comp.", "es": "las multitudes de gandharvas, yakṣas, asuras y perfectos", "ref": "gandharva", "analisis": "gandharva + yakṣa + asura + siddha + saṅgha (multitud)"}, {"iast": "vīkṣante", "sa": "वीक्षन्ते", "gram": "3 pl. pres. med.", "es": "contemplan", "analisis": "vi-√īkṣ (mirar)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti"}, {"iast": "vismitāḥ", "sa": "विस्मिताः", "gram": "nom. pl. m. ppp", "es": "asombrados", "analisis": "vi-√smi (asombrarse)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "en verdad"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m.", "es": "todos"}], "nota": "<p>El verso pasa revista a las clases de seres divinos del mundo védico y épico. Varias ya han aparecido en la lista de manifestaciones: Kṛṣṇa era Śaṅkara entre los Rudras, Viṣṇu entre los Ādityas, Pāvaka entre los Vasus, Marīci entre los Maruts (<a class=\"vref\" href=\"capitulo-10.html#v21\" data-v=\"10.21\">10.21</a>–<a class=\"vref\" href=\"capitulo-10.html#v23\" data-v=\"10.23\">10.23</a>); ahora todas lo miran a él. <em>Viśve</em>, «todos», es la forma abreviada de <em>viśve devāḥ</em>, los Viśvedevas. Los Sādhyas, los Viśvedevas y los Ūṣmapās sólo aparecen en este verso de la Gītā.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 23, "hablante": "arjuna", "sa": ["रूपं महत्ते बहुवक्त्रनेत्रं महाबाहो बहुबाहूरुपादम् ।", "बहूदरं बहुदंष्ट्राकरालं दृष्ट्वा लोकाः प्रव्यथितास्तथाहम् ॥२३॥"], "iast": ["rūpaṃ mahat te bahu-vaktra-netraṃ mahā-bāho bahu-bāhūru-pādam", "bahūdaraṃ bahu-daṃṣṭrā-karālaṃ dṛṣṭvā lokāḥ pravyathitās tathāham"], "rojas": [], "t": "<span class=\"vt-parte\">Al ver tu forma inmensa, de muchas bocas y ojos, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, de muchos brazos, muslos y pies, de muchos vientres, terrible por sus muchos colmillos, los mundos tiemblan, y yo también.</span>", "palabras": [{"iast": "rūpam", "sa": "रूपम्", "gram": "ac. sg. n.", "es": "forma"}, {"iast": "mahat", "sa": "महत्", "gram": "ac. sg. n.", "es": "grande, inmensa"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "bahu-vaktra-netram", "sa": "बहुवक्त्रनेत्रम्", "gram": "ac. sg. n. comp.", "es": "de muchas bocas y ojos", "analisis": "bahu (mucho) + vaktra (boca) + netra (ojo)"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu, oh tú, de brazos poderosos", "ref": "mahabaho", "analisis": "mahā (grande) + bāhu (brazo)"}, {"iast": "bahu-bāhu-ūru-pādam", "sa": "बहुबाहूरुपादम्", "gram": "ac. sg. n. comp.", "es": "de muchos brazos, muslos y pies", "analisis": "bahu + bāhu (brazo) + ūru (muslo) + pāda (pie)"}, {"iast": "bahu-udaram", "sa": "बहूदरम्", "gram": "ac. sg. n. comp.", "es": "de muchos vientres", "analisis": "bahu + udara (vientre)"}, {"iast": "bahu-daṃṣṭrā-karālam", "sa": "बहुदंष्ट्राकरालम्", "gram": "ac. sg. n. comp.", "es": "terrible por sus muchos colmillos", "analisis": "bahu + daṃṣṭrā (colmillo) + karāla (que muestra los dientes, espantoso)"}, {"iast": "dṛṣṭvā", "sa": "दृष्ट्वा", "gram": "abs.", "es": "al ver"}, {"iast": "lokāḥ", "sa": "लोकाः", "gram": "nom. pl. m.", "es": "los mundos, las gentes"}, {"iast": "pravyathitāḥ", "sa": "प्रव्यथिताः", "gram": "nom. pl. m. ppp", "es": "tiemblan", "analisis": "pra-√vyath"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "y también"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}], "nota": "<p><em>Karāla</em> es «el que enseña los dientes», «espantoso»; con <em>daṃṣṭrā</em>, «colmillo», la imagen es la de unas fauces. Hasta aquí Arjuna ha descrito a los demás; con «y yo también» entra él mismo en la escena del espanto. <em>Lokāḥ</em>, «los mundos», puede entenderse también de los seres que los habitan: así lo glosan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> («los vivientes del mundo») y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>.</p>", "interp": [{"titulo": "Del asombro al espanto", "html": "<p>El himno cambia de tono a partir de este verso. En <a class=\"vref\" href=\"capitulo-11.html#v15\" data-v=\"11.15\">11.15</a>–<a class=\"vref\" href=\"capitulo-11.html#v22\" data-v=\"11.22\">11.22</a> dominaba el asombro: Arjuna veía todo en Kṛṣṇa y lo nombraba con los títulos más altos. Ahora aparecen los colmillos, las bocas abiertas, el fuego del fin del tiempo, y el que ve ya no puede sostener la mirada. La misma forma que contiene el universo es la que lo devora; los versos siguientes (<a class=\"vref\" href=\"capitulo-11.html#v26\" data-v=\"11.26\">11.26</a>–<a class=\"vref\" href=\"capitulo-11.html#v30\" data-v=\"11.30\">11.30</a>) lo mostrarán con los guerreros de los dos ejércitos.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 24, "hablante": "arjuna", "sa": ["नभःस्पृशं दीप्तमनेकवर्णं व्यात्ताननं दीप्तविशालनेत्रम् ।", "दृष्ट्वा हि त्वां प्रव्यथितान्तरात्मा धृतिं न विन्दामि शमं च विष्णो ॥२४॥"], "iast": ["nabhaḥ-spṛśaṃ dīptam aneka-varṇaṃ vyāttānanaṃ dīpta-viśāla-netram", "dṛṣṭvā hi tvāṃ pravyathitāntar-ātmā dhṛtiṃ na vindāmi śamaṃ ca viṣṇo"], "rojas": [], "t": "<span class=\"vt-parte\">Porque, al verte tocando el cielo, resplandeciente, de muchos colores, con la boca abierta y los ojos inmensos y llameantes, tiemblo en lo más hondo de mí y no hallo firmeza ni calma, oh <a class=\"t\" href=\"glosario.html#visnu\" data-t=\"visnu\">Viṣṇu</a>.</span>", "palabras": [{"iast": "nabhaḥ-spṛśam", "sa": "नभःस्पृशम्", "gram": "ac. sg. m. comp.", "es": "que toca el cielo", "analisis": "nabhas (cielo) + spṛś (que toca)"}, {"iast": "dīptam", "sa": "दीप्तम्", "gram": "ac. sg. m. ppp", "es": "resplandeciente", "analisis": "√dīp (arder, brillar)"}, {"iast": "aneka-varṇam", "sa": "अनेकवर्णम्", "gram": "ac. sg. m. comp.", "es": "de muchos colores", "analisis": "aneka (muchos) + varṇa (color)"}, {"iast": "vyātta-ānanam", "sa": "व्यात्ताननम्", "gram": "ac. sg. m. comp.", "es": "con la boca abierta", "analisis": "vyātta (abierto, de vi-ā-√dā) + ānana (boca, rostro)"}, {"iast": "dīpta-viśāla-netram", "sa": "दीप्तविशालनेत्रम्", "gram": "ac. sg. m. comp.", "es": "de ojos inmensos y llameantes", "analisis": "dīpta (ardiente) + viśāla (vasto) + netra (ojo)"}, {"iast": "dṛṣṭvā", "sa": "दृष्ट्वा", "gram": "abs.", "es": "al ver"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti"}, {"iast": "pravyathita-antar-ātmā", "sa": "प्रव्यथितान्तरात्मा", "gram": "nom. sg. m. comp.", "es": "estremecido en lo más hondo", "ref": "atman", "analisis": "pravyathita (turbado) + antar (interior) + ātman (ser)"}, {"iast": "dhṛtim", "sa": "धृतिम्", "gram": "ac. sg. f.", "es": "firmeza", "analisis": "√dhṛ (sostener)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vindāmi", "sa": "विन्दामि", "gram": "1 sg. pres. act.", "es": "hallo", "analisis": "√vid (encontrar)"}, {"iast": "śamam", "sa": "शमम्", "gram": "ac. sg. m.", "es": "calma", "analisis": "√śam (aquietarse)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "viṣṇo", "sa": "विष्णो", "gram": "voc. sg. m.", "es": "oh Viṣṇu", "ref": "visnu"}], "nota": "<p><em>Antar-ātman</em>, «el ser interior», es aquí el ánimo de Arjuna, lo más íntimo de él. <em>Dhṛti</em>, la firmeza, y <em>śama</em>, la calma, son precisamente dos de las cualidades que el yogui debía cultivar (<a class=\"vref\" href=\"capitulo-06.html#v3\" data-v=\"6.3\">6.3</a>, <a class=\"vref\" href=\"capitulo-06.html#v25\" data-v=\"6.25\">6.25</a>); ante la visión, Arjuna las pierde. Es la primera vez que Arjuna llama a Kṛṣṇa «Viṣṇu»; lo hará otra vez en <a class=\"vref\" href=\"capitulo-11.html#v30\" data-v=\"11.30\">11.30</a>.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 25, "hablante": "arjuna", "sa": ["दंष्ट्राकरालानि च ते मुखानि दृष्ट्वैव कालानलसन्निभानि ।", "दिशो न जाने न लभे च शर्म प्रसीद देवेश जगन्निवास ॥२५॥"], "iast": ["daṃṣṭrā-karālāni ca te mukhāni dṛṣṭvaiva kālānala-sannibhāni", "diśo na jāne na labhe ca śarma prasīda deveśa jagan-nivāsa"], "rojas": [], "t": "<span class=\"vt-parte\">Al ver tus bocas, terribles por sus colmillos, semejantes al fuego del fin del tiempo, ya no sé dónde estoy ni hallo amparo. ¡Ten piedad, señor de los dioses, morada del universo!</span>", "palabras": [{"iast": "daṃṣṭrā-karālāni", "sa": "दंष्ट्राकरालानि", "gram": "ac. pl. n. comp.", "es": "terribles por sus colmillos", "analisis": "daṃṣṭrā (colmillo) + karāla (espantoso)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tus"}, {"iast": "mukhāni", "sa": "मुखानि", "gram": "ac. pl. n.", "es": "bocas"}, {"iast": "dṛṣṭvā", "sa": "दृष्ट्वा", "gram": "abs.", "es": "al ver"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "nada más, sólo"}, {"iast": "kāla-anala-sannibhāni", "sa": "कालानलसन्निभानि", "gram": "ac. pl. n. comp.", "es": "semejantes al fuego del fin del tiempo", "ref": "kala", "analisis": "kāla (tiempo, el fin de los tiempos) + anala (fuego) + sannibha (semejante)"}, {"iast": "diśaḥ", "sa": "दिशः", "gram": "ac. pl. f.", "es": "las direcciones"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "jāne", "sa": "जाने", "gram": "1 sg. pres. med.", "es": "conozco, sé", "analisis": "√jñā (conocer)"}, {"iast": "labhe", "sa": "लभे", "gram": "1 sg. pres. med.", "es": "obtengo, hallo", "analisis": "√labh (obtener)"}, {"iast": "śarma", "sa": "शर्म", "gram": "ac. sg. n.", "es": "amparo, refugio, alivio", "analisis": "śarman"}, {"iast": "prasīda", "sa": "प्रसीद", "gram": "2 sg. impv. act.", "es": "ten piedad, sé propicio", "analisis": "pra-√sad (calmarse, ser favorable)"}, {"iast": "deva-īśa", "sa": "देवेश", "gram": "voc. sg. m. comp.", "es": "oh señor de los dioses", "analisis": "deva (dios) + īśa (señor)"}, {"iast": "jagan-nivāsa", "sa": "जगन्निवास", "gram": "voc. sg. m. comp.", "es": "oh morada del universo", "analisis": "jagat (mundo) + nivāsa (morada)"}], "nota": "<p><em>Kālānala</em>, «el fuego del tiempo», es el fuego que, al final de un ciclo, consume los mundos (véanse <a class=\"t\" href=\"glosario.html#kala\" data-t=\"kala\">kāla</a> y <a class=\"t\" href=\"glosario.html#pralaya\" data-t=\"pralaya\">pralaya</a>): Arjuna ve en las bocas de Kṛṣṇa la disolución del universo, lo que Kṛṣṇa dirá con palabras en <a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a>: «soy el tiempo». <em>Diśo na jāne</em>, literalmente «no conozco las direcciones», es la expresión del que ha perdido la orientación. <em>Prasīda</em>, «sé propicio, cálmate», vuelve como estribillo en <a class=\"vref\" href=\"capitulo-11.html#v31\" data-v=\"11.31\">11.31</a> y <a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>. «Señor de los dioses» y «morada del universo» se repiten, en ese orden, en <a class=\"vref\" href=\"capitulo-11.html#v37\" data-v=\"11.37\">11.37</a> y <a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 26, "hablante": "arjuna", "sa": ["अमी च त्वां धृतराष्ट्रस्य पुत्राः सर्वे सहैवावनिपालसङ्घैः ।", "भीष्मो द्रोणः सूतपुत्रस्तथासौ सहास्मदीयैरपि योधमुख्यैः ॥२६॥"], "iast": ["amī ca tvāṃ dhṛtarāṣṭrasya putrāḥ sarve sahaivāvanipāla-saṅghaiḥ", "bhīṣmo droṇaḥ sūta-putras tathāsau sahāsmadīyair api yodha-mukhyaiḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Y todos esos hijos de <a class=\"t\" href=\"glosario.html#dhrtarastra\" data-t=\"dhrtarastra\">Dhṛtarāṣṭra</a>, junto con las huestes de los reyes; <a class=\"t\" href=\"glosario.html#bhisma\" data-t=\"bhisma\">Bhīṣma</a>, <a class=\"t\" href=\"glosario.html#drona\" data-t=\"drona\">Droṇa</a> y también ese <a class=\"t\" href=\"glosario.html#karna\" data-t=\"karna\">hijo del auriga</a>, con los principales guerreros de los nuestros,</span>", "palabras": [{"iast": "amī", "sa": "अमी", "gram": "nom. pl. m. pron.", "es": "esos, aquéllos"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti", "analisis": "complemento de viśanti en el verso siguiente"}, {"iast": "dhṛtarāṣṭrasya", "sa": "धृतराष्ट्रस्य", "gram": "gen. sg. m.", "es": "de Dhṛtarāṣṭra", "ref": "dhrtarastra"}, {"iast": "putrāḥ", "sa": "पुत्राः", "gram": "nom. pl. m.", "es": "los hijos", "ref": "dhartarastras"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m.", "es": "todos"}, {"iast": "saha", "sa": "सह", "gram": "ind.", "es": "junto con"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "precisamente, también"}, {"iast": "avani-pāla-saṅghaiḥ", "sa": "अवनिपालसङ्घैः", "gram": "instr. pl. m.", "es": "con las huestes de los reyes", "analisis": "avani (tierra) + pāla (protector): rey; saṅgha (multitud, hueste)"}, {"iast": "bhīṣmaḥ", "sa": "भीष्मः", "gram": "nom. sg. m.", "es": "Bhīṣma", "ref": "bhisma"}, {"iast": "droṇaḥ", "sa": "द्रोणः", "gram": "nom. sg. m.", "es": "Droṇa", "ref": "drona"}, {"iast": "sūta-putraḥ", "sa": "सूतपुत्रः", "gram": "nom. sg. m.", "es": "el hijo del auriga", "ref": "karna", "analisis": "sūta (auriga) + putra (hijo): Karṇa, criado por el auriga Adhiratha"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "también, así"}, {"iast": "asau", "sa": "असौ", "gram": "nom. sg. m. pron.", "es": "ese, aquél"}, {"iast": "saha", "sa": "सह", "gram": "ind.", "es": "junto con"}, {"iast": "asmadīyaiḥ", "sa": "अस्मदीयैः", "gram": "instr. pl. m.", "es": "nuestros", "analisis": "asmad (nosotros) + -īya (perteneciente a)"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "también"}, {"iast": "yodha-mukhyaiḥ", "sa": "योधमुख्यैः", "gram": "instr. pl. m.", "es": "con los principales guerreros", "analisis": "yodha (guerrero) + mukhya (principal)"}], "nota": "<p>Los versos 26 y 27 forman una sola frase: el verbo, «entran», llega en el verso siguiente. <em>Avani-pāla</em>, «protector de la tierra», es el rey. <em>Sūta-putra</em>, «hijo del auriga», es <a class=\"t\" href=\"glosario.html#karna\" data-t=\"karna\">Karṇa</a>, al que crió el auriga Adhiratha; sus enemigos lo llaman así para rebajarlo, aunque en realidad es hijo de Kuntī y del Sol. Arjuna no ve entrar en las bocas sólo a los del bando contrario: con ellos van «los principales guerreros de los nuestros».</p>", "interp": [{"titulo": "La batalla vista antes de librarse", "html": "<p>Lo que Arjuna ve es el desenlace de una guerra que todavía no ha empezado. Los nombres son los de los grandes guerreros <a class=\"t\" href=\"glosario.html#kauravas\" data-t=\"kauravas\">kauravas</a> —su abuelo <a class=\"t\" href=\"glosario.html#bhisma\" data-t=\"bhisma\">Bhīṣma</a>, su maestro <a class=\"t\" href=\"glosario.html#drona\" data-t=\"drona\">Droṇa</a>, su rival <a class=\"t\" href=\"glosario.html#karna\" data-t=\"karna\">Karṇa</a>—, los mismos cuya muerte no quería causar en el capítulo 1 (<a class=\"vref\" href=\"capitulo-01.html#v26\" data-v=\"1.26\">1.26</a>–<a class=\"vref\" href=\"capitulo-01.html#v35\" data-v=\"1.35\">1.35</a>). Pero la visión no distingue bandos: también los «nuestros» caen. La forma universal muestra la guerra como la verá el tiempo, no como la ven los que combaten.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 27, "hablante": "arjuna", "sa": ["वक्त्राणि ते त्वरमाणा विशन्ति दंष्ट्राकरालानि भयानकानि ।", "केचिद्विलग्ना दशनान्तरेषु सन्दृश्यन्ते चूर्णितैरुत्तमाङ्गैः ॥२७॥"], "iast": ["vaktrāṇi te tvaramāṇā viśanti daṃṣṭrā-karālāni bhayānakāni", "kecid vilagnā daśanāntareṣu sandṛśyante cūrṇitair uttamāṅgaiḥ"], "rojas": [], "t": "<span class=\"vt-parte\">se precipitan en tus bocas, terribles por sus colmillos, espantosas. Algunos aparecen prendidos entre tus dientes, con las cabezas trituradas.</span>", "palabras": [{"iast": "vaktrāṇi", "sa": "वक्त्राणि", "gram": "ac. pl. n.", "es": "en las bocas", "analisis": "vaktra (boca, rostro)"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tus"}, {"iast": "tvaramāṇāḥ", "sa": "त्वरमाणाः", "gram": "nom. pl. m. part. pres. med.", "es": "precipitándose", "analisis": "√tvar (apresurarse)"}, {"iast": "viśanti", "sa": "विशन्ति", "gram": "3 pl. pres. act.", "es": "entran", "analisis": "√viś (entrar)"}, {"iast": "daṃṣṭrā-karālāni", "sa": "दंष्ट्राकरालानि", "gram": "ac. pl. n.", "es": "terribles por los colmillos", "analisis": "daṃṣṭrā (colmillo) + karāla (de dientes salientes, espantoso)"}, {"iast": "bhayānakāni", "sa": "भयानकानि", "gram": "ac. pl. n.", "es": "espantosas", "analisis": "bhaya (miedo)"}, {"iast": "kecit", "sa": "केचित्", "gram": "nom. pl. m. pron. indef.", "es": "algunos"}, {"iast": "vilagnāḥ", "sa": "विलग्नाः", "gram": "nom. pl. m. part. pas.", "es": "prendidos, atrapados", "analisis": "vi-√lag (adherirse)"}, {"iast": "daśana-antareṣu", "sa": "दशनान्तरेषु", "gram": "loc. pl. n.", "es": "entre los dientes", "analisis": "daśana (diente) + antara (espacio intermedio)"}, {"iast": "sandṛśyante", "sa": "सन्दृश्यन्ते", "gram": "3 pl. pres. pas.", "es": "se ven, aparecen", "analisis": "sam-√dṛś (ver)"}, {"iast": "cūrṇitaiḥ", "sa": "चूर्णितैः", "gram": "instr. pl. n. part. pas.", "es": "trituradas", "analisis": "cūrṇa (polvo): reducido a polvo"}, {"iast": "uttama-aṅgaiḥ", "sa": "उत्तमाङ्गैः", "gram": "instr. pl. n.", "es": "con las cabezas", "analisis": "uttama (el más alto) + aṅga (miembro): la cabeza"}], "nota": "<p><em>Uttamāṅga</em>, «el miembro más alto», es la cabeza. <em>Daṃṣṭrā-karāla</em>: «terribles por los colmillos», ya en <a class=\"vref\" href=\"capitulo-11.html#v25\" data-v=\"11.25\">11.25</a>. El presente, «entran», «aparecen», es el de la visión: Arjuna describe lo que tiene delante.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 28, "hablante": "arjuna", "sa": ["यथा नदीनां बहवोऽम्बुवेगाः समुद्रमेवाभिमुखा द्रवन्ति ।", "तथा तवामी नरलोकवीरा विशन्ति वक्त्राण्यभिविज्वलन्ति ॥२८॥"], "iast": ["yathā nadīnāṃ bahavo 'mbu-vegāḥ samudram evābhimukhā dravanti", "tathā tavāmī nara-loka-vīrā viśanti vaktrāṇy abhivijvalanti"], "rojas": [], "t": "<span class=\"vt-parte\">Como las muchas corrientes de los ríos corren hacia el océano, así entran esos héroes del mundo de los hombres en tus bocas, que llamean por todas partes.</span>", "palabras": [{"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "como"}, {"iast": "nadīnām", "sa": "नदीनाम्", "gram": "gen. pl. f.", "es": "de los ríos"}, {"iast": "bahavaḥ", "sa": "बहवः", "gram": "nom. pl. m.", "es": "muchas"}, {"iast": "ambu-vegāḥ", "sa": "अम्बुवेगाः", "gram": "nom. pl. m.", "es": "corrientes", "analisis": "ambu (agua) + vega (ímpetu, corriente)"}, {"iast": "samudram", "sa": "समुद्रम्", "gram": "ac. sg. m.", "es": "al océano"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "precisamente"}, {"iast": "abhimukhāḥ", "sa": "अभिमुखाः", "gram": "nom. pl. m.", "es": "vueltas hacia, en dirección a"}, {"iast": "dravanti", "sa": "द्रवन्ति", "gram": "3 pl. pres. act.", "es": "corren", "analisis": "√dru (correr, fluir)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tus"}, {"iast": "amī", "sa": "अमी", "gram": "nom. pl. m. pron.", "es": "esos"}, {"iast": "nara-loka-vīrāḥ", "sa": "नरलोकवीराः", "gram": "nom. pl. m.", "es": "los héroes del mundo de los hombres", "analisis": "nara (hombre) + loka (mundo) + vīra (héroe)"}, {"iast": "viśanti", "sa": "विशन्ति", "gram": "3 pl. pres. act.", "es": "entran"}, {"iast": "vaktrāṇi", "sa": "वक्त्राणि", "gram": "ac. pl. n.", "es": "en las bocas"}, {"iast": "abhivijvalanti", "sa": "अभिविज्वलन्ति", "gram": "ac. pl. n. part. pres.", "es": "llameantes", "analisis": "abhi-vi-√jval (arder por todas partes)"}], "nota": "<p><em>Abhivijvalanti</em> es un participio que concuerda con <em>vaktrāṇi</em>: no son los héroes los que arden, sino las bocas. La imagen de los ríos que van al mar es la misma de <a class=\"vref\" href=\"capitulo-02.html#v70\" data-v=\"2.70\">2.70</a>, aunque allí el océano permanece inmóvil y aquí devora.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 29, "hablante": "arjuna", "sa": ["यथा प्रदीप्तं ज्वलनं पतङ्गा विशन्ति नाशाय समृद्धवेगाः ।", "तथैव नाशाय विशन्ति लोकास्तवापि वक्त्राणि समृद्धवेगाः ॥२९॥"], "iast": ["yathā pradīptaṃ jvalanaṃ pataṅgā viśanti nāśāya samṛddha-vegāḥ", "tathaiva nāśāya viśanti lokās tavāpi vaktrāṇi samṛddha-vegāḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Como las polillas se lanzan con ímpetu creciente al fuego ardiente para perecer, así entran también los mundos en tus bocas, con ímpetu creciente, para perecer.</span>", "palabras": [{"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "como"}, {"iast": "pradīptam", "sa": "प्रदीप्तम्", "gram": "ac. sg. m. part. pas.", "es": "encendido, ardiente", "analisis": "pra-√dīp (arder)"}, {"iast": "jvalanam", "sa": "ज्वलनम्", "gram": "ac. sg. m.", "es": "el fuego", "analisis": "√jval (llamear)"}, {"iast": "pataṅgāḥ", "sa": "पतङ्गाः", "gram": "nom. pl. m.", "es": "las polillas", "analisis": "pataṅga (insecto volador, polilla)"}, {"iast": "viśanti", "sa": "विशन्ति", "gram": "3 pl. pres. act.", "es": "entran"}, {"iast": "nāśāya", "sa": "नाशाय", "gram": "dat. sg. m.", "es": "para perecer", "analisis": "nāśa (destrucción)"}, {"iast": "samṛddha-vegāḥ", "sa": "समृद्धवेगाः", "gram": "nom. pl. m.", "es": "con ímpetu creciente", "analisis": "samṛddha (aumentado, pleno) + vega (ímpetu)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "precisamente"}, {"iast": "nāśāya", "sa": "नाशाय", "gram": "dat. sg. m.", "es": "para perecer"}, {"iast": "viśanti", "sa": "विशन्ति", "gram": "3 pl. pres. act.", "es": "entran"}, {"iast": "lokāḥ", "sa": "लोकाः", "gram": "nom. pl. m.", "es": "los mundos, las gentes", "analisis": "loka (mundo; también la gente)"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tus"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "también"}, {"iast": "vaktrāṇi", "sa": "वक्त्राणि", "gram": "ac. pl. n.", "es": "en las bocas"}, {"iast": "samṛddha-vegāḥ", "sa": "समृद्धवेगाः", "gram": "nom. pl. m.", "es": "con ímpetu creciente"}], "nota": "<p><em>Loka</em>, «mundo», vale también «la gente», y aquí puede entenderse de los seres, como <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, o de los guerreros que llenan los mundos, como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>. <em>Pataṅga</em> es cualquier insecto volador; la imagen de la polilla atraída por la llama es proverbial en la literatura sánscrita.</p>", "interp": [{"titulo": "Dos imágenes de la muerte", "html": "<p>Los dos símiles seguidos no dicen exactamente lo mismo. Los ríos corren al océano porque ése es su curso: no lo eligen (<a class=\"vref\" href=\"capitulo-11.html#v28\" data-v=\"11.28\">11.28</a>). Las polillas se lanzan al fuego atraídas por él, con un ímpetu que va en aumento: van a perecer, pero van hacia lo que las fascina. La visión junta así la necesidad y el deseo como dos caras de un mismo fin. La distinción es de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: los ríos entran sin quererlo, las polillas a sabiendas (<em>buddhi-pūrvakam</em>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 30, "hablante": "arjuna", "sa": ["लेलिह्यसे ग्रसमानः समन्ताल्लोकान्समग्रान्वदनैर्ज्वलद्भिः ।", "तेजोभिरापूर्य जगत्समग्रं भासस्तवोग्राः प्रतपन्ति विष्णो ॥३०॥"], "iast": ["lelihyase grasamānaḥ samantāl lokān samagrān vadanair jvaladbhiḥ", "tejobhir āpūrya jagat samagraṃ bhāsas tavogrāḥ pratapanti viṣṇo"], "rojas": [], "t": "<span class=\"vt-parte\">Lames por todas partes, devorándolos, los mundos enteros con tus bocas llameantes; tus rayos terribles llenan de resplandor el universo entero y lo abrasan, oh <a class=\"t\" href=\"glosario.html#visnu\" data-t=\"visnu\">Viṣṇu</a>.</span>", "palabras": [{"iast": "lelihyase", "sa": "लेलिह्यसे", "gram": "2 sg. pres. intens. med.", "es": "lames una y otra vez", "analisis": "intensivo de √lih (lamer)"}, {"iast": "grasamānaḥ", "sa": "ग्रसमानः", "gram": "nom. sg. m. part. pres. med.", "es": "devorando", "analisis": "√gras (tragar, devorar)"}, {"iast": "samantāt", "sa": "समन्तात्", "gram": "ind.", "es": "por todas partes"}, {"iast": "lokān", "sa": "लोकान्", "gram": "ac. pl. m.", "es": "los mundos"}, {"iast": "samagrān", "sa": "समग्रान्", "gram": "ac. pl. m.", "es": "enteros"}, {"iast": "vadanaiḥ", "sa": "वदनैः", "gram": "instr. pl. n.", "es": "con las bocas", "analisis": "vadana (boca, rostro)"}, {"iast": "jvaladbhiḥ", "sa": "ज्वलद्भिः", "gram": "instr. pl. n. part. pres.", "es": "llameantes", "analisis": "√jval (llamear)"}, {"iast": "tejobhiḥ", "sa": "तेजोभिः", "gram": "instr. pl. n.", "es": "con resplandores", "ref": "tejas"}, {"iast": "āpūrya", "sa": "आपूर्य", "gram": "abs.", "es": "llenando", "analisis": "ā-√pṝ (llenar)"}, {"iast": "jagat", "sa": "जगत्", "gram": "ac. sg. n.", "es": "el universo"}, {"iast": "samagram", "sa": "समग्रम्", "gram": "ac. sg. n.", "es": "entero"}, {"iast": "bhāsaḥ", "sa": "भासः", "gram": "nom. pl. f.", "es": "los rayos, las luces", "analisis": "bhās (luz, resplandor)"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tus"}, {"iast": "ugrāḥ", "sa": "उग्राः", "gram": "nom. pl. f.", "es": "terribles, violentos"}, {"iast": "pratapanti", "sa": "प्रतपन्ति", "gram": "3 pl. pres. act.", "es": "abrasan", "analisis": "pra-√tap (quemar, abrasar)"}, {"iast": "viṣṇo", "sa": "विष्णो", "gram": "voc. sg. m.", "es": "oh Viṣṇu", "ref": "visnu"}], "nota": "<p><em>Lelihyase</em> es el intensivo de √lih, «lamer»: «lames y vuelves a lamer», como el fuego que avanza. Arjuna llama a Kṛṣṇa «Viṣṇu», como ya en <a class=\"vref\" href=\"capitulo-11.html#v24\" data-v=\"11.24\">11.24</a>: la forma que ve es la del dios que todo lo penetra, no la del amigo y auriga.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 31, "hablante": "arjuna", "sa": ["आख्याहि मे को भवानुग्ररूपो नमोऽस्तु ते देववर प्रसीद ।", "विज्ञातुमिच्छामि भवन्तमाद्यं न हि प्रजानामि तव प्रवृत्तिम् ॥३१॥"], "iast": ["ākhyāhi me ko bhavān ugra-rūpo namo 'stu te deva-vara prasīda", "vijñātum icchāmi bhavantam ādyaṃ na hi prajānāmi tava pravṛttim"], "rojas": [], "t": "<span class=\"vt-parte\">Dime quién eres tú, de forma tan terrible. Te saludo, oh el mejor de los dioses: ten piedad. Quiero conocerte a ti, que eres el principio, porque no comprendo lo que haces.</span>", "palabras": [{"iast": "ākhyāhi", "sa": "आख्याहि", "gram": "2 sg. imper. act.", "es": "dime", "analisis": "ā-√khyā (decir, declarar)"}, {"iast": "me", "sa": "मे", "gram": "dat. sg. pron.", "es": "a mí"}, {"iast": "kaḥ", "sa": "कः", "gram": "nom. sg. m. pron. interr.", "es": "quién"}, {"iast": "bhavān", "sa": "भवान्", "gram": "nom. sg. m.", "es": "tú (respetuoso)", "analisis": "bhavat, pronombre de cortesía con verbo en tercera persona"}, {"iast": "ugra-rūpaḥ", "sa": "उग्ररूपः", "gram": "nom. sg. m.", "es": "de forma terrible", "analisis": "ugra (terrible) + rūpa (forma)"}, {"iast": "namaḥ", "sa": "नमः", "gram": "nom. sg. n.", "es": "saludo, reverencia"}, {"iast": "astu", "sa": "अस्तु", "gram": "3 sg. imper.", "es": "sea", "analisis": "√as (ser)"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "deva-vara", "sa": "देववर", "gram": "voc. sg. m.", "es": "oh el mejor de los dioses", "analisis": "deva (dios) + vara (el mejor)"}, {"iast": "prasīda", "sa": "प्रसीद", "gram": "2 sg. imper. act.", "es": "ten piedad, sé propicio", "analisis": "pra-√sad (calmarse, ser favorable)"}, {"iast": "vijñātum", "sa": "विज्ञातुम्", "gram": "inf.", "es": "conocer", "analisis": "vi-√jñā (conocer, discernir)"}, {"iast": "icchāmi", "sa": "इच्छामि", "gram": "1 sg. pres. act.", "es": "quiero", "analisis": "√iṣ (desear)"}, {"iast": "bhavantam", "sa": "भवन्तम्", "gram": "ac. sg. m.", "es": "a ti"}, {"iast": "ādyam", "sa": "आद्यम्", "gram": "ac. sg. m.", "es": "el primero, el que está al principio", "analisis": "ādi (comienzo)"}, {"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "hi", "sa": "हि", "gram": "part.", "es": "pues"}, {"iast": "prajānāmi", "sa": "प्रजानामि", "gram": "1 sg. pres. act.", "es": "comprendo", "analisis": "pra-√jñā (conocer)"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "pravṛttim", "sa": "प्रवृत्तिम्", "gram": "ac. sg. f.", "es": "obrar, actividad, propósito", "analisis": "pra-√vṛt (ponerse en marcha)"}], "nota": "<p><em>Bhavān</em> es el pronombre de cortesía, que Arjuna vuelve a usar ante lo que no reconoce. <em>Pravṛtti</em> es la actividad, lo que alguien está haciendo o se propone hacer: Arjuna ve la destrucción, pero no entiende su porqué. <em>Prasīda</em>, «sé propicio», «cálmate», «ten piedad», es la súplica que ya hizo en <a class=\"vref\" href=\"capitulo-11.html#v25\" data-v=\"11.25\">11.25</a> y que repetirá en <a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>.</p>", "interp": [{"titulo": "«¿Quién eres?»", "html": "<p>Arjuna había pedido ver la forma soberana de Kṛṣṇa (<a class=\"vref\" href=\"capitulo-11.html#v3\" data-v=\"11.3\">11.3</a>–<a class=\"vref\" href=\"capitulo-11.html#v4\" data-v=\"11.4\">11.4</a>), y ahora que la ve no la reconoce. La pregunta no es retórica: lo que tiene delante no se parece al amigo que conduce su carro, ni siquiera a las manifestaciones del capítulo 10. <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> lo entiende de otro modo: Arjuna sabe con quién habla, pues acaba de llamarlo «Viṣṇu», y pregunta por otro de sus atributos, como quien, conociendo el nombre de alguien, le pregunta «¿quién eres?» para saber de qué clase es. Kṛṣṇa responde en el verso siguiente con su nombre más desnudo: «soy el tiempo».</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 32, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "कालोऽस्मि लोकक्षयकृत्प्रवृद्धो लोकान्समाहर्तुमिह प्रवृत्तः ।", "ऋतेऽपि त्वां न भविष्यन्ति सर्वे येऽवस्थिताः प्रत्यनीकेषु योधाः ॥३२॥"], "iast": ["śrī-bhagavān uvāca", "kālo 'smi loka-kṣaya-kṛt pravṛddho lokān samāhartum iha pravṛttaḥ", "ṛte 'pi tvāṃ na bhaviṣyanti sarve ye 'vasthitāḥ pratyanīkeṣu yodhāḥ"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Soy el <a class=\"t\" href=\"glosario.html#kala\" data-t=\"kala\">tiempo</a>, que, crecido, destruye los mundos, y me he puesto aquí a aniquilarlos. Aun sin ti, no quedará ninguno de los guerreros alineados en los ejércitos enemigos.</span>", "palabras": [{"iast": "kālaḥ", "sa": "कालः", "gram": "nom. sg. m.", "es": "el tiempo", "ref": "kala"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "soy"}, {"iast": "loka-kṣaya-kṛt", "sa": "लोकक्षयकृत्", "gram": "nom. sg. m.", "es": "que destruye los mundos", "analisis": "loka (mundo) + kṣaya (destrucción) + kṛt (que hace)"}, {"iast": "pravṛddhaḥ", "sa": "प्रवृद्धः", "gram": "nom. sg. m. part. pas.", "es": "crecido, en su plenitud", "analisis": "pra-√vṛdh (crecer)"}, {"iast": "lokān", "sa": "लोकान्", "gram": "ac. pl. m.", "es": "los mundos"}, {"iast": "samāhartum", "sa": "समाहर्तुम्", "gram": "inf.", "es": "para recogerlos, aniquilarlos", "analisis": "sam-ā-√hṛ (recoger, retirar; destruir)"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí"}, {"iast": "pravṛttaḥ", "sa": "प्रवृत्तः", "gram": "nom. sg. m. part. pas.", "es": "puesto a la obra, ocupado", "analisis": "pra-√vṛt (ponerse en marcha)"}, {"iast": "ṛte", "sa": "ऋते", "gram": "ind.", "es": "sin, excepto"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "aun"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "ti"}, {"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "bhaviṣyanti", "sa": "भविष्यन्ति", "gram": "3 pl. fut. act.", "es": "existirán, quedarán", "analisis": "√bhū (ser)"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m.", "es": "todos"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron. rel.", "es": "los que"}, {"iast": "avasthitāḥ", "sa": "अवस्थिताः", "gram": "nom. pl. m. part. pas.", "es": "alineados, apostados", "analisis": "ava-√sthā (situarse)"}, {"iast": "pratyanīkeṣu", "sa": "प्रत्यनीकेषु", "gram": "loc. pl. n.", "es": "en los ejércitos enemigos", "analisis": "prati (contra) + anīka (ejército, frente)"}, {"iast": "yodhāḥ", "sa": "योधाः", "gram": "nom. pl. m.", "es": "los guerreros"}], "nota": "<p><em>Pravṛddha</em>, «crecido», «llegado a su plenitud»: el tiempo en el momento en que madura su obra. <em>Samāhartum</em>, «para recoger», «para retirar»: es de la misma raíz que el <em>saṃharate</em> con que el yogui retira los sentidos de sus objetos (<a class=\"vref\" href=\"capitulo-02.html#v58\" data-v=\"2.58\">2.58</a>); aquí es el tiempo el que retira los mundos. <em>Ṛte &#x27;pi tvām</em>, «aun sin ti»: la muerte de los guerreros no depende de Arjuna (así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: «aun sin tu esfuerzo»). <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> y Prabhupāda entienden en cambio «salvo tú»: no quedará nadie en ninguno de los dos ejércitos, excepto Arjuna y sus hermanos. El texto de la Gita Press lee <em>tvām</em>; la edición crítica, <em>tvā</em>, sin cambio de sentido. <em>Tvā</em> es también la lectura que comentan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que la glosan <em>tvām</em>; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> leen <em>tvām</em>.</p>", "interp": [{"titulo": "El tiempo en tres pasos", "html": "<p>Kṛṣṇa ya se había presentado como el tiempo «entre los que cuentan» (<a class=\"vref\" href=\"capitulo-10.html#v30\" data-v=\"10.30\">10.30</a>) y como «el tiempo imperecedero» (<a class=\"vref\" href=\"capitulo-10.html#v33\" data-v=\"10.33\">10.33</a>). Aquí el tiempo deja de ser una medida o una cualidad y se muestra como lo que hace: destruir. Es la respuesta a la pregunta de Arjuna (<a class=\"vref\" href=\"capitulo-11.html#v31\" data-v=\"11.31\">11.31</a>), «¿quién eres?, no comprendo lo que haces»: lo que hace es lo que el tiempo hace con todo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Oppenheimer y la primera bomba atómica", "html": "<p>J. Robert Oppenheimer, director científico del proyecto que construyó la bomba atómica, recordó en una entrevista para la televisión estadounidense en 1965 que, ante la primera explosión nuclear —la prueba Trinity, el 16 de julio de 1945—, le vino a la mente este verso: «Now I am become Death, the destroyer of worlds». Había leído la Gītā en sánscrito, que estudió en Berkeley con Arthur W. Ryder, cuya traducción dice «Death am I»; la frase que citó es su propia versión, que sigue a Ryder al traducir <em>kāla</em> por «muerte». La cita ha hecho de este verso uno de los más conocidos de la Gītā fuera de la India, y de paso ha difundido en inglés la lectura de <em>kāla</em> como «muerte», aunque la mayoría de los traductores ingleses prefieren «Time» (véase la alternativa).</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Soy la muerte, que, crecida, destruye los mundos, y me he puesto aquí a aniquilarlos. Aun sin ti, no quedará ninguno de los guerreros alineados en los ejércitos enemigos.", "nota": "<p><em>Kāla</em> es el tiempo, pero también el fin al que todo llega, y por eso la muerte: Yama, el dios de los muertos, se llama asimismo Kāla (véase la ficha <a class=\"t\" href=\"glosario.html#kala\" data-t=\"kala\">kāla</a>). La traducción principal conserva «el tiempo», que enlaza con <a class=\"vref\" href=\"capitulo-10.html#v30\" data-v=\"10.30\">10.30</a> y <a class=\"vref\" href=\"capitulo-10.html#v33\" data-v=\"10.33\">10.33</a>, donde Kṛṣṇa ya se había dicho «el tiempo»; la alternativa toma el sentido de muerte, el que eligieron algunas traducciones inglesas («Death»). Ningún comentarista clásico glosa aquí <em>kāla</em> como muerte: para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> es «el que cuenta» el fin de la vida de los reyes; para <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el Señor supremo como destructor de todo; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> no lo glosan; <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> lo toma como un nombre de Viṣṇu, de √<em>kal</em> «atar, cortar, conocer», y Prabhupāda traduce «Time».</p>"}, {"html": "Soy el tiempo, que, crecido, destruye los mundos, y me he puesto aquí a aniquilarlos. Salvo tú, no quedará ninguno de los guerreros alineados en los dos ejércitos.", "nota": "<p><em>Ṛte</em> rige el acusativo y significa «sin» o «excepto». La traducción principal lo entiende «aun sin ti», es decir, aunque tú no luches, como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>; <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, Jayatīrtha y Prabhupāda leen «salvo tú» (y tus hermanos), y aplican la frase a los guerreros de los dos ejércitos.</p>"}], "ens": "solo-el-instrumento"}, {"n": 33, "hablante": "krsna", "sa": ["तस्मात्त्वमुत्तिष्ठ यशो लभस्व जित्वा शत्रून्भुङ्क्ष्व राज्यं समृद्धम् ।", "मयैवैते निहताः पूर्वमेव निमित्तमात्रं भव सव्यसाचिन् ॥३३॥"], "iast": ["tasmāt tvam uttiṣṭha yaśo labhasva jitvā śatrūn bhuṅkṣva rājyaṃ samṛddham", "mayaivaite nihatāḥ pūrvam eva nimitta-mātraṃ bhava savya-sācin"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Por eso, levántate y alcanza la gloria; vence a tus enemigos y goza de un reino próspero. Yo mismo los he matado ya de antemano: sé tú sólo el <a class=\"t\" href=\"glosario.html#nimitta\" data-t=\"nimitta\">instrumento</a>, oh <a class=\"t\" href=\"glosario.html#savyasacin\" data-t=\"savyasacin\">Savyasācin</a>.</span>", "palabras": [{"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. pron.", "es": "por eso"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "uttiṣṭha", "sa": "उत्तिष्ठ", "gram": "2 sg. imper. act.", "es": "levántate", "analisis": "ud-√sthā (levantarse)"}, {"iast": "yaśaḥ", "sa": "यशः", "gram": "ac. sg. n.", "es": "la gloria, la fama"}, {"iast": "labhasva", "sa": "लभस्व", "gram": "2 sg. imper. med.", "es": "alcanza, obtén", "analisis": "√labh (obtener)"}, {"iast": "jitvā", "sa": "जित्वा", "gram": "abs.", "es": "venciendo", "analisis": "√ji (vencer)"}, {"iast": "śatrūn", "sa": "शत्रून्", "gram": "ac. pl. m.", "es": "a los enemigos"}, {"iast": "bhuṅkṣva", "sa": "भुङ्क्ष्व", "gram": "2 sg. imper. med.", "es": "goza", "analisis": "√bhuj (gozar, disfrutar)"}, {"iast": "rājyam", "sa": "राज्यम्", "gram": "ac. sg. n.", "es": "un reino"}, {"iast": "samṛddham", "sa": "समृद्धम्", "gram": "ac. sg. n.", "es": "próspero"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "precisamente, mismo"}, {"iast": "ete", "sa": "एते", "gram": "nom. pl. m. pron.", "es": "éstos"}, {"iast": "nihatāḥ", "sa": "निहताः", "gram": "nom. pl. m. part. pas.", "es": "muertos", "analisis": "ni-√han (matar)"}, {"iast": "pūrvam", "sa": "पूर्वम्", "gram": "ind.", "es": "antes, de antemano"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "ya"}, {"iast": "nimitta-mātram", "sa": "निमित्तमात्रम्", "gram": "nom. sg. n.", "es": "sólo el instrumento", "ref": "nimitta", "analisis": "nimitta (causa instrumental, ocasión) + mātra (sólo, nada más que)"}, {"iast": "bhava", "sa": "भव", "gram": "2 sg. imper. act.", "es": "sé", "analisis": "√bhū (ser)"}, {"iast": "savya-sācin", "sa": "सव्यसाचिन्", "gram": "voc. sg. m.", "es": "oh Savyasācin", "ref": "savyasacin", "analisis": "savya (izquierdo) + sācin (que dispara): el que tira también con la izquierda"}], "nota": "<p><em>Yaśas</em>, «gloria, fama»: es lo mismo que Kṛṣṇa le recordaba en el capítulo 2, cuando le advertía de la deshonra que caería sobre él si se retiraba (<a class=\"vref\" href=\"capitulo-02.html#v33\" data-v=\"2.33\">2.33</a>–<a class=\"vref\" href=\"capitulo-02.html#v34\" data-v=\"2.34\">2.34</a>). <em>Pūrvam eva</em>, «ya antes»: su muerte está decidida antes de la batalla. <em>Savya-sācin</em>, «el que tira también con la izquierda», es un epíteto de Arjuna, arquero ambidiestro (véase la ficha <a class=\"t\" href=\"glosario.html#savyasacin\" data-t=\"savyasacin\">Savyasācin</a>).</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Por eso, levántate y alcanza la gloria; vence a tus enemigos y goza de un reino próspero. Yo mismo los he matado ya de antemano: sé tú sólo la ocasión, oh Savyasācin.", "nota": "<p><em>Nimitta</em> es la causa instrumental o eficiente, y también la ocasión, el motivo, la señal (en <a class=\"vref\" href=\"capitulo-01.html#v31\" data-v=\"1.31\">1.31</a>, «presagios»). La traducción principal lo entiende como instrumento, como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, que glosa «sé como el arma», y Prabhupāda: Arjuna es la mano por la que se cumple lo que Kṛṣṇa ya ha hecho. La alternativa toma, como <a class=\"t\" href=\"glosario.html#aurobindo\" data-t=\"aurobindo\">Aurobindo</a> («become the occasion only»), el sentido de ocasión, como <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: Arjuna sólo ha de ser aquel a quien todos atribuirán la victoria («Arjuna los venció»), el punto en que se hace visible lo que Kṛṣṇa ha hecho. Las dos lecturas coinciden en lo esencial: el resultado no depende de él.</p>"}], "ens": "solo-el-instrumento"}, {"n": 34, "hablante": "krsna", "sa": ["द्रोणं च भीष्मं च जयद्रथं च कर्णं तथान्यानपि योधवीरान् ।", "मया हतांस्त्वं जहि मा व्यथिष्ठा युध्यस्व जेतासि रणे सपत्नान् ॥३४॥"], "iast": ["droṇaṃ ca bhīṣmaṃ ca jayadrathaṃ ca karṇaṃ tathānyān api yodha-vīrān", "mayā hatāṃs tvaṃ jahi mā vyathiṣṭhā yudhyasva jetāsi raṇe sapatnān"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">A <a class=\"t\" href=\"glosario.html#drona\" data-t=\"drona\">Droṇa</a>, a <a class=\"t\" href=\"glosario.html#bhisma\" data-t=\"bhisma\">Bhīṣma</a>, a <a class=\"t\" href=\"glosario.html#jayadratha\" data-t=\"jayadratha\">Jayadratha</a>, a <a class=\"t\" href=\"glosario.html#karna\" data-t=\"karna\">Karṇa</a> y también a los demás guerreros héroes, ya muertos por mí, mátalos tú; no te angusties. Lucha: vencerás en la batalla a tus rivales.</span>", "palabras": [{"iast": "droṇam", "sa": "द्रोणम्", "gram": "ac. sg. m.", "es": "a Droṇa", "ref": "drona"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "bhīṣmam", "sa": "भीष्मम्", "gram": "ac. sg. m.", "es": "a Bhīṣma", "ref": "bhisma"}, {"iast": "jayadratham", "sa": "जयद्रथम्", "gram": "ac. sg. m.", "es": "a Jayadratha", "ref": "jayadratha"}, {"iast": "karṇam", "sa": "कर्णम्", "gram": "ac. sg. m.", "es": "a Karṇa", "ref": "karna"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "también"}, {"iast": "anyān", "sa": "अन्यान्", "gram": "ac. pl. m.", "es": "a los demás"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "también"}, {"iast": "yodha-vīrān", "sa": "योधवीरान्", "gram": "ac. pl. m.", "es": "guerreros héroes", "analisis": "yodha (guerrero) + vīra (héroe)"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "hatān", "sa": "हतान्", "gram": "ac. pl. m. part. pas.", "es": "muertos", "analisis": "√han (matar)"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "jahi", "sa": "जहि", "gram": "2 sg. imper. act.", "es": "mata", "analisis": "√han (matar)"}, {"iast": "mā", "sa": "मा", "gram": "part. prohib.", "es": "no"}, {"iast": "vyathiṣṭhāḥ", "sa": "व्यथिष्ठाः", "gram": "2 sg. aor. med.", "es": "te angusties", "analisis": "√vyath (temblar, angustiarse); con mā, prohibición"}, {"iast": "yudhyasva", "sa": "युध्यस्व", "gram": "2 sg. imper. med.", "es": "lucha", "analisis": "√yudh (luchar)"}, {"iast": "jetāsi", "sa": "जेतासि", "gram": "2 sg. fut. perifr.", "es": "vencerás", "analisis": "jetṛ (vencedor) + asi (eres)"}, {"iast": "raṇe", "sa": "रणे", "gram": "loc. sg. m.", "es": "en la batalla"}, {"iast": "sapatnān", "sa": "सपत्नान्", "gram": "ac. pl. m.", "es": "a los rivales", "analisis": "sapatna (rival, enemigo)"}], "nota": "<p>Los cuatro nombrados son los guerreros que Arjuna tenía más razones para temer, según <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, o para no querer matar, según <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: su maestro, su abuelo, el cuñado de Duryodhana y su gran rival. <em>Mā vyathiṣṭhāḥ</em>, «no te angusties»: es la angustia que lo paralizaba al principio (la palabra, <em>vyathā</em>, volverá en <a class=\"vref\" href=\"capitulo-11.html#v49\" data-v=\"11.49\">11.49</a>), y recuerda el «combate sin angustia» de <a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>. <em>Jetāsi</em>, futuro perifrástico: «serás el vencedor», una promesa más que una exhortación.</p>", "interp": [{"titulo": "Por qué estos cuatro", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica, y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo repite casi a la letra, por qué Kṛṣṇa nombra precisamente a estos guerreros: eran aquellos de quienes Arjuna podía dudar que fuera posible vencerlos. <a class=\"t\" href=\"glosario.html#drona\" data-t=\"drona\">Droṇa</a> era su maestro en el arte del arco y poseía armas divinas; <a class=\"t\" href=\"glosario.html#bhisma\" data-t=\"bhisma\">Bhīṣma</a> sólo podía morir cuando él mismo lo quisiera; el padre de <a class=\"t\" href=\"glosario.html#jayadratha\" data-t=\"jayadratha\">Jayadratha</a> había obtenido con su ascesis que muriera quien hiciera caer al suelo la cabeza de su hijo; y <a class=\"t\" href=\"glosario.html#karna\" data-t=\"karna\">Karṇa</a> tenía el arma infalible que le había dado Indra. Al llamarlos «ya muertos por mí», Kṛṣṇa quita a Arjuna el miedo de no poder vencerlos. <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> da las mismas razones para Jayadratha y Karṇa; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, otra: Kṛṣṇa los ha destinado a morir por sus faltas, y Arjuna no ha de angustiarse por matar a maestros y parientes.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "ens": "solo-el-instrumento"}, {"n": 35, "hablante": "sanjaya", "sa": ["सञ्जय उवाच ।", "एतच्छ्रुत्वा वचनं केशवस्य कृताञ्जलिर्वेपमानः किरीटी ।", "नमस्कृत्वा भूय एवाह कृष्णं सगद्गदं भीतभीतः प्रणम्य ॥३५॥"], "iast": ["sañjaya uvāca", "etac chrutvā vacanaṃ keśavasya kṛtāñjalir vepamānaḥ kirīṭī", "namaskṛtvā bhūya evāha kṛṣṇaṃ sa-gadgadaṃ bhīta-bhītaḥ praṇamya"], "rojas": [], "t": "<span class=\"vt-parte\">Al oír estas palabras de <a class=\"t\" href=\"glosario.html#kesava\" data-t=\"kesava\">Keśava</a>, <a class=\"t\" href=\"glosario.html#kiritin\" data-t=\"kiritin\">el de la diadema</a>, temblando y con las manos juntas, le rindió homenaje y, postrado, sobrecogido de miedo, habló de nuevo a <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Kṛṣṇa</a> con la voz entrecortada.</span>", "palabras": [{"iast": "sañjayaḥ", "sa": "सञ्जयः", "gram": "nom. sg. m.", "es": "Sañjaya", "ref": "sanjaya"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "etat", "sa": "एतत्", "gram": "acc. sg. n.", "es": "esto, estas"}, {"iast": "śrutvā", "sa": "श्रुत्वा", "gram": "abs.", "es": "habiendo oído", "analisis": "√śru (oír)"}, {"iast": "vacanam", "sa": "वचनम्", "gram": "acc. sg. n.", "es": "las palabras", "analisis": "de √vac (hablar)"}, {"iast": "keśavasya", "sa": "केशवस्य", "gram": "gen. sg. m.", "es": "de Keśava", "ref": "kesava"}, {"iast": "kṛta-añjaliḥ", "sa": "कृताञ्जलिः", "gram": "nom. sg. m. comp.", "es": "con las manos juntas", "analisis": "kṛta (hecho) + añjali (el gesto de juntar las palmas en señal de reverencia)"}, {"iast": "vepamānaḥ", "sa": "वेपमानः", "gram": "nom. sg. m. ppr. med.", "es": "temblando", "analisis": "√vip (temblar)"}, {"iast": "kirīṭī", "sa": "किरीटी", "gram": "nom. sg. m.", "es": "el de la diadema", "ref": "kiritin", "analisis": "kirīṭa (diadema) + -in (que tiene)"}, {"iast": "namaskṛtvā", "sa": "नमस्कृत्वा", "gram": "abs.", "es": "tras rendirle homenaje", "analisis": "namas (homenaje) + √kṛ (hacer)"}, {"iast": "bhūyaḥ", "sa": "भूयः", "gram": "adv.", "es": "de nuevo"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "(enfática)"}, {"iast": "āha", "sa": "आह", "gram": "3 sg. pf.", "es": "dijo", "analisis": "√ah (decir)"}, {"iast": "kṛṣṇam", "sa": "कृष्णम्", "gram": "acc. sg. m.", "es": "a Kṛṣṇa", "ref": "krsna"}, {"iast": "sa-gadgadam", "sa": "सगद्गदम्", "gram": "adv. comp.", "es": "con la voz entrecortada", "analisis": "sa (con) + gadgada (balbuceo, voz quebrada por la emoción)"}, {"iast": "bhīta-bhītaḥ", "sa": "भीतभीतः", "gram": "nom. sg. m. comp.", "es": "sobrecogido de miedo", "analisis": "bhīta (atemorizado), repetido para intensificar"}, {"iast": "praṇamya", "sa": "प्रणम्य", "gram": "abs.", "es": "postrándose", "analisis": "pra-√nam (inclinarse)"}], "nota": "<p>Es la única intervención de <a class=\"t\" href=\"glosario.html#sanjaya\" data-t=\"sanjaya\">Sañjaya</a> entre la visión y la plegaria de Arjuna: el narrador describe el gesto antes de dar las palabras. <a class=\"t\" href=\"glosario.html#kiritin\" data-t=\"kiritin\"><em>Kirīṭin</em></a>, «el de la diadema», es aquí Arjuna; la misma palabra describe a Kṛṣṇa en la visión (<a class=\"vref\" href=\"capitulo-11.html#v17\" data-v=\"11.17\">11.17</a>) y en la petición final (<a class=\"vref\" href=\"capitulo-11.html#v46\" data-v=\"11.46\">11.46</a>). <em>Añjali</em> es el gesto de juntar las palmas a la altura del pecho o de la frente, que se hace todavía hoy al saludar o al venerar. <em>Bhīta-bhītaḥ</em>, «atemorizado, atemorizado»: la repetición intensifica, como en «muy, muy asustado». <em>Namaskṛtvā</em> y <em>praṇamya</em> dicen dos veces la inclinación: una al empezar a hablar y otra, más profunda, la postración.</p>", "interp": [{"titulo": "La plegaria después de la visión", "html": "<p>Los versos que siguen, hasta <a class=\"vref\" href=\"capitulo-11.html#v46\" data-v=\"11.46\">11.46</a>, son la segunda gran plegaria de Arjuna en el capítulo, después de la de <a class=\"vref\" href=\"capitulo-11.html#v15\" data-v=\"11.15\">11.15</a>–<a class=\"vref\" href=\"capitulo-11.html#v31\" data-v=\"11.31\">11.31</a>. Aquélla describía lo que veía y preguntaba quién era el que lo veía; ésta, tras la respuesta de Kṛṣṇa («soy el tiempo», <a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a>), alaba, pide perdón y pide volver a la forma conocida. Las dos están en <em>triṣṭubh</em>, el metro de los himnos, y la de ahora conserva su tono: letanía de nombres, repetición del homenaje, súplica final.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 36, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "स्थाने हृषीकेश तव प्रकीर्त्या जगत्प्रहृष्यत्यनुरज्यते च ।", "रक्षांसि भीतानि दिशो द्रवन्ति सर्वे नमस्यन्ति च सिद्धसङ्घाः ॥३६॥"], "iast": ["arjuna uvāca", "sthāne hṛṣīkeśa tava prakīrtyā jagat prahṛṣyaty anurajyate ca", "rakṣāṃsi bhītāni diśo dravanti sarve namasyanti ca siddha-saṅghāḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Con razón, oh <a class=\"t\" href=\"glosario.html#hrsikesa\" data-t=\"hrsikesa\">Hṛṣīkeśa</a>, el mundo se alegra al celebrarte y se llena de amor; los <a class=\"t\" href=\"glosario.html#raksasa\" data-t=\"raksasa\">rākṣasas</a>, aterrados, huyen en todas direcciones, y todas las huestes de los <a class=\"t\" href=\"glosario.html#siddha\" data-t=\"siddha\">perfectos</a> se inclinan ante ti.</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "sthāne", "sa": "स्थाने", "gram": "adv. (loc. sg. n.)", "es": "con razón, como es justo", "analisis": "loc. de sthāna (lugar): «en su lugar», «como corresponde»"}, {"iast": "hṛṣīkeśa", "sa": "हृषीकेश", "gram": "voc. sg. m.", "es": "oh Hṛṣīkeśa", "ref": "hrsikesa"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "prakīrtyā", "sa": "प्रकीर्त्या", "gram": "instr. sg. f.", "es": "con la alabanza, al celebrarte", "analisis": "pra-√kīrt (proclamar, alabar)"}, {"iast": "jagat", "sa": "जगत्", "gram": "nom. sg. n.", "es": "el mundo"}, {"iast": "prahṛṣyati", "sa": "प्रहृष्यति", "gram": "3 sg. pres.", "es": "se alegra", "analisis": "pra-√hṛṣ (regocijarse)"}, {"iast": "anurajyate", "sa": "अनुरज्यते", "gram": "3 sg. pres. med.", "es": "se llena de afecto, se deleita", "analisis": "anu-√rañj (teñirse de, enamorarse)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "rakṣāṃsi", "sa": "रक्षांसि", "gram": "nom. pl. n.", "es": "los rākṣasas", "ref": "raksasa", "analisis": "rakṣas"}, {"iast": "bhītāni", "sa": "भीतानि", "gram": "nom. pl. n.", "es": "aterrados", "analisis": "√bhī (temer)"}, {"iast": "diśaḥ", "sa": "दिशः", "gram": "acc. pl. f.", "es": "en todas direcciones", "analisis": "diś (punto cardinal)"}, {"iast": "dravanti", "sa": "द्रवन्ति", "gram": "3 pl. pres.", "es": "huyen", "analisis": "√dru (correr)"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m.", "es": "todas"}, {"iast": "namasyanti", "sa": "नमस्यन्ति", "gram": "3 pl. pres.", "es": "se inclinan, rinden homenaje", "analisis": "de namas (homenaje)"}, {"iast": "siddha-saṅghāḥ", "sa": "सिद्धसङ्घाः", "gram": "nom. pl. m. comp.", "es": "las huestes de los perfectos", "ref": "siddha", "analisis": "siddha (perfecto) + saṅgha (multitud)"}], "nota": "<p><em>Sthāne</em>, literalmente «en su lugar», es «con razón», «como es debido»: Arjuna empieza dando por justa la reacción de los seres que ha visto en la forma universal. <em>Prakīrti</em> es la alabanza, el canto de la gloria de alguien; <em>anurajyate</em>, de anu-√rañj, «teñirse de», es quedar prendado, llenarse de afecto. Los rākṣasas huyen y los perfectos se inclinan: es el reverso de <a class=\"vref\" href=\"capitulo-11.html#v21\" data-v=\"11.21\">11.21</a>–<a class=\"vref\" href=\"capitulo-11.html#v22\" data-v=\"11.22\">11.22</a>, donde las huestes de los dioses y los sabios lo contemplaban asombradas.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 37, "hablante": "arjuna", "sa": ["कस्माच्च ते न नमेरन्महात्मन् गरीयसे ब्रह्मणोऽप्यादिकर्त्रे ।", "अनन्त देवेश जगन्निवास त्वमक्षरं सदसत्तत्परं यत् ॥३७॥"], "iast": ["kasmāc ca te na nameran mahātman garīyase brahmaṇo 'py ādi-kartre", "ananta deveśa jagan-nivāsa tvam akṣaraṃ sad asat tat-paraṃ yat"], "rojas": [], "t": "<span class=\"vt-parte\">¿Y cómo no habrían de inclinarse ante ti, oh <a class=\"t\" href=\"glosario.html#mahatman\" data-t=\"mahatman\">Mahātman</a>, tú que eres el creador primero, más grande aún que <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a>? Oh infinito, señor de los dioses, morada del universo: tú eres lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a>, el <a class=\"t\" href=\"glosario.html#sat-asat\" data-t=\"sat-asat\">ser y el no-ser</a>, y lo que está más allá de ellos.</span>", "palabras": [{"iast": "kasmāt", "sa": "कस्मात्", "gram": "abl. sg. pron. interr.", "es": "¿por qué?"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "ante ti"}, {"iast": "na", "sa": "न", "gram": "neg.", "es": "no"}, {"iast": "nameran", "sa": "नमेरन्", "gram": "3 pl. opt. med.", "es": "habrían de inclinarse", "analisis": "√nam (inclinarse)"}, {"iast": "mahātman", "sa": "महात्मन्", "gram": "voc. sg. m.", "es": "oh gran ser", "ref": "mahatman", "analisis": "mahā (grande) + ātman (ser)"}, {"iast": "garīyase", "sa": "गरीयसे", "gram": "dat. sg. m.", "es": "más grande, más venerable", "analisis": "comparativo de guru (pesado, venerable)"}, {"iast": "brahmaṇaḥ", "sa": "ब्रह्मणः", "gram": "abl. sg. m.", "es": "que Brahmā", "ref": "brahma-deva", "analisis": "brahman (m.): el dios creador"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "aun, incluso"}, {"iast": "ādi-kartre", "sa": "आदिकर्त्रे", "gram": "dat. sg. m. comp.", "es": "al creador primero", "analisis": "ādi (primero, principio) + kartṛ (hacedor, de √kṛ)"}, {"iast": "ananta", "sa": "अनन्त", "gram": "voc. sg. m.", "es": "oh infinito", "analisis": "an- (sin) + anta (fin)"}, {"iast": "deva-īśa", "sa": "देवेश", "gram": "voc. sg. m. comp.", "es": "oh señor de los dioses", "analisis": "deva (dios) + īśa (señor)"}, {"iast": "jagan-nivāsa", "sa": "जगन्निवास", "gram": "voc. sg. m. comp.", "es": "oh morada del universo", "analisis": "jagat (mundo) + nivāsa (morada, de ni-√vas)"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "akṣaram", "sa": "अक्षरम्", "gram": "nom. sg. n.", "es": "lo imperecedero", "ref": "aksara"}, {"iast": "sat", "sa": "सत्", "gram": "nom. sg. n.", "es": "el ser, lo que es", "ref": "sat-asat"}, {"iast": "asat", "sa": "असत्", "gram": "nom. sg. n.", "es": "el no-ser, lo que no es", "ref": "sat-asat"}, {"iast": "tat-param", "sa": "तत्परम्", "gram": "nom. sg. n. comp.", "es": "lo que está más allá de ellos", "analisis": "tat (eso) + para (más allá, superior)"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "que, lo que"}], "nota": "<p><em>Ādi-kartre</em>, «al creador primero», concierta con <em>te</em>, «a ti», no con <em>brahmaṇaḥ</em>: el creador primero es Kṛṣṇa, del que nace también <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a>, el creador del mundo; por eso es «más grande aún que Brahmā» (<em>brahmaṇaḥ</em>, aquí masculino, el dios, no el brahman neutro; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo construyen con <em>ādi-kartre</em>, «creador primero aun de Brahmā», y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, con las dos palabras). <a class=\"vref\" href=\"capitulo-10.html#v2\" data-v=\"10.2\">10.2</a> decía lo mismo: él es el principio de los dioses. <em>Deveśa</em> y <em>jagan-nivāsa</em>, «señor de los dioses» y «morada del universo», aparecen, en el mismo orden, también en <a class=\"vref\" href=\"capitulo-11.html#v25\" data-v=\"11.25\">11.25</a> y <a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>. Sobre <em>sat</em> y <em>asat</em>, véase la ficha <a class=\"t\" href=\"glosario.html#sat-asat\" data-t=\"sat-asat\">sat-asat</a>.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "¿Y cómo no habrían de inclinarse ante ti, oh Mahātman, tú que eres el creador primero, más grande aún que Brahmā? Oh infinito, señor de los dioses, morada del universo: tú eres lo imperecedero, lo que está más allá del ser y del no-ser.", "nota": "<p>La última frase, <em>tvam akṣaraṃ sad asat tat-paraṃ yat</em>, admite dos construcciones. La traducción principal enumera tres cosas: lo imperecedero, el ser y el no-ser, y «lo que está más allá de ellos»; así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien son el alma individual, la materia en su estado de efecto y de causa, y el alma liberada. La alternativa toma la relativa <em>tat-paraṃ yat</em> como aposición de <em>akṣaram</em>: lo imperecedero es precisamente lo que está más allá del ser y del no-ser. Es la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, para quien el ser y el no-ser son sólo los adjuntos por los que se nombra lo imperecedero, y la de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que glosan <em>sat</em> y <em>asat</em> como lo manifiesto y lo no manifiesto. La primera es la de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien lo imperecedero es aquí el alma individual, el ser y el no-ser la materia como efecto y como causa, y lo que está más allá, las almas liberadas, y también la de <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>; la segunda, la de Viśvanātha Cakravartī. Las dos son posibles por la sintaxis y apuntan a la misma idea de <a class=\"vref\" href=\"capitulo-13.html#v12\" data-v=\"13.12\">13.12</a>, donde brahman «no se dice ni ser ni no-ser»; con el «ser y no-ser» de <a class=\"vref\" href=\"capitulo-09.html#v19\" data-v=\"9.19\">9.19</a>, Kṛṣṇa ya se había nombrado en los dos lados.</p>"}]}, {"n": 38, "hablante": "arjuna", "sa": ["त्वमादिदेवः पुरुषः पुराणस्त्वमस्य विश्वस्य परं निधानम् ।", "वेत्तासि वेद्यं च परं च धाम त्वया ततं विश्वमनन्तरूप ॥३८॥"], "iast": ["tvam ādi-devaḥ puruṣaḥ purāṇas tvam asya viśvasya paraṃ nidhānam", "vettāsi vedyaṃ ca paraṃ ca dhāma tvayā tataṃ viśvam ananta-rūpa"], "rojas": [], "t": "<span class=\"vt-parte\">Tú eres el dios primero, la <a class=\"t\" href=\"glosario.html#purusa\" data-t=\"purusa\">Persona</a> antigua; tú eres el lugar supremo donde reposa este universo. Eres el que conoce y lo que ha de conocerse, y la morada suprema; por ti está penetrado el universo, oh tú, de forma infinita.</span>", "palabras": [{"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "ādi-devaḥ", "sa": "आदिदेवः", "gram": "nom. sg. m. comp.", "es": "el dios primero", "ref": "deva", "analisis": "ādi (primero) + deva (dios)"}, {"iast": "puruṣaḥ", "sa": "पुरुषः", "gram": "nom. sg. m.", "es": "la Persona", "ref": "purusa"}, {"iast": "purāṇaḥ", "sa": "पुराणः", "gram": "nom. sg. m.", "es": "antigua, primordial", "analisis": "de purā (antes)"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. n. pron.", "es": "de este"}, {"iast": "viśvasya", "sa": "विश्वस्य", "gram": "gen. sg. n.", "es": "del universo"}, {"iast": "param", "sa": "परम्", "gram": "nom. sg. n.", "es": "supremo"}, {"iast": "nidhānam", "sa": "निधानम्", "gram": "nom. sg. n.", "es": "lugar de reposo, depósito", "analisis": "ni-√dhā (depositar)"}, {"iast": "vettā", "sa": "वेत्ता", "gram": "nom. sg. m.", "es": "el que conoce", "analisis": "√vid (saber), nombre de agente"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres.", "es": "eres", "analisis": "√as (ser)"}, {"iast": "vedyam", "sa": "वेद्यम्", "gram": "nom. sg. n. gerundivo", "es": "lo que ha de conocerse", "analisis": "√vid (saber)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "dhāma", "sa": "धाम", "gram": "nom. sg. n.", "es": "la morada", "analisis": "dhāman, de √dhā (poner, asentar)"}, {"iast": "tvayā", "sa": "त्वया", "gram": "instr. sg. pron.", "es": "por ti"}, {"iast": "tatam", "sa": "ततम्", "gram": "nom. sg. n. ppp.", "es": "penetrado, extendido", "analisis": "√tan (extender)"}, {"iast": "viśvam", "sa": "विश्वम्", "gram": "nom. sg. n.", "es": "el universo"}, {"iast": "ananta-rūpa", "sa": "अनन्तरूप", "gram": "voc. sg. m. comp.", "es": "oh tú, de forma infinita", "analisis": "ananta (sin fin) + rūpa (forma)"}], "nota": "<p><em>Nidhāna</em>, de ni-√dhā, «depositar», es el lugar donde algo se guarda; <a class=\"vref\" href=\"capitulo-09.html#v18\" data-v=\"9.18\">9.18</a>, donde Kṛṣṇa se lo aplicaba a sí mismo, lo dejaba en «el tesoro», y aquí, unido a «este universo», se entiende mejor como el lugar donde el universo descansa o se recoge: <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo glosan como el lugar donde todo se deposita en la gran disolución, y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como su soporte supremo. <em>Vettā</em> y <em>vedya</em>, «el que conoce» y «lo que ha de conocerse», ponen a Kṛṣṇa a la vez como sujeto y objeto del conocimiento; «lo que ha de conocerse» ya estaba en <a class=\"vref\" href=\"capitulo-09.html#v17\" data-v=\"9.17\">9.17</a>. <em>Paraṃ dhāma</em>, «la morada suprema», repite lo que Arjuna dijo en <a class=\"vref\" href=\"capitulo-10.html#v12\" data-v=\"10.12\">10.12</a> (véase la alternativa de aquel verso). <em>Tatam</em>, «penetrado», como en <a class=\"vref\" href=\"capitulo-02.html#v17\" data-v=\"2.17\">2.17</a> y <a class=\"vref\" href=\"capitulo-09.html#v4\" data-v=\"9.4\">9.4</a>.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 39, "hablante": "arjuna", "sa": ["वायुर्यमोऽग्निर्वरुणः शशाङ्कः प्रजापतिस्त्वं प्रपितामहश्च ।", "नमो नमस्तेऽस्तु सहस्रकृत्वः पुनश्च भूयोऽपि नमो नमस्ते ॥३९॥"], "iast": ["vāyur yamo 'gnir varuṇaḥ śaśāṅkaḥ prajāpatis tvaṃ prapitāmahaś ca", "namo namas te 'stu sahasra-kṛtvaḥ punaś ca bhūyo 'pi namo namas te"], "rojas": [], "t": "<span class=\"vt-parte\">Tú eres <a class=\"t\" href=\"glosario.html#vayu\" data-t=\"vayu\">Vāyu</a>, <a class=\"t\" href=\"glosario.html#yama\" data-t=\"yama\">Yama</a>, <a class=\"t\" href=\"glosario.html#agni\" data-t=\"agni\">Agni</a>, <a class=\"t\" href=\"glosario.html#varuna\" data-t=\"varuna\">Varuṇa</a>, la luna; eres <a class=\"t\" href=\"glosario.html#prajapati\" data-t=\"prajapati\">Prajāpati</a> y el <a class=\"t\" href=\"glosario.html#prapitamaha\" data-t=\"prapitamaha\">bisabuelo</a>. ¡Homenaje, homenaje a ti mil veces, y otra vez, y aún otra: homenaje, homenaje a ti!</span>", "palabras": [{"iast": "vāyuḥ", "sa": "वायुः", "gram": "nom. sg. m.", "es": "Vāyu, el viento", "ref": "vayu"}, {"iast": "yamaḥ", "sa": "यमः", "gram": "nom. sg. m.", "es": "Yama", "ref": "yama"}, {"iast": "agniḥ", "sa": "अग्निः", "gram": "nom. sg. m.", "es": "Agni, el fuego", "ref": "agni"}, {"iast": "varuṇaḥ", "sa": "वरुणः", "gram": "nom. sg. m.", "es": "Varuṇa", "ref": "varuna"}, {"iast": "śaśa-aṅkaḥ", "sa": "शशाङ्कः", "gram": "nom. sg. m. comp.", "es": "la luna", "analisis": "śaśa (liebre) + aṅka (marca): «el que lleva la marca de la liebre»"}, {"iast": "prajāpatiḥ", "sa": "प्रजापतिः", "gram": "nom. sg. m.", "es": "Prajāpati, el señor de las criaturas", "ref": "prajapati"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "prapitāmahaḥ", "sa": "प्रपितामहः", "gram": "nom. sg. m.", "es": "el bisabuelo", "ref": "prapitamaha", "analisis": "pra- (anterior) + pitāmaha (abuelo, el gran padre)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "namaḥ", "sa": "नमः", "gram": "nom. sg. n.", "es": "homenaje, reverencia", "analisis": "namas, de √nam (inclinarse)"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "astu", "sa": "अस्तु", "gram": "3 sg. imperat.", "es": "sea", "analisis": "√as (ser)"}, {"iast": "sahasra-kṛtvaḥ", "sa": "सहस्रकृत्वः", "gram": "adv. comp.", "es": "mil veces", "analisis": "sahasra (mil) + -kṛtvas (veces)"}, {"iast": "punaḥ", "sa": "पुनः", "gram": "adv.", "es": "otra vez"}, {"iast": "bhūyaḥ", "sa": "भूयः", "gram": "adv.", "es": "y aún más"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "también"}], "nota": "<p>Arjuna nombra a los grandes dioses védicos: <a class=\"t\" href=\"glosario.html#vayu\" data-t=\"vayu\">Vāyu</a>, el viento; <a class=\"t\" href=\"glosario.html#yama\" data-t=\"yama\">Yama</a>, señor de los muertos; <a class=\"t\" href=\"glosario.html#agni\" data-t=\"agni\">Agni</a>, el fuego; <a class=\"t\" href=\"glosario.html#varuna\" data-t=\"varuna\">Varuṇa</a>, señor de las aguas; <em>śaśāṅka</em>, «el que lleva la marca de la liebre», la luna, en cuyas manchas la imaginación india ve una liebre; y <a class=\"t\" href=\"glosario.html#prajapati\" data-t=\"prajapati\">Prajāpati</a>, el señor de las criaturas. <em>Prapitāmaha</em>, «bisabuelo», va un grado más allá de <em>pitāmaha</em>, «abuelo», título del creador <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a>, padre de los Prajāpatis y por ellos abuelo de los seres: Kṛṣṇa, del que nace Brahmā, es el padre del abuelo, como explica <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como glosan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> (véase la nota a <a class=\"vref\" href=\"capitulo-09.html#v17\" data-v=\"9.17\">9.17</a>, donde Kṛṣṇa se dice el abuelo). <em>Namas</em>, «inclinación, homenaje», es la palabra del saludo ritual; su repetición, «homenaje, homenaje», llena el verso y el siguiente.</p>", "interp": [{"titulo": "Todos los dioses en uno", "html": "<p>La lista no sustituye a los dioses: los incluye. Vāyu, Yama, Agni y Varuṇa siguen siendo quienes son, pero Arjuna los ve como formas de aquel al que tiene delante, igual que en <a class=\"vref\" href=\"capitulo-10.html#v21\" data-v=\"10.21\">10.21</a>–<a class=\"vref\" href=\"capitulo-10.html#v29\" data-v=\"10.29\">10.29</a> Kṛṣṇa se había dicho Viṣṇu entre los Ādityas, Varuṇa entre los seres de las aguas y Yama entre los que someten. Es la teología del capítulo 9 dicha en forma de plegaria: el que sacrifica a otros dioses le sacrifica a él (<a class=\"vref\" href=\"capitulo-09.html#v23\" data-v=\"9.23\">9.23</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 40, "hablante": "arjuna", "sa": ["नमः पुरस्तादथ पृष्ठतस्ते नमोऽस्तु ते सर्वत एव सर्व ।", "अनन्तवीर्यामितविक्रमस्त्वं सर्वं समाप्नोषि ततोऽसि सर्वः ॥४०॥"], "iast": ["namaḥ purastād atha pṛṣṭhatas te namo 'stu te sarvata eva sarva", "ananta-vīryāmita-vikramas tvaṃ sarvaṃ samāpnoṣi tato 'si sarvaḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Homenaje a ti por delante y por detrás; homenaje a ti por todas partes, oh Todo. Infinita es tu fuerza y sin medida tu poder; todo lo abarcas, y por eso eres todo.</span>", "palabras": [{"iast": "namaḥ", "sa": "नमः", "gram": "nom. sg. n.", "es": "homenaje"}, {"iast": "purastāt", "sa": "पुरस्तात्", "gram": "adv.", "es": "por delante"}, {"iast": "atha", "sa": "अथ", "gram": "conj.", "es": "y también"}, {"iast": "pṛṣṭhataḥ", "sa": "पृष्ठतः", "gram": "adv.", "es": "por detrás", "analisis": "de pṛṣṭha (espalda)"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "astu", "sa": "अस्तु", "gram": "3 sg. imperat.", "es": "sea", "analisis": "√as (ser)"}, {"iast": "sarvataḥ", "sa": "सर्वतः", "gram": "adv.", "es": "por todas partes"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "(enfática)"}, {"iast": "sarva", "sa": "सर्व", "gram": "voc. sg. m.", "es": "oh Todo"}, {"iast": "ananta-vīrya-amita-vikramaḥ", "sa": "अनन्तवीर्यामितविक्रमः", "gram": "nom. sg. m. comp.", "es": "de fuerza infinita y de poder sin medida", "analisis": "ananta (sin fin) + vīrya (fuerza) + amita (sin medida) + vikrama (empuje, poder)"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "acc. sg. n.", "es": "todo"}, {"iast": "samāpnoṣi", "sa": "समाप्नोषि", "gram": "2 sg. pres.", "es": "abarcas, penetras por completo", "analisis": "sam-√āp (alcanzar del todo)"}, {"iast": "tataḥ", "sa": "ततः", "gram": "adv.", "es": "por eso"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres.", "es": "eres", "analisis": "√as (ser)"}, {"iast": "sarvaḥ", "sa": "सर्वः", "gram": "nom. sg. m.", "es": "todo"}], "nota": "<p><em>Sarva</em>, «todo», va dos veces en vocativo y en nominativo: «oh Todo» y «eres todo». La segunda mitad da la razón del nombre: Kṛṣṇa es todo porque todo lo alcanza y lo llena (<em>samāpnoṣi</em>, de sam-√āp, «alcanzar por completo»). Es la forma de plegaria de lo que Kṛṣṇa había enseñado en <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a> («Vāsudeva es todo») y en <a class=\"vref\" href=\"capitulo-09.html#v4\" data-v=\"9.4\">9.4</a>.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 41, "hablante": "arjuna", "sa": ["सखेति मत्वा प्रसभं यदुक्तं हे कृष्ण हे यादव हे सखेति ।", "अजानता महिमानं तवेदं मया प्रमादात्प्रणयेन वापि ॥४१॥"], "iast": ["sakheti matvā prasabhaṃ yad uktaṃ he kṛṣṇa he yādava he sakheti", "ajānatā mahimānaṃ tavedaṃ mayā pramādāt praṇayena vāpi"], "rojas": [], "t": "<span class=\"vt-parte\">Todo lo que, tomándote por un amigo, te dije sin miramientos —«¡eh, <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Kṛṣṇa</a>!, ¡eh, <a class=\"t\" href=\"glosario.html#yadavas\" data-t=\"yadavas\">Yādava</a>!, ¡eh, amigo!»—, sin conocer esta grandeza tuya, por descuido o por cariño,</span>", "palabras": [{"iast": "sakhā", "sa": "सखा", "gram": "nom. sg. m.", "es": "amigo, compañero"}, {"iast": "iti", "sa": "इति", "gram": "part.", "es": "(cierra la cita): así"}, {"iast": "matvā", "sa": "मत्वा", "gram": "abs.", "es": "creyendo, tomando por", "analisis": "√man (pensar)"}, {"iast": "prasabham", "sa": "प्रसभम्", "gram": "adv.", "es": "sin miramientos, con atrevimiento"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "lo que"}, {"iast": "uktam", "sa": "उक्तम्", "gram": "nom. sg. n. ppp.", "es": "fue dicho", "analisis": "√vac (hablar)"}, {"iast": "he", "sa": "हे", "gram": "interj.", "es": "¡eh!"}, {"iast": "kṛṣṇa", "sa": "कृष्ण", "gram": "voc. sg. m.", "es": "Kṛṣṇa", "ref": "krsna"}, {"iast": "yādava", "sa": "यादव", "gram": "voc. sg. m.", "es": "Yādava, descendiente de Yadu", "ref": "yadavas"}, {"iast": "sakhe", "sa": "सखे", "gram": "voc. sg. m.", "es": "amigo"}, {"iast": "ajānatā", "sa": "अजानता", "gram": "instr. sg. m. ppr.", "es": "sin conocer", "analisis": "a- (no) + √jñā (conocer)"}, {"iast": "mahimānam", "sa": "महिमानम्", "gram": "acc. sg. m.", "es": "la grandeza", "analisis": "mahiman, de mahā (grande)"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "idam", "sa": "इदम्", "gram": "nom./acc. sg. n.", "es": "esto"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "pramādāt", "sa": "प्रमादात्", "gram": "abl. sg. m.", "es": "por descuido", "analisis": "pra-√mad (descuidarse)"}, {"iast": "praṇayena", "sa": "प्रणयेन", "gram": "instr. sg. m.", "es": "por cariño, por confianza", "analisis": "pra-√nī (guiar; familiaridad, afecto)"}, {"iast": "vā", "sa": "वा", "gram": "conj.", "es": "o"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "también"}], "nota": "<p>Este verso y el siguiente forman una sola frase, que termina en «te pido perdón» (<a class=\"vref\" href=\"capitulo-11.html#v42\" data-v=\"11.42\">11.42</a>). <em>Prasabham</em> es «a la fuerza», «sin consideración»: el trato confiado, sin las formas que se deben a un superior. Las tres llamadas, con la interjección familiar <em>he</em>, reproducen ese trato: por su nombre, por su linaje (los <a class=\"t\" href=\"glosario.html#yadavas\" data-t=\"yadavas\">Yādavas</a>, descendientes de Yadu) y como «amigo». <em>Tavedam</em> es <em>tava idam</em>, «esto tuyo»; <em>idam</em> es neutro y no concierta con <em>mahimānam</em>, que es masculino: «esta grandeza tuya» traduce el sentido, pero la gramática deja ver «esto», lo que Arjuna tiene ahora delante, la forma universal: así lo entienden <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, «sin conocer tu grandeza y esta forma universal». Śaṅkara y Madhusūdana recogen también la variante <em>tavemam</em>, con <em>imam</em> masculino, que concierta con <em>mahimānam</em> y que parece seguir <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>. Viśvanātha Cakravartī entiende la grandeza como la forma universal. <em>Praṇaya</em> es la confianza que da el cariño: el amigo no mide sus palabras.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 42, "hablante": "arjuna", "sa": ["यच्चावहासार्थमसत्कृतोऽसि विहारशय्यासनभोजनेषु ।", "एकोऽथवाप्यच्युत तत्समक्षं तत्क्षामये त्वामहमप्रमेयम् ॥४२॥"], "iast": ["yac cāvahāsārtham asat-kṛto 'si vihāra-śayyāsana-bhojaneṣu", "eko 'tha vāpy acyuta tat-samakṣaṃ tat kṣāmaye tvām aham aprameyam"], "rojas": [], "t": "<span class=\"vt-parte\">y las veces que, en broma, te falté al respeto, al pasear, al acostarnos, sentados o comiendo, a solas, oh <a class=\"t\" href=\"glosario.html#acyuta\" data-t=\"acyuta\">Acyuta</a>, o delante de otros: de todo eso te pido perdón, a ti, el inconmensurable.</span>", "palabras": [{"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "lo que, las veces que"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "avahāsa-artham", "sa": "अवहासार्थम्", "gram": "adv. comp.", "es": "en broma, por reír", "analisis": "avahāsa (burla, risa) + artham (con el fin de)"}, {"iast": "asat-kṛtaḥ", "sa": "असत्कृतः", "gram": "nom. sg. m. ppp. comp.", "es": "tratado sin respeto", "analisis": "asat (no debido) + kṛta (hecho, tratado)"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres.", "es": "has sido", "analisis": "√as (ser)"}, {"iast": "vihāra-śayyā-āsana-bhojaneṣu", "sa": "विहारशय्यासनभोजनेषु", "gram": "loc. pl. n. comp.", "es": "al pasear, al acostarnos, sentados o comiendo", "analisis": "vihāra (paseo, recreo) + śayyā (lecho) + āsana (asiento) + bhojana (comida)"}, {"iast": "ekaḥ", "sa": "एकः", "gram": "nom. sg. m.", "es": "a solas"}, {"iast": "athavā", "sa": "अथवा", "gram": "conj.", "es": "o bien"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "también"}, {"iast": "acyuta", "sa": "अच्युत", "gram": "voc. sg. m.", "es": "oh Acyuta", "ref": "acyuta"}, {"iast": "tat-samakṣam", "sa": "तत्समक्षम्", "gram": "adv. comp.", "es": "en presencia de ellos, ante otros", "analisis": "tat (ellos) + samakṣa (a la vista)"}, {"iast": "tat", "sa": "तत्", "gram": "acc. sg. n.", "es": "eso"}, {"iast": "kṣāmaye", "sa": "क्षामये", "gram": "1 sg. pres. caus.", "es": "pido perdón", "analisis": "causativo de √kṣam (soportar, perdonar)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "acc. sg. pron.", "es": "a ti"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "aprameyam", "sa": "अप्रमेयम्", "gram": "acc. sg. m.", "es": "inconmensurable", "analisis": "a- (no) + prameya (medible, de pra-√mā)"}], "nota": "<p>La lista de 11.42 es la de la vida en común: paseos, descanso, asiento, comida. Arjuna y Kṛṣṇa son primos (la madre de Arjuna, <a class=\"t\" href=\"glosario.html#kunti\" data-t=\"kunti\">Kuntī</a>, es hermana del padre de Kṛṣṇa) y amigos inseparables en el <em>Mahābhārata</em>. <em>Tat-samakṣam</em>, «a la vista de ellos», es en presencia de los compañeros que estaban con ellos, según <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> toma <em>tat</em> como adverbio y entiende sólo «en público», frente a <em>ekaḥ</em>, «en privado». <em>Kṣāmaye</em>, causativo de √kṣam, «soportar», es literalmente «hago que soportes», «te pido que me perdones». <a class=\"t\" href=\"glosario.html#acyuta\" data-t=\"acyuta\">Acyuta</a>, «el que no cae», es el nombre con que Arjuna se dirigió a Kṛṣṇa al empezar la batalla (<a class=\"vref\" href=\"capitulo-01.html#v21\" data-v=\"1.21\">1.21</a>).</p>", "interp": [{"titulo": "La amistad y la majestad", "html": "<p>Los dos versos son de los más humanos del poema: el que acaba de ver la forma que llena el cielo y devora a los guerreros recuerda las bromas de la mesa y del camino. La Gītā no borra esa amistad, la pone a prueba: el Kṛṣṇa del que Arjuna fue compañero y el que se ha mostrado son el mismo. Y Kṛṣṇa no le reprocha nada; al contrario, le devolverá la forma conocida (<a class=\"vref\" href=\"capitulo-11.html#v50\" data-v=\"11.50\">11.50</a>) y, al final de la obra, lo llamará «muy querido» (<a class=\"vref\" href=\"capitulo-18.html#v64\" data-v=\"18.64\">18.64</a>), como ya lo había llamado «mi devoto y mi amigo» (<a class=\"vref\" href=\"capitulo-04.html#v3\" data-v=\"4.3\">4.3</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 43, "hablante": "arjuna", "sa": ["पितासि लोकस्य चराचरस्य त्वमस्य पूज्यश्च गुरुर्गरीयान् ।", "न त्वत्समोऽस्त्यभ्यधिकः कुतोऽन्यो लोकत्रयेऽप्यप्रतिमप्रभाव ॥४३॥"], "iast": ["pitāsi lokasya carācarasya tvam asya pūjyaś ca gurur garīyān", "na tvat-samo 'sty abhyadhikaḥ kuto 'nyo loka-traye 'py apratima-prabhāva"], "rojas": [], "t": "<span class=\"vt-parte\">Eres el padre del mundo, de lo móvil y de lo inmóvil; tú eres para él digno de veneración, su <a class=\"t\" href=\"glosario.html#guru\" data-t=\"guru\">maestro</a> más venerable. No hay nadie igual a ti: ¿cómo habría otro superior, en los tres mundos, oh tú, de poder sin igual?</span>", "palabras": [{"iast": "pitā", "sa": "पिता", "gram": "nom. sg. m.", "es": "el padre"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres.", "es": "eres", "analisis": "√as (ser)"}, {"iast": "lokasya", "sa": "लोकस्य", "gram": "gen. sg. m.", "es": "del mundo"}, {"iast": "cara-acarasya", "sa": "चराचरस्य", "gram": "gen. sg. m. comp.", "es": "de lo móvil y lo inmóvil", "analisis": "cara (que se mueve) + acara (que no se mueve)"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. m. pron.", "es": "de él, de este (mundo)"}, {"iast": "pūjyaḥ", "sa": "पूज्यः", "gram": "nom. sg. m. gerundivo", "es": "digno de veneración", "analisis": "√pūj (venerar)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "guruḥ", "sa": "गुरुः", "gram": "nom. sg. m.", "es": "el maestro", "ref": "guru"}, {"iast": "garīyān", "sa": "गरीयान्", "gram": "nom. sg. m.", "es": "más venerable, el más grande", "analisis": "comparativo de guru"}, {"iast": "na", "sa": "न", "gram": "neg.", "es": "no"}, {"iast": "tvat-samaḥ", "sa": "त्वत्समः", "gram": "nom. sg. m. comp.", "es": "igual a ti", "analisis": "tvat (tú) + sama (igual)"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres.", "es": "hay", "analisis": "√as (ser)"}, {"iast": "abhyadhikaḥ", "sa": "अभ्यधिकः", "gram": "nom. sg. m.", "es": "superior"}, {"iast": "kutaḥ", "sa": "कुतः", "gram": "adv. interr.", "es": "¿cómo?, ¿de dónde?"}, {"iast": "anyaḥ", "sa": "अन्यः", "gram": "nom. sg. m.", "es": "otro"}, {"iast": "loka-traye", "sa": "लोकत्रये", "gram": "loc. sg. n. comp.", "es": "en los tres mundos", "analisis": "loka (mundo) + traya (tríada)"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "aun"}, {"iast": "apratima-prabhāva", "sa": "अप्रतिमप्रभाव", "gram": "voc. sg. m. comp.", "es": "oh tú, de poder sin igual", "analisis": "apratima (sin par) + prabhāva (poder, grandeza)"}], "nota": "<p><em>Pūjyaś ca gurur garīyān</em>: Kṛṣṇa es «digno de veneración» y «el maestro más venerable» (<em>garīyān</em>, comparativo de <em>guru</em>, «pesado, grave, venerable», con valor de superlativo: el más digno de respeto, como glosa <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo entienden como comparativo, «más venerable aún que un maestro»). El padre y el maestro son, en la tradición india, las dos figuras que más reverencia merecen; Arjuna, que acaba de pedir perdón por haber tratado a Kṛṣṇa como a un igual, lo pone ahora por encima de ambas. <em>Loka-traya</em>, «los tres mundos», son la tierra, el espacio intermedio y el cielo.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 44, "hablante": "arjuna", "sa": ["तस्मात्प्रणम्य प्रणिधाय कायं प्रसादये त्वामहमीशमीड्यम् ।", "पितेव पुत्रस्य सखेव सख्युः प्रियः प्रियायार्हसि देव सोढुम् ॥४४॥"], "iast": ["tasmāt praṇamya praṇidhāya kāyaṃ prasādaye tvām aham īśam īḍyam", "piteva putrasya sakheva sakhyuḥ priyaḥ priyāyārhasi deva soḍhum"], "rojas": [], "t": "<span class=\"vt-parte\">Por eso, inclinándome y postrándome en tierra, te pido tu gracia a ti, el Señor digno de alabanza. Como un padre con su hijo, como un amigo con su amigo, como el amante con su amada, dígnate tener paciencia conmigo, oh dios.</span>", "palabras": [{"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. pron.", "es": "por eso"}, {"iast": "praṇamya", "sa": "प्रणम्य", "gram": "abs.", "es": "inclinándome", "analisis": "pra-√nam (inclinarse)"}, {"iast": "praṇidhāya", "sa": "प्रणिधाय", "gram": "abs.", "es": "postrando, poniendo en tierra", "analisis": "pra-ni-√dhā (poner delante, depositar)"}, {"iast": "kāyam", "sa": "कायम्", "gram": "acc. sg. m.", "es": "el cuerpo"}, {"iast": "prasādaye", "sa": "प्रसादये", "gram": "1 sg. pres. caus.", "es": "busco tu gracia, te pido que te apacigües", "analisis": "causativo de pra-√sad (calmarse, ser favorable)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "acc. sg. pron.", "es": "a ti"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "īśam", "sa": "ईशम्", "gram": "acc. sg. m.", "es": "al Señor", "analisis": "de √īś (gobernar)"}, {"iast": "īḍyam", "sa": "ईड्यम्", "gram": "acc. sg. m. gerundivo", "es": "digno de alabanza", "analisis": "√īḍ (alabar)"}, {"iast": "pitā", "sa": "पिता", "gram": "nom. sg. m.", "es": "un padre"}, {"iast": "iva", "sa": "इव", "gram": "part.", "es": "como"}, {"iast": "putrasya", "sa": "पुत्रस्य", "gram": "gen. sg. m.", "es": "con su hijo, del hijo"}, {"iast": "sakhā", "sa": "सखा", "gram": "nom. sg. m.", "es": "un amigo"}, {"iast": "sakhyuḥ", "sa": "सख्युः", "gram": "gen. sg. m.", "es": "con su amigo, del amigo"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m.", "es": "el amante, el que ama", "analisis": "priya (querido)"}, {"iast": "priyāyāḥ", "sa": "प्रियायाः", "gram": "gen. sg. f.", "es": "con su amada, de la amada"}, {"iast": "arhasi", "sa": "अर्हसि", "gram": "2 sg. pres.", "es": "te dignes, debes", "analisis": "√arh (merecer, ser digno)"}, {"iast": "deva", "sa": "देव", "gram": "voc. sg. m.", "es": "oh dios", "ref": "deva"}, {"iast": "soḍhum", "sa": "सोढुम्", "gram": "inf.", "es": "soportar, tener paciencia", "analisis": "√sah (soportar)"}], "nota": "<p>Las tres imágenes van de la relación más desigual a la más íntima: el padre perdona al hijo, el amigo al amigo, el amante a la amada. Arjuna pide a Kṛṣṇa que lo trate como cada uno de ellos trata al otro: con la paciencia (<em>soḍhum</em>, de √sah, «soportar») de quien ama. <em>Prasādaye</em>, causativo de pra-√sad, «calmarse, aclararse, ser favorable», es pedir <em>prasāda</em>, la gracia del dios aplacado; la misma palabra cierra el verso siguiente, <em>prasīda</em>, «ten piedad».</p>", "interp": [{"titulo": "Tres maneras de amar", "html": "<p>Las tres imágenes del verso —el padre, el amigo, el amante— son tres de las formas de amor que la teología de la devoción desarrollará siglos después. La escuela <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a> distinguirá, a partir de Rūpa Gosvāmī, discípulo de <a class=\"t\" href=\"glosario.html#caitanya\" data-t=\"caitanya\">Caitanya</a>, varias relaciones (<em>rasa</em>) con Kṛṣṇa: entre ellas la del amigo (<em>sakhya</em>), la del padre o la madre (<em>vātsalya</em>) y la de la amada (<em>mādhurya</em>). El verso de la Gītā no las sistematiza, y en él es Kṛṣṇa quien hace de padre, mientras que en el <em>vātsalya</em> el devoto ama a Kṛṣṇa como a un hijo; pero muestra que el lenguaje de la devoción ya tenía a mano esas tres maneras de pedir perdón. Prabhupāda lee el verso en esa clave: los devotos se relacionan con Kṛṣṇa como con un hijo, un esposo, un amigo o un señor. Viśvanātha Cakravartī, en cambio, sólo comenta aquí la forma de las palabras.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Por eso, inclinándome y postrándome en tierra, te pido tu gracia a ti, el Señor digno de alabanza. Como un padre con su hijo, como un amigo con su amigo, como quien ama con aquel a quien ama, dígnate tener paciencia conmigo, oh dios.", "nota": "<p><em>Priyāyārhasi</em> es una unión irregular de dos palabras. Puede deshacerse en <em>priyāyāḥ arhasi</em>, con <em>priyāyāḥ</em> en genitivo femenino, «de la amada», en paralelo con <em>putrasya</em> y <em>sakhyuḥ</em>, como hace la traducción principal con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> (este último explica la unión como irregularidad arcaica, <em>chāndasa</em>), y también Viśvanātha Cakravartī, que ve en ella una licencia poética, y Prabhupāda; o en <em>priyāya arhasi</em>, con <em>priyāya</em> en dativo masculino, como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, que no hace de ello una tercera comparación, sino que lo dice de Kṛṣṇa y Arjuna: «tú, que eres querido, has de soportarme a mí, que te soy querido». El paralelo con los dos genitivos anteriores favorece la primera lectura, pero la forma admite las dos. <em>Arhasi</em> con infinitivo, «te dignas, debes», es una fórmula de ruego cortés que Arjuna ya había usado (véase <a class=\"vref\" href=\"capitulo-06.html#v39\" data-v=\"6.39\">6.39</a> y <a class=\"vref\" href=\"capitulo-10.html#v16\" data-v=\"10.16\">10.16</a>).</p>"}]}, {"n": 45, "hablante": "arjuna", "sa": ["अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा भयेन च प्रव्यथितं मनो मे ।", "तदेव मे दर्शय देव रूपं प्रसीद देवेश जगन्निवास ॥४५॥"], "iast": ["adṛṣṭa-pūrvaṃ hṛṣito 'smi dṛṣṭvā bhayena ca pravyathitaṃ mano me", "tad eva me darśaya deva rūpaṃ prasīda deveśa jagan-nivāsa"], "rojas": [], "t": "<span class=\"vt-parte\">He visto lo que nadie había visto, y me alegro; pero el miedo me turba la mente. Muéstrame, oh dios, aquella forma tuya de antes; ten piedad, señor de los dioses, morada del universo.</span>", "palabras": [{"iast": "adṛṣṭa-pūrvam", "sa": "अदृष्टपूर्वम्", "gram": "acc. sg. n. comp.", "es": "lo nunca visto", "analisis": "a- (no) + dṛṣṭa (visto) + pūrva (antes)"}, {"iast": "hṛṣitaḥ", "sa": "हृषितः", "gram": "nom. sg. m. ppp.", "es": "alegre, gozoso", "analisis": "√hṛṣ (alegrarse)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres.", "es": "estoy", "analisis": "√as (ser)"}, {"iast": "dṛṣṭvā", "sa": "दृष्ट्वा", "gram": "abs.", "es": "al ver", "analisis": "√dṛś (ver)"}, {"iast": "bhayena", "sa": "भयेन", "gram": "instr. sg. n.", "es": "de miedo"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "pravyathitam", "sa": "प्रव्यथितम्", "gram": "nom. sg. n. ppp.", "es": "turbada, agitada", "analisis": "pra-√vyath (temblar, angustiarse)"}, {"iast": "manaḥ", "sa": "मनः", "gram": "nom. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "tat", "sa": "तत्", "gram": "acc. sg. n.", "es": "aquella"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "misma"}, {"iast": "darśaya", "sa": "दर्शय", "gram": "2 sg. imperat. caus.", "es": "muéstrame", "analisis": "causativo de √dṛś (ver)"}, {"iast": "deva", "sa": "देव", "gram": "voc. sg. m.", "es": "oh dios", "ref": "deva"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "acc. sg. n.", "es": "forma"}, {"iast": "prasīda", "sa": "प्रसीद", "gram": "2 sg. imperat.", "es": "ten piedad, sé propicio", "analisis": "pra-√sad (calmarse, ser favorable)"}, {"iast": "deva-īśa", "sa": "देवेश", "gram": "voc. sg. m. comp.", "es": "oh señor de los dioses", "analisis": "deva (dios) + īśa (señor)"}, {"iast": "jagan-nivāsa", "sa": "जगन्निवास", "gram": "voc. sg. m. comp.", "es": "oh morada del universo", "analisis": "jagat (mundo) + nivāsa (morada)"}], "nota": "<p><em>Adṛṣṭa-pūrva</em>, «no visto antes»: es lo que Kṛṣṇa había prometido mostrar en <a class=\"vref\" href=\"capitulo-11.html#v6\" data-v=\"11.6\">11.6</a>, «maravillas nunca vistas». Arjuna siente a la vez gozo y miedo, las dos caras de lo sagrado que el capítulo no separa. <em>Tad eva rūpam</em>, «aquella misma forma», es la que conocía antes de la visión; el verso siguiente la describe.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 46, "hablante": "arjuna", "sa": ["किरीटिनं गदिनं चक्रहस्तमिच्छामि त्वां द्रष्टुमहं तथैव ।", "तेनैव रूपेण चतुर्भुजेन सहस्रबाहो भव विश्वमूर्ते ॥४६॥"], "iast": ["kirīṭinaṃ gadinaṃ cakra-hastam icchāmi tvāṃ draṣṭum ahaṃ tathaiva", "tenaiva rūpeṇa catur-bhujena sahasra-bāho bhava viśva-mūrte"], "rojas": [], "t": "<span class=\"vt-parte\">Quiero verte como antes, con la diadema, con la maza y con el disco en la mano. Toma de nuevo esa <a class=\"t\" href=\"glosario.html#caturbhuja\" data-t=\"caturbhuja\">forma de cuatro brazos</a>, oh tú, de mil brazos, oh <a class=\"t\" href=\"glosario.html#visvarupa\" data-t=\"visvarupa\">forma universal</a>.</span>", "palabras": [{"iast": "kirīṭinam", "sa": "किरीटिनम्", "gram": "acc. sg. m.", "es": "con la diadema", "analisis": "kirīṭa (diadema) + -in"}, {"iast": "gadinam", "sa": "गदिनम्", "gram": "acc. sg. m.", "es": "con la maza", "analisis": "gadā (maza) + -in"}, {"iast": "cakra-hastam", "sa": "चक्रहस्तम्", "gram": "acc. sg. m. comp.", "es": "con el disco en la mano", "analisis": "cakra (disco) + hasta (mano)"}, {"iast": "icchāmi", "sa": "इच्छामि", "gram": "1 sg. pres.", "es": "quiero, deseo", "analisis": "√iṣ (desear)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "acc. sg. pron.", "es": "a ti"}, {"iast": "draṣṭum", "sa": "द्रष्टुम्", "gram": "inf.", "es": "ver", "analisis": "√dṛś (ver)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "tathā", "sa": "तथा", "gram": "adv.", "es": "así, como antes"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "mismo"}, {"iast": "tena", "sa": "तेन", "gram": "instr. sg. n. pron.", "es": "con esa"}, {"iast": "rūpeṇa", "sa": "रूपेण", "gram": "instr. sg. n.", "es": "con la forma"}, {"iast": "catur-bhujena", "sa": "चतुर्भुजेन", "gram": "instr. sg. n. comp.", "es": "de cuatro brazos", "ref": "caturbhuja", "analisis": "catur (cuatro) + bhuja (brazo)"}, {"iast": "sahasra-bāho", "sa": "सहस्रबाहो", "gram": "voc. sg. m. comp.", "es": "oh tú, de mil brazos", "analisis": "sahasra (mil) + bāhu (brazo)"}, {"iast": "bhava", "sa": "भव", "gram": "2 sg. imperat.", "es": "sé, vuelve a ser", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "viśva-mūrte", "sa": "विश्वमूर्ते", "gram": "voc. sg. m. comp.", "es": "oh forma universal", "ref": "visvarupa", "analisis": "viśva (todo, el universo) + mūrti (forma, figura)"}], "nota": "<p>La diadema, la maza y el disco son atributos de <a class=\"t\" href=\"glosario.html#visnu\" data-t=\"visnu\">Viṣṇu</a>, al que la iconografía representa con cuatro brazos, con la caracola y el loto como los otros dos emblemas. El verso plantea una pregunta que los comentaristas resuelven de modos distintos: Arjuna pide verlo «como antes» (<em>tathaiva</em>) y «con esa forma de cuatro brazos»: ¿tenía cuatro brazos el Kṛṣṇa que conducía su carro? <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> responden que sí: la forma del hijo de Vasudeva, la que Arjuna conocía, era la de cuatro brazos, y es la que Kṛṣṇa vuelve a tomar en <a class=\"vref\" href=\"capitulo-11.html#v50\" data-v=\"11.50\">11.50</a>; Viśvanātha Cakravartī y Prabhupāda entienden que Kṛṣṇa muestra primero la forma de cuatro brazos y después la humana (<a class=\"vref\" href=\"capitulo-11.html#v51\" data-v=\"11.51\">11.51</a>). Véase la ficha <a class=\"t\" href=\"glosario.html#caturbhuja\" data-t=\"caturbhuja\">caturbhuja</a>. Los dos vocativos finales, «de mil brazos» y «forma universal», nombran todavía lo que Arjuna tiene delante y quiere dejar de ver.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 47, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "मया प्रसन्नेन तवार्जुनेदं रूपं परं दर्शितमात्मयोगात् ।", "तेजोमयं विश्वमनन्तमाद्यं यन्मे त्वदन्येन न दृष्टपूर्वम् ॥४७॥"], "iast": ["śrī-bhagavān uvāca", "mayā prasannena tavārjunedaṃ rūpaṃ paraṃ darśitam ātma-yogāt", "tejomayaṃ viśvam anantam ādyaṃ yan me tvad anyena na dṛṣṭa-pūrvam"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Complacido contigo, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, por mi propio <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga</a> te he mostrado esta <a class=\"t\" href=\"glosario.html#visvarupa\" data-t=\"visvarupa\">forma</a> suprema, hecha de luz, universal, infinita, primordial, que nadie antes que tú había visto.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m.", "es": "el Señor bienaventurado", "ref": "bhagavan"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. perf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "prasannena", "sa": "प्रसन्नेन", "gram": "instr. sg. m. part. pas.", "es": "complacido, propicio", "analisis": "pra-√sad (serenarse, mostrarse favorable)"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "a ti, para ti"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "esta"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "nom. sg. n.", "es": "forma", "ref": "visvarupa"}, {"iast": "param", "sa": "परम्", "gram": "nom. sg. n. adj.", "es": "suprema"}, {"iast": "darśitam", "sa": "दर्शितम्", "gram": "nom. sg. n. part. pas. caus.", "es": "mostrada", "analisis": "caus. de √dṛś (ver): hacer ver"}, {"iast": "ātma-yogāt", "sa": "आत्मयोगात्", "gram": "abl. sg. m.", "es": "por mi propio yoga, por mi propio poder", "ref": "yoga-maya", "analisis": "ātman (uno mismo) + yoga (aquí, poder)"}, {"iast": "tejomayam", "sa": "तेजोमयम्", "gram": "nom. sg. n. adj.", "es": "hecha de luz, resplandeciente", "ref": "tejas", "analisis": "tejas (esplendor) + -maya (hecho de)"}, {"iast": "viśvam", "sa": "विश्वम्", "gram": "nom. sg. n. adj.", "es": "universal, que es el todo"}, {"iast": "anantam", "sa": "अनन्तम्", "gram": "nom. sg. n. adj.", "es": "infinita", "analisis": "an- (sin) + anta (fin)"}, {"iast": "ādyam", "sa": "आद्यम्", "gram": "nom. sg. n. adj.", "es": "primordial, primera"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "que"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mía"}, {"iast": "tvad anyena", "sa": "त्वदन्येन", "gram": "instr. sg. m.", "es": "por otro que tú", "analisis": "tvad (tú) + anya (otro)"}, {"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "dṛṣṭa-pūrvam", "sa": "दृष्टपूर्वम्", "gram": "nom. sg. n. part. pas.", "es": "visto antes", "analisis": "dṛṣṭa (visto) + pūrva (antes)"}], "nota": "<p><em>Prasannena</em>, «complacido, propicio»: la visión es un don, no una conquista; es lo que el capítulo repetirá en <a class=\"vref\" href=\"capitulo-11.html#v48\" data-v=\"11.48\">11.48</a> y <a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a>. <em>Ātma-yogāt</em>, «por mi propio yoga» (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>: «por el poder de mi soberanía»; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>: «de mi <em>yoga-māyā</em>»; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: «mi poder propio»; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: «por mi voluntad infalible»), da a <em>yoga</em> el sentido de poder que tiene en el «yoga soberano» de <a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a> y <a class=\"vref\" href=\"capitulo-11.html#v8\" data-v=\"11.8\">11.8</a>. Con este verso vuelve a hablar Kṛṣṇa, después de la larga plegaria de Arjuna (<a class=\"vref\" href=\"capitulo-11.html#v36\" data-v=\"11.36\">11.36</a>–<a class=\"vref\" href=\"capitulo-11.html#v46\" data-v=\"11.46\">11.46</a>); el metro sigue siendo la <em>triṣṭubh</em>, la estrofa de cuatro pies de once sílabas, hasta <a class=\"vref\" href=\"capitulo-11.html#v50\" data-v=\"11.50\">11.50</a>.</p>", "interp": [{"titulo": "«Que nadie antes que tú había visto»", "html": "<p>La frase plantea una dificultad conocida: el propio <em>Mahābhārata</em> cuenta, en el libro del Esfuerzo (<em>Udyoga-parvan</em>), que Kṛṣṇa mostró una forma universal ante la asamblea de los Kauravas, cuando fue como embajador de paz. La Gītā no se ocupa de ello (tampoco lo mencionan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> ni <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; Śrīdhara entiende «nadie que no sea un devoto como tú»; Prabhupāda responde que las formas mostradas entonces eran distintas de ésta): lo que subraya es que esta visión, con todo lo que Arjuna ha visto en ella, es un don hecho a él. Los dos versos siguientes y <a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a>–<a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a> lo explican: no hay técnica, rito ni estudio que la produzca.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 48, "hablante": "krsna", "sa": ["न वेदयज्ञाध्ययनैर्न दानैर्न च क्रियाभिर्न तपोभिरुग्रैः ।", "एवंरूपः शक्य अहं नृलोके द्रष्टुं त्वदन्येन कुरुप्रवीर ॥४८॥"], "iast": ["na veda-yajñādhyayanair na dānair na ca kriyābhir na tapobhir ugraiḥ", "evaṃ-rūpaḥ śakya ahaṃ nṛ-loke draṣṭuṃ tvad anyena kuru-pravīra"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Ni por el estudio de los <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a> y de los <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificios</a>, ni por dones, ni por ritos, ni por <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridades</a> terribles puedo ser visto en esta forma en el mundo de los hombres por nadie más que tú, oh Kurupravīra.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "part.", "es": "ni"}, {"iast": "veda-yajñādhyayanaiḥ", "sa": "वेदयज्ञाध्ययनैः", "gram": "instr. pl. n.", "es": "por los Vedas, los sacrificios y el estudio", "ref": "veda", "analisis": "veda + yajña (sacrificio) + adhyayana (estudio, recitación)"}, {"iast": "dānaiḥ", "sa": "दानैः", "gram": "instr. pl. n.", "es": "por dones", "analisis": "dāna (don, limosna), √dā (dar)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "kriyābhiḥ", "sa": "क्रियाभिः", "gram": "instr. pl. f.", "es": "por ritos, por obras", "analisis": "kriyā (acción, rito), √kṛ (hacer)"}, {"iast": "tapobhiḥ", "sa": "तपोभिः", "gram": "instr. pl. n.", "es": "por austeridades", "ref": "tapas"}, {"iast": "ugraiḥ", "sa": "उग्रैः", "gram": "instr. pl. n. adj.", "es": "terribles, severas"}, {"iast": "evaṃ-rūpaḥ", "sa": "एवंरूपः", "gram": "nom. sg. m. adj.", "es": "en esta forma", "analisis": "evam (así) + rūpa (forma)"}, {"iast": "śakyaḥ", "sa": "शक्यः", "gram": "nom. sg. m. gerundivo", "es": "puedo ser", "analisis": "√śak (poder)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "nṛ-loke", "sa": "नृलोके", "gram": "loc. sg. m.", "es": "en el mundo de los hombres", "analisis": "nṛ (hombre) + loka (mundo)"}, {"iast": "draṣṭum", "sa": "द्रष्टुम्", "gram": "inf.", "es": "ser visto, ver", "analisis": "√dṛś (ver)"}, {"iast": "tvad anyena", "sa": "त्वदन्येन", "gram": "instr. sg. m.", "es": "por otro que tú"}, {"iast": "kuru-pravīra", "sa": "कुरुप्रवीर", "gram": "voc. sg. m.", "es": "oh el más valiente de los Kurus", "analisis": "kuru + pravīra (héroe principal): Arjuna"}], "nota": "<p>La lista recorre los medios religiosos reconocidos: la palabra revelada y su estudio, el rito, el don y la austeridad. <a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a> la repetirá casi con las mismas palabras, para añadir en <a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a> lo único que sí abre el acceso. <em>Kuru-pravīra</em>, «el más valiente de los Kurus», es un vocativo de Arjuna que la Gītā sólo usa aquí. «Nadie más que tú» no compara a Arjuna con los ascetas: dice que la visión ha sido una gracia (<a class=\"vref\" href=\"capitulo-11.html#v47\" data-v=\"11.47\">11.47</a>, <em>prasannena</em>); <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> glosa «nadie que no tenga mi gracia», y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, «nadie sin devoción exclusiva».</p>", "interp": [{"titulo": "Lo que no abre la puerta", "html": "<p>El verso parece contradecir buena parte de lo enseñado: el sacrificio, el estudio y la austeridad se han presentado como caminos (<a class=\"vref\" href=\"capitulo-04.html#v25\" data-v=\"4.25\">4.25</a>–<a class=\"vref\" href=\"capitulo-04.html#v30\" data-v=\"4.30\">4.30</a>). Pero aquí se habla de algo preciso, ver la forma universal, y la Gītā la sitúa fuera del alcance de cualquier práctica: lo que el capítulo enseña es la gratuidad de la visión, que <a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a> vincula a la devoción exclusiva. La misma idea aparece en la <em>Kaṭha</em> (que <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> cita aquí) y la <em>Muṇḍaka Upaniṣad</em>: el sí-mismo no se alcanza por la enseñanza, la inteligencia ni el mucho oír, sino que se revela a quien él elige.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Ni por los Vedas, los sacrificios y el estudio, ni por dones, ni por ritos, ni por austeridades terribles puedo ser visto en esta forma en el mundo de los hombres por nadie más que tú, oh Kurupravīra.", "nota": "<p>El compuesto <em>veda-yajñādhyayanaiḥ</em> puede hacer de <em>adhyayana</em>, «estudio», el núcleo del que dependen los otros dos, como la traducción principal: «el estudio de los Vedas y de los (textos de los) sacrificios». Es la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: el estudio de los cuatro Vedas y el de los textos rituales (para Śrīdhara y Madhusūdana, los <em>Kalpa-sūtra</em>). La alternativa enumera tres cosas —los Vedas, los sacrificios, el estudio—, que la gramática también admite. El sentido de conjunto no cambia: ningún medio religioso produce la visión.</p>"}]}, {"n": 49, "hablante": "krsna", "sa": ["मा ते व्यथा मा च विमूढभावो दृष्ट्वा रूपं घोरमीदृङ्ममेदम् ।", "व्यपेतभीः प्रीतमनाः पुनस्त्वं तदेव मे रूपमिदं प्रपश्य ॥४९॥"], "iast": ["mā te vyathā mā ca vimūḍha-bhāvo dṛṣṭvā rūpaṃ ghoram īdṛṅ mamedam", "vyapeta-bhīḥ prīta-manāḥ punas tvaṃ tad eva me rūpam idaṃ prapaśya"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No tiembles ni te turbes al ver esta forma mía tan terrible. Libre de miedo y con el ánimo alegre, mira otra vez aquella misma forma mía: aquí la tienes.</span>", "palabras": [{"iast": "mā", "sa": "मा", "gram": "part. prohib.", "es": "no (haya)"}, {"iast": "te", "sa": "ते", "gram": "gen./dat. sg. pron.", "es": "en ti"}, {"iast": "vyathā", "sa": "व्यथा", "gram": "nom. sg. f.", "es": "temblor, angustia", "analisis": "√vyath (temblar, sufrir)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "vimūḍha-bhāvaḥ", "sa": "विमूढभावः", "gram": "nom. sg. m.", "es": "turbación, estado de confusión", "ref": "moha", "analisis": "vimūḍha (confundido, de vi-√muh) + bhāva (estado)"}, {"iast": "dṛṣṭvā", "sa": "दृष्ट्वा", "gram": "absol.", "es": "al ver", "analisis": "√dṛś (ver)"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "acc. sg. n.", "es": "forma", "ref": "visvarupa"}, {"iast": "ghoram", "sa": "घोरम्", "gram": "acc. sg. n. adj.", "es": "terrible"}, {"iast": "īdṛk", "sa": "ईदृक्", "gram": "acc. sg. n. adj.", "es": "tal, semejante"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mía"}, {"iast": "idam", "sa": "इदम्", "gram": "acc. sg. n. pron.", "es": "esta"}, {"iast": "vyapeta-bhīḥ", "sa": "व्यपेतभीः", "gram": "nom. sg. m. adj.", "es": "libre de miedo", "analisis": "vyapeta (ido, apartado) + bhī (miedo)"}, {"iast": "prīta-manāḥ", "sa": "प्रीतमनाः", "gram": "nom. sg. m. adj.", "es": "con el ánimo alegre", "ref": "manas", "analisis": "prīta (contento) + manas (mente, ánimo)"}, {"iast": "punaḥ", "sa": "पुनः", "gram": "adv.", "es": "otra vez"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "tat", "sa": "तत्", "gram": "acc. sg. n. pron.", "es": "aquella"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "misma"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mía"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "acc. sg. n.", "es": "forma"}, {"iast": "idam", "sa": "इदम्", "gram": "acc. sg. n. pron.", "es": "esta, aquí"}, {"iast": "prapaśya", "sa": "प्रपश्य", "gram": "2 sg. impv. act.", "es": "mira, contempla", "analisis": "pra-√paś (ver)"}], "nota": "<p><em>Tad eva … idam</em>, «aquella misma … ésta»: Kṛṣṇa anuncia que va a volver a la forma que Arjuna conocía, la que le pidió ver de nuevo en <a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>–<a class=\"vref\" href=\"capitulo-11.html#v46\" data-v=\"11.46\">11.46</a>. Cuál sea exactamente esa forma —la de cuatro brazos que Arjuna nombra en <a class=\"vref\" href=\"capitulo-11.html#v46\" data-v=\"11.46\">11.46</a> o la humana de <a class=\"vref\" href=\"capitulo-11.html#v51\" data-v=\"11.51\">11.51</a>— es una de las cuestiones del verso siguiente; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la identifican ya aquí con la de cuatro brazos, que para ellos es la que Arjuna veía siempre, y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, con «la forma apacible a la que estabas acostumbrado» (véase la ficha <a class=\"t\" href=\"glosario.html#caturbhuja\" data-t=\"caturbhuja\">caturbhuja</a>).</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 50, "hablante": "sanjaya", "sa": ["सञ्जय उवाच ।", "इत्यर्जुनं वासुदेवस्तथोक्त्वा स्वकं रूपं दर्शयामास भूयः ।", "आश्वासयामास च भीतमेनं भूत्वा पुनः सौम्यवपुर्महात्मा ॥५०॥"], "iast": ["sañjaya uvāca", "ity arjunaṃ vāsudevas tathoktvā svakaṃ rūpaṃ darśayām āsa bhūyaḥ", "āśvāsayām āsa ca bhītam enaṃ bhūtvā punaḥ saumya-vapur mahātmā"], "rojas": [], "t": "<span class=\"vt-parte\">Tras hablar así a <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Vāsudeva</a> le mostró de nuevo su propia forma; y, tomando otra vez su cuerpo apacible, el de <a class=\"t\" href=\"glosario.html#mahatman\" data-t=\"mahatman\">gran alma</a> consoló al que estaba aterrado.</span>", "palabras": [{"iast": "sañjayaḥ", "sa": "सञ्जयः", "gram": "nom. sg. m.", "es": "Sañjaya", "ref": "sanjaya"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. perf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "iti", "sa": "इति", "gram": "part.", "es": "así"}, {"iast": "arjunam", "sa": "अर्जुनम्", "gram": "acc. sg. m.", "es": "a Arjuna", "ref": "arjuna"}, {"iast": "vāsudevaḥ", "sa": "वासुदेवः", "gram": "nom. sg. m.", "es": "Vāsudeva", "ref": "krsna", "analisis": "vāsudeva (hijo de Vasudeva: Kṛṣṇa)"}, {"iast": "tathā", "sa": "तथा", "gram": "adv.", "es": "de este modo"}, {"iast": "uktvā", "sa": "उक्त्वा", "gram": "absol.", "es": "tras hablar", "analisis": "√vac (hablar)"}, {"iast": "svakam", "sa": "स्वकम्", "gram": "acc. sg. n. adj.", "es": "propia", "analisis": "sva (propio) + -ka"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "acc. sg. n.", "es": "forma", "ref": "caturbhuja"}, {"iast": "darśayām āsa", "sa": "दर्शयामास", "gram": "3 sg. perf. perifr. caus.", "es": "mostró", "analisis": "caus. de √dṛś (ver)"}, {"iast": "bhūyaḥ", "sa": "भूयः", "gram": "adv.", "es": "de nuevo"}, {"iast": "āśvāsayām āsa", "sa": "आश्वासयामास", "gram": "3 sg. perf. perifr. caus.", "es": "consoló, tranquilizó", "analisis": "caus. de ā-√śvas (respirar, recobrar el aliento)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "bhītam", "sa": "भीतम्", "gram": "acc. sg. m. part. pas.", "es": "aterrado", "analisis": "√bhī (temer)"}, {"iast": "enam", "sa": "एनम्", "gram": "acc. sg. m. pron.", "es": "a él"}, {"iast": "bhūtvā", "sa": "भूत्वा", "gram": "absol.", "es": "tras volverse", "analisis": "√bhū (llegar a ser)"}, {"iast": "punaḥ", "sa": "पुनः", "gram": "adv.", "es": "otra vez"}, {"iast": "saumya-vapuḥ", "sa": "सौम्यवपुः", "gram": "nom. sg. m. adj.", "es": "de cuerpo apacible", "analisis": "saumya (suave, apacible, propio de la luna) + vapus (cuerpo, figura)"}, {"iast": "mahātmā", "sa": "महात्मा", "gram": "nom. sg. m.", "es": "el de gran alma", "ref": "mahatman"}], "nota": "<p>Sañjaya vuelve a tomar la palabra, como en <a class=\"vref\" href=\"capitulo-11.html#v9\" data-v=\"11.9\">11.9</a> y <a class=\"vref\" href=\"capitulo-11.html#v35\" data-v=\"11.35\">11.35</a>. <em>Saumya</em>, de <em>soma</em>, la luna, es «apacible, suave», lo contrario de <em>ghora</em>, «terrible», con que Kṛṣṇa ha calificado su forma universal en <a class=\"vref\" href=\"capitulo-11.html#v49\" data-v=\"11.49\">11.49</a>. <em>Āśvāsayām āsa</em> es literalmente «le hizo recobrar el aliento». <em>Mahātmā</em>, «el de gran alma», es aquí Kṛṣṇa.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Tras hablar así a Arjuna, Vāsudeva le mostró de nuevo su propia forma, la de cuatro brazos; y luego, tomando otra vez su cuerpo apacible, el de gran alma consoló al que estaba aterrado.", "nota": "<p>El verso tiene dos verbos, «mostró» y «consoló», y dos expresiones para la forma: «su propia forma» (<em>svakaṃ rūpam</em>) y «su cuerpo apacible» (<em>saumya-vapuḥ</em>). La traducción principal las entiende como una sola: Kṛṣṇa vuelve a la figura que Arjuna conocía, la que en el verso siguiente llama «humana». Así leen <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, para quienes esa figura conocida, la del hijo de Vasudeva, tenía ya cuatro brazos. La alternativa, como Viśvanātha Cakravartī y Prabhupāda, las separa en dos momentos: primero la forma de cuatro brazos que Arjuna había pedido en <a class=\"vref\" href=\"capitulo-11.html#v46\" data-v=\"11.46\">11.46</a>, después la humana. Las dos construcciones son posibles. La primera es la de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien esa única forma, la propia de Kṛṣṇa, tiene cuatro brazos y figura humana; la segunda, la de Viśvanātha Cakravartī y Prabhupāda. <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> sólo advierte que se la llama «su propia forma» según la impresión común, pues también la universal es suya. Véase la ficha <a class=\"t\" href=\"glosario.html#caturbhuja\" data-t=\"caturbhuja\">caturbhuja</a>.</p>"}]}, {"n": 51, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "दृष्ट्वेदं मानुषं रूपं तव सौम्यं जनार्दन ।", "इदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः ॥५१॥"], "iast": ["arjuna uvāca", "dṛṣṭvedaṃ mānuṣaṃ rūpaṃ tava saumyaṃ janārdana", "idānīm asmi saṃvṛttaḥ sacetāḥ prakṛtiṃ gataḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Al ver esta forma humana tuya, apacible, oh <a class=\"t\" href=\"glosario.html#janardana\" data-t=\"janardana\">Janārdana</a>, ahora he vuelto en mí: he recobrado mi estado natural.</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. perf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "dṛṣṭvā", "sa": "दृष्ट्वा", "gram": "absol.", "es": "al ver"}, {"iast": "idam", "sa": "इदम्", "gram": "acc. sg. n. pron.", "es": "esta"}, {"iast": "mānuṣam", "sa": "मानुषम्", "gram": "acc. sg. n. adj.", "es": "humana", "analisis": "mānuṣa (humano, de manu)"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "acc. sg. n.", "es": "forma"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tuya"}, {"iast": "saumyam", "sa": "सौम्यम्", "gram": "acc. sg. n. adj.", "es": "apacible"}, {"iast": "janārdana", "sa": "जनार्दन", "gram": "voc. sg. m.", "es": "oh Janārdana", "ref": "janardana"}, {"iast": "idānīm", "sa": "इदानीम्", "gram": "adv.", "es": "ahora"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "estoy, soy"}, {"iast": "saṃvṛttaḥ", "sa": "संवृत्तः", "gram": "nom. sg. m. part. pas.", "es": "vuelto (en mí)", "analisis": "sam-√vṛt (volver, llegar a ser)"}, {"iast": "sacetāḥ", "sa": "सचेताः", "gram": "nom. sg. m. adj.", "es": "consciente, en mi juicio", "analisis": "sa- (con) + cetas (mente, conciencia)"}, {"iast": "prakṛtim", "sa": "प्रकृतिम्", "gram": "acc. sg. f.", "es": "a mi estado natural", "ref": "prakrti"}, {"iast": "gataḥ", "sa": "गतः", "gram": "nom. sg. m. part. pas.", "es": "ido, vuelto", "analisis": "√gam (ir)"}], "nota": "<p><em>Prakṛtiṃ gataḥ</em>, «he vuelto a la <em>prakṛti</em>»: aquí la palabra no es la naturaleza cósmica, sino el estado normal de uno mismo, el que Arjuna había perdido ante la visión (<a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>: «se me turba la mente de miedo»). <em>Mānuṣam</em>, «humana»: es la única vez que la Gītā llama así a la forma de Kṛṣṇa en boca de Arjuna; en <a class=\"vref\" href=\"capitulo-09.html#v11\" data-v=\"9.11\">9.11</a> Kṛṣṇa había hablado de su «cuerpo humano», despreciado por los necios.</p>", "interp": [{"titulo": "Volver a lo humano", "html": "<p>El capítulo no termina en lo sublime, sino en lo familiar. Arjuna ha pedido ver la forma universal y, cuando la ve, no la soporta; pide entonces que Kṛṣṇa vuelva a ser como era (<a class=\"vref\" href=\"capitulo-11.html#v45\" data-v=\"11.45\">11.45</a>–<a class=\"vref\" href=\"capitulo-11.html#v46\" data-v=\"11.46\">11.46</a>), y sólo al verlo de nuevo así recobra el juicio. La Gītā no presenta este retorno como una caída: la forma apacible es la del amigo con el que se puede hablar, y es en ella donde Kṛṣṇa ha enseñado todo lo anterior y seguirá enseñando.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 52, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "सुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम ।", "देवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः ॥५२॥"], "iast": ["śrī-bhagavān uvāca", "su-durdarśam idaṃ rūpaṃ dṛṣṭavān asi yan mama", "devā apy asya rūpasya nityaṃ darśana-kāṅkṣiṇaḥ"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Muy difícil de ver es esta forma mía que has visto: hasta los <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a> anhelan siempre contemplarla.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m.", "es": "el Señor bienaventurado", "ref": "bhagavan"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. perf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "su-durdarśam", "sa": "सुदुर्दर्शम्", "gram": "nom. sg. n. adj.", "es": "muy difícil de ver", "analisis": "su- (muy) + dur- (difícil) + darśa (que se ve)"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "esta"}, {"iast": "rūpam", "sa": "रूपम्", "gram": "nom. sg. n.", "es": "forma"}, {"iast": "dṛṣṭavān asi", "sa": "दृष्टवानसि", "gram": "2 sg. part. act. pas. + asi", "es": "has visto"}, {"iast": "yat", "sa": "यत्", "gram": "acc. sg. n. rel.", "es": "que"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mía"}, {"iast": "devāḥ", "sa": "देवाः", "gram": "nom. pl. m.", "es": "los dioses", "ref": "deva"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "incluso, hasta"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. n. pron.", "es": "de esta"}, {"iast": "rūpasya", "sa": "रूपस्य", "gram": "gen. sg. n.", "es": "forma"}, {"iast": "nityam", "sa": "नित्यम्", "gram": "adv.", "es": "siempre"}, {"iast": "darśana-kāṅkṣiṇaḥ", "sa": "दर्शनकाङ्क्षिणः", "gram": "nom. pl. m. adj.", "es": "deseosos de ver", "analisis": "darśana (visión) + kāṅkṣin (que anhela)"}], "nota": "<p><em>Idaṃ rūpam</em>, «esta forma», puede referirse a la forma universal que Arjuna acaba de ver o a la que tiene ahora delante, la apacible: el pronombre no lo decide. La traducción mantiene la ambigüedad del original; el contexto inmediato, que repite los medios inútiles de <a class=\"vref\" href=\"capitulo-11.html#v48\" data-v=\"11.48\">11.48</a>, apunta a la primera, y así lo entienden <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y Viśvanātha Cakravartī (Prabhupāda la refiere, en cambio, a la forma de dos brazos); <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> no lo precisa aquí, pero en <a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a>–<a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a> habla de la forma «tal como se te ha mostrado», la universal.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "solo-por-la-devocion"}, {"n": 53, "hablante": "krsna", "sa": ["नाहं वेदैर्न तपसा न दानेन न चेज्यया ।", "शक्य एवंविधो द्रष्टुं दृष्टवानसि मां यथा ॥५३॥"], "iast": ["nāhaṃ vedair na tapasā na dānena na cejyayā", "śakya evaṃ-vidho draṣṭuṃ dṛṣṭavān asi māṃ yathā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Ni por los <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a>, ni por la <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a>, ni por los dones, ni por el <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a> se me puede ver así, como tú me has visto.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "part.", "es": "no, ni"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "vedaiḥ", "sa": "वेदैः", "gram": "instr. pl. m.", "es": "por los Vedas", "ref": "veda"}, {"iast": "tapasā", "sa": "तपसा", "gram": "instr. sg. n.", "es": "por la austeridad", "ref": "tapas"}, {"iast": "dānena", "sa": "दानेन", "gram": "instr. sg. n.", "es": "por el don"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "ijyayā", "sa": "इज्यया", "gram": "instr. sg. f.", "es": "por el sacrificio, el culto", "ref": "yajna", "analisis": "ijyā (sacrificio, de √yaj)"}, {"iast": "śakyaḥ", "sa": "शक्यः", "gram": "nom. sg. m. gerundivo", "es": "puedo ser"}, {"iast": "evaṃ-vidhaḥ", "sa": "एवंविधः", "gram": "nom. sg. m. adj.", "es": "de esta clase, así", "analisis": "evam (así) + vidha (clase)"}, {"iast": "draṣṭum", "sa": "द्रष्टुम्", "gram": "inf.", "es": "visto, ver"}, {"iast": "dṛṣṭavān asi", "sa": "दृष्टवानसि", "gram": "2 sg. part. act. pas. + asi", "es": "has visto"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "me"}, {"iast": "yathā", "sa": "यथा", "gram": "adv.", "es": "como"}], "nota": "<p>El verso repite, ahora en el metro corto (<em>anuṣṭubh</em>), la lista de <a class=\"vref\" href=\"capitulo-11.html#v48\" data-v=\"11.48\">11.48</a>. La repetición prepara la afirmación del verso siguiente: lo que ninguno de estos medios logra, lo logra la devoción.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "solo-por-la-devocion"}, {"n": 54, "hablante": "krsna", "sa": ["भक्त्या त्वनन्यया शक्य अहमेवंविधोऽर्जुन ।", "ज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च परन्तप ॥५४॥"], "iast": ["bhaktyā tv ananyayā śakya aham evaṃ-vidho 'rjuna", "jñātuṃ draṣṭuṃ ca tattvena praveṣṭuṃ ca parantapa"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero por una <a class=\"t\" href=\"glosario.html#ananya-bhakti\" data-t=\"ananya-bhakti\">devoción exclusiva</a>, que no se vuelve a ningún otro, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, se me puede conocer así, ver en verdad y entrar en mí, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>.</span>", "palabras": [{"iast": "bhaktyā", "sa": "भक्त्या", "gram": "instr. sg. f.", "es": "por la devoción", "ref": "bhakti"}, {"iast": "tu", "sa": "तु", "gram": "part.", "es": "pero"}, {"iast": "ananyayā", "sa": "अनन्यया", "gram": "instr. sg. f. adj.", "es": "exclusiva, que no se dirige a otro", "ref": "ananya-bhakti", "analisis": "an- (no) + anya (otro)"}, {"iast": "śakyaḥ", "sa": "शक्यः", "gram": "nom. sg. m. gerundivo", "es": "puedo ser"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "evaṃ-vidhaḥ", "sa": "एवंविधः", "gram": "nom. sg. m. adj.", "es": "así, de esta clase"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "jñātum", "sa": "ज्ञातुम्", "gram": "inf.", "es": "conocido, conocer", "ref": "jnana", "analisis": "√jñā (conocer)"}, {"iast": "draṣṭum", "sa": "द्रष्टुम्", "gram": "inf.", "es": "visto, ver"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "tattvena", "sa": "तत्त्वेन", "gram": "instr. sg. n.", "es": "en verdad, tal como soy", "analisis": "tattva (la realidad, lo que algo es)"}, {"iast": "praveṣṭum", "sa": "प्रवेष्टुम्", "gram": "inf.", "es": "entrar (en mí)", "analisis": "pra-√viś (entrar)"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa", "ref": "parantapa"}], "nota": "<p><em>Bhaktyā tv ananyayā</em> repite casi a la letra <a class=\"vref\" href=\"capitulo-08.html#v22\" data-v=\"8.22\">8.22</a> (<em>bhaktyā labhyas tv ananyayā</em>), donde la Persona suprema «se alcanza con una devoción exclusiva». Los tres infinitivos —conocer, ver, entrar— forman una gradación: el conocimiento, la visión directa y la unión. <em>Praveṣṭum</em>, «entrar», tiene un paralelo en <a class=\"vref\" href=\"capitulo-18.html#v55\" data-v=\"18.55\">18.55</a>: «por la devoción me conoce tal como soy; y, conociéndome así en verdad, entra en mí (<em>viśate</em>) enseguida». Qué sea ese «entrar» —disolverse en él o llegar a su presencia— es uno de los puntos en que las escuelas del Vedānta se separan: <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo glosa «alcanzar la liberación», <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> «por identidad» y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> «alcanzarme como mi propia forma», una vez disuelta la ignorancia; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo entiende como alcanzarlo en verdad, y Vedānta Deśika precisa que es la experiencia plena de él tal como es, no la identidad; Viśvanātha Cakravartī admite que quien busca la liberación se funde en el brahman, pero también sólo por la devoción; Prabhupāda traduce «entrar en los misterios de mi comprensión».</p>", "interp": [{"titulo": "La única llave", "html": "<p>Después de negar por dos veces que los Vedas, el rito, el don o la austeridad den acceso a la visión (<a class=\"vref\" href=\"capitulo-11.html#v48\" data-v=\"11.48\">11.48</a>, <a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a>), Kṛṣṇa nombra lo que sí lo da. El capítulo de la forma universal desemboca así en la devoción, y prepara el capítulo 12, que empieza precisamente preguntando quiénes son los mejores conocedores del yoga: los que adoran a Kṛṣṇa con forma o los que meditan en lo imperecedero sin forma (<a class=\"vref\" href=\"capitulo-12.html#v1\" data-v=\"12.1\">12.1</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "solo-por-la-devocion"}, {"n": 55, "hablante": "krsna", "sa": ["मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः ।", "निर्वैरः सर्वभूतेषु यः स मामेति पाण्डव ॥५५॥"], "iast": ["mat-karma-kṛn mat-paramo mad-bhaktaḥ saṅga-varjitaḥ", "nirvairaḥ sarva-bhūteṣu yaḥ sa mām eti pāṇḍava"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien hace mis <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">obras</a>, me tiene por meta suprema y es mi <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoto</a>, libre de apego y sin enemistad hacia ningún ser, ése viene a mí, oh <a class=\"t\" href=\"glosario.html#pandava\" data-t=\"pandava\">Pāṇḍava</a>.</span>", "palabras": [{"iast": "mat-karma-kṛt", "sa": "मत्कर्मकृत्", "gram": "nom. sg. m.", "es": "el que hace mis obras", "ref": "karma", "analisis": "mad (mío) + karman (obra) + kṛt (que hace)"}, {"iast": "mat-paramaḥ", "sa": "मत्परमः", "gram": "nom. sg. m. adj.", "es": "que me tiene por meta suprema", "analisis": "mad (yo) + parama (lo supremo)"}, {"iast": "mad-bhaktaḥ", "sa": "मद्भक्तः", "gram": "nom. sg. m.", "es": "mi devoto", "ref": "bhakti"}, {"iast": "saṅga-varjitaḥ", "sa": "सङ्गवर्जितः", "gram": "nom. sg. m. adj.", "es": "libre de apego", "ref": "raga-dvesa", "analisis": "saṅga (apego) + varjita (privado, libre)"}, {"iast": "nirvairaḥ", "sa": "निर्वैरः", "gram": "nom. sg. m. adj.", "es": "sin enemistad", "analisis": "nis- (sin) + vaira (enemistad, hostilidad)"}, {"iast": "sarva-bhūteṣu", "sa": "सर्वभूतेषु", "gram": "loc. pl. n.", "es": "hacia todos los seres"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "eti", "sa": "एति", "gram": "3 sg. pres. act.", "es": "viene, llega", "analisis": "√i (ir)"}, {"iast": "pāṇḍava", "sa": "पाण्डव", "gram": "voc. sg. m.", "es": "oh Pāṇḍava", "ref": "pandava"}], "nota": "<p>Cinco rasgos en un solo verso: obrar para Kṛṣṇa, tenerlo por meta, la devoción, el desapego y la ausencia de hostilidad hacia cualquier ser. Los dos primeros recogen la enseñanza de la acción (<a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>: «ofreciéndome todas las acciones»; <a class=\"vref\" href=\"capitulo-09.html#v27\" data-v=\"9.27\">9.27</a>); el tercero, la de los capítulos 7 a 11; los dos últimos, la ecuanimidad del capítulo 2 y del 6. <em>Nirvaira</em>, «sin enemistad», dicho a un guerrero en vísperas de la batalla, separa la acción de la hostilidad: Arjuna ha de combatir, pero no odiar. Una fórmula muy parecida vuelve en <a class=\"vref\" href=\"capitulo-09.html#v34\" data-v=\"9.34\">9.34</a> y en <a class=\"vref\" href=\"capitulo-18.html#v65\" data-v=\"18.65\">18.65</a>.</p>", "interp": [{"titulo": "La esencia de toda la Gītā", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> introduce este verso como la esencia de toda la enseñanza de la Gītā, lo que conduce al bien supremo y ha de ponerse en práctica; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> repite la fórmula casi a la letra, y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo presenta como «la esencia de todas las escrituras, el secreto supremo». También Prabhupāda lo llama «la esencia de la Bhagavad-gītā». El verso cierra así la parte central del libro con una regla de vida, no con una doctrina.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Sin enemistad, en el campo de batalla", "html": "<p>El último rasgo es el más sorprendente en su contexto. Kṛṣṇa acaba de mostrar a Arjuna a los guerreros de los dos ejércitos entrando en sus bocas (<a class=\"vref\" href=\"capitulo-11.html#v26\" data-v=\"11.26\">11.26</a>–<a class=\"vref\" href=\"capitulo-11.html#v30\" data-v=\"11.30\">11.30</a>) y le ha dicho que sea sólo un instrumento (<a class=\"vref\" href=\"capitulo-11.html#v33\" data-v=\"11.33\">11.33</a>). Ahora pide que el devoto no tenga enemistad hacia ningún ser. La Gītā no ve contradicción: el deber de combatir no exige odiar, y la hostilidad es justamente lo que el devoto deja atrás.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "cinco-rasgos-del-devoto"}], "ensenanzas": [{"id": "el-ojo-divino", "desde": 5, "hasta": 8, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El ojo divino: lo que no se ve con los ojos de la carne", "resumen": "<p>A la petición de Arjuna, Kṛṣṇa responde mostrando: formas divinas a cientos y a miles, las clases de dioses, el universo entero reunido en su cuerpo. Pero advierte que nada de eso puede verse con los ojos propios: la visión es un don, y por eso le concede un ojo divino. El capítulo cerrará la idea por el otro extremo: esta forma no se alcanza con el estudio, los ritos ni la ascesis, sino con la devoción (<a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a>–<a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a>).</p>"}, {"id": "solo-el-instrumento", "desde": 32, "hasta": 34, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Sé sólo el instrumento", "resumen": "<p>Kṛṣṇa responde a la pregunta de Arjuna con su nombre más terrible: es el <a class=\"t\" href=\"glosario.html#kala\" data-t=\"kala\">tiempo</a> que destruye los mundos, y los guerreros enemigos no quedarán, con Arjuna o sin él (<a class=\"vref\" href=\"capitulo-11.html#v32\" data-v=\"11.32\">11.32</a>). De ahí saca una consecuencia práctica. Lo que va a ocurrir ya está decidido —«yo mismo los he matado de antemano»—, y a Arjuna sólo le toca ser el <a class=\"t\" href=\"glosario.html#nimitta\" data-t=\"nimitta\">instrumento</a> por el que se cumple (<a class=\"vref\" href=\"capitulo-11.html#v33\" data-v=\"11.33\">11.33</a>); por eso puede luchar sin angustia (<a class=\"vref\" href=\"capitulo-11.html#v34\" data-v=\"11.34\">11.34</a>). Es la forma más radical del yoga de la acción: obrar sin considerarse el autor de los resultados (<a class=\"vref\" href=\"capitulo-03.html#v27\" data-v=\"3.27\">3.27</a>–<a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>).</p>"}, {"id": "solo-por-la-devocion", "desde": 52, "hasta": 54, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Sólo por la devoción exclusiva se le puede ver", "resumen": "<p>Ni los Vedas, ni la austeridad, ni los dones, ni el sacrificio permiten ver a Kṛṣṇa como Arjuna lo ha visto: hasta los dioses lo anhelan sin lograrlo (<a class=\"vref\" href=\"capitulo-11.html#v52\" data-v=\"11.52\">11.52</a>–<a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a>). Sólo una <a class=\"t\" href=\"glosario.html#ananya-bhakti\" data-t=\"ananya-bhakti\">devoción exclusiva</a>, que no se vuelve a ningún otro, permite conocerlo, verlo en verdad y entrar en él (<a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a>). Es la conclusión del capítulo: la visión no se conquista con una práctica, sino que responde al amor.</p>"}, {"id": "cinco-rasgos-del-devoto", "desde": 55, "hasta": 55, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Cinco rasgos de quien llega a él", "resumen": "<p>Kṛṣṇa resume en un verso el camino entero: hacer sus obras, tenerlo por meta suprema, ser su <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoto</a>, vivir libre de apego y sin enemistad hacia ningún ser. Quien así vive llega a él (<a class=\"vref\" href=\"capitulo-11.html#v55\" data-v=\"11.55\">11.55</a>). Une la enseñanza de la acción ofrecida, la de la devoción y la de la ecuanimidad, y añade, en medio de una guerra, la renuncia a toda hostilidad.</p>"}]};
